/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20120925-6","meetingId":"h24-cm09","date":"2012年9月25日","dateIso":"2012-09-25","committee":"区民委員会","time":"午前１０時００分～午後 ０時３２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の伊藤学園プール温水運用および地域一般開放の取り止め","agenda":"の伊藤学園プール温水運用および地域一般開放の取り止め","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"幾つかお聞きしたいんですが、一つは、この電気消費量が多大で全電気使用料の４割を占めているとありますけれども、この４割というのは、年間の伊藤学園の使用料の４割なのか、それとも温水プールを使っている期間の４割なのかというのをまず教えていただきたいのと、それから、この２番のところで、平成２３年度には６カ所でいわゆる温水プールが使用できるということで。","respondent":"安藤文化スポーツ振興課長","answer":"ちょっとそれを先にご説明させていただきました。そして、まず１点目の４割の使用料というのは年間かどうか、これは学校全体の年間の使用料の４割です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"はい、わかりました。４年になるのか。最後のところで、学校側からの強い要請だったということなんですけれども、そうすると、その辺のところの兼ね合いとか、また、学校として、もうちょっと具体的に、なぜ中止したいんだと、それは学校ということは、ＰＴＡの意見だとか、そういう保護者の意見なんかも踏まえた上での学校の意見と受けとっていいのか、その辺はどうですか。","respondent":"安藤文化スポーツ振興課長","answer":"その段階で、当初、全天候型の屋上加温プールとして予定していたです。ですから、日野学園等の温水プールとしては予定していなかったと。ですから、加温ですので、少し夏場の暖かい時期の前後、そういう前後に利用ができるようなプールを予定していたというようなお話です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。今、私自身が、その方たちがこれを聞いたときにどう思うかというのはちょっと予測できないんですけれども、おそらく使った方からすれば、判断というか、利便性が損なわれたわけですから、これからしっかり説明されるということなので、本当にきめ細かくやっていっていただいた上で納得していただけるようなことをやっていただかなければいけないのかなと思っていて、一たんそこで要望として。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、それをするのにも構造上非常に難問がございまして、そのようなところで現在に至っているところです。なお、区民の皆さん、貸し切りの団体の皆さんには、丁寧にご説明させていただきたいと思っています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"本当に最初に計画を立てたときに、もうちょっとしっかり先まで考えて計画をされればよかったのになと、まず感想で思うんですけれども、それで、１番の2)で、この抜本的にやり直すには構造的に難しいという課長の答弁、説明をいただいていたんですけれども、これを抜本的にやる考えは全くないということなんですか。","respondent":"安藤文化スポーツ振興課長","answer":"大変恐縮ですけれども、学校のプールということで、学校サイドとしては、その考えは今のところないというふうに聞いています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"それと、３番目の光熱水費で先ほどの答弁で、１,１３９万円余ということなんですけれども、実際この中でもほとんどが電気代だと思うんですけれども、水道代というのはこのうちどのくらい占めるんですか。","respondent":"安藤文化スポーツ振興課長","answer":"電気使用料がそのうちの７７７万円余です。水道の使用料が２４２万８,０００円余、ガスの使用料が１１９万４,０００円余で、合計１,１３９万２,０００円余という計算がされてあります。","voiceIndex":16,"id":"exchange-006"},{"speaker":"本多委員","kind":"質問・要望","question":"この委員会が終わったら周知をされるということで、おそらく地域の方たちからは、すごい反響があるんだろうなと思っていたんですけれども、特にこの伊藤学園の施設利用については、なかなか地域の皆さんが納得していない部分がほかにもあると思うので、その辺はすごく心配だなと思うんですけれども、うまく、本当にその辺はよく配慮して決めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"山内委員","kind":"質問","question":"伺いたいのは、２枚目の一般開放で人数が書いてありますけれども、これは重複する方もいるという考え方でいいんですね。","respondent":"安藤文化スポーツ振興課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"山内委員","kind":"提案","question":"そうですね、わかりました。それが１点で、考え方なんですが、当初、温水プールにする予定はなく、結局やるということでいろいろ整備をした。今回やめるという決断をしたということは、ある意味、これは二重投資になっている部分があると思うんです。そして、そういう提案を地域振興事業部から提案をするとか、そういったことはなかったのかということをお伺いします。","respondent":"安藤文化スポーツ振興課長","answer":"我々もこの表を見て検討してまいりました。そんな中で、平成１８年度、先ほどご説明しましたように、３カ所で２５万３,０００人、最後、下の合計のところです。３カ所で２５万３,０００人です。","voiceIndex":21,"id":"exchange-009"},{"speaker":"山内委員","kind":"確認","question":"確認なんですが、この温水プールは、今、６カ所あって、料金は基本一律同じ金額でやっているということでよろしいのでしょうか。幾らでやっているのかちょっと教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"今現在、学校温水プールを含めて６カ所ありますけれども、すべて個人料金が３５０円、貸切料金も一緒でやってあります。","voiceIndex":23,"id":"exchange-010"},{"speaker":"山内委員","kind":"質問・要望","question":"今こういう考え方なんですが、例えば３５０円で伊藤学園を使えている。むだになるんですよ。ですから、そういったところもしっかりと今後施設をつくっていく中で、ちゃんと先読みをするというか、そういったところをしっかりとやっていただきたいなという思いがします。これは最後、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"品川学園がなぜ問題なのかちょっとわからないですけれども、近くに健康センターがあるからとかあるのかわからないですけれども、そういう中で、例えば１人当たりの電気使用料という考え方で行くと、そうすると、この八潮とか品川学園なんていうのも、もしかすると全体の使用料は４０％に行っていなくても、１人当たりというような考え方をすると、逆に伊藤学園と同じか。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、今後、場所的にもそんなに悪いところではないと思うので、徐々に品川学園のほうは伸びていくと思います。そして、１人当たりの電気使用料ですけれども、費用対効果を考えて、我々も今後進めていけたらというふうに考えています。","voiceIndex":26,"id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"やっぱり今後は、そういう１人当たりのということも含めて整合性を持っていかないと、ご説明いただいても、人によっては学校を見て、うちは高いけどほかと比べてどうなんだろうということで、その辺はしっかりそれも含めて丁寧なご説明をいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-013"},{"speaker":"井上副委員長","kind":"質問","question":"やっとできたというような地域の方の評価だと思うので、そこについて、区はやろうとしてやったのか、すごいニーズがあって、それに押されてやっぱりやりましょうという判断をしたのか、その辺の一番最初はどうだったんですか。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、あわせて地域開放ができるというふうにしていますので、初めから地域開放ありきで建設されたものではないというふうに理解しています。","voiceIndex":29,"id":"exchange-014"},{"speaker":"井上副委員長","kind":"意見","question":"ここでは、温水を中止しても、子どもたちでは５月、１０月でオーケーだということで、教育委員会の判断があったと思うんですけれども、今言われた光熱水費で電気代の部分で考えればいいというふうに思うんですけれども、水道代はどこのプールも一緒だし、ガスがちょっとどういうことなのかよくわからないですが、単純に電気代でいくと７７７万円余ということで、そうすると。","respondent":"安藤文化スポーツ振興課長","answer":"民間のプールですけれども、民間のプールについても、品川区では１２カ所ありますけれども、やっぱりこの民間のプールは、アスレチッククラブだとか、専門的なスポーツ団体の中にあって、会費制というんですか、そんな形で年間会費だとか、月会費だとか。","voiceIndex":31,"id":"exchange-015"},{"speaker":"井上副委員長","kind":"質問","question":"プール自体、区民の方が利用しているところで、これもあるからまあいいんじゃないでしょうかねみたいな表記では、もしそういうことであるならば、民間に比べてこのぐらいの料金で料金設定をというような視野になるために書かれているのかなと思ったんですけれども、そういうことではないということですね。","respondent":"安藤文化スポーツ振興課長","answer":"これは水泳の人口と申しましょうか、水泳を愛好する方々が、水泳を健康のために始めるところで、そういう活動の場所が品川区で幾つあるかということを示させていただきました。そんなことで１２カ所ありますということを示しています。","voiceIndex":33,"id":"exchange-016"},{"speaker":"井上副委員長","kind":"質問・要望","question":"私は、基本的には、今まで教育委員会のほうで学校の電気使用料の見直しというような視点がどの程度ここに反映されているのかが、ここは所管が違うのでわからないんですけれども、その電気、温水にするためのものについて、使用料の見直しをもし考えたとすれば、例えばここの伊藤学園だけでペイするためであれば、どのぐらいの料金にすればこのまま利用していただけるのかということと、さらには。","respondent":"安藤文化スポーツ振興課長","answer":"１点目の考え方と貸し切りも含むものについて、費用対効果と申しますか、光熱水費と、また使用料の考え方だというように理解しました。そんな中で、品川区では、資料に示したとおり６カ所のプールがあります。","voiceIndex":35,"id":"exchange-017"},{"speaker":"井上副委員長","kind":"質問","question":"７７７万円をどのぐらい上げたらできるのかとか、１回３５０円ではなくて、大体１回１,０００円ぐらいにならないとできないということであれば、そういうことを区民の方に投げたとしても、気持ち的には１,０００円でも続けますというような声があったとしても、結果、あけてみたら全然利用がなかったとかというのはよくありがちなことなんですけれども、でも、どのぐらいになるんでしょうか。","respondent":"安藤文化スポーツ振興課長、中川原地域振興事業部長","answer":"しかし、全体の使用料の考え方としては、今後、温水プールの施設を運営していく上で、貸し切り料金も含めて研究させていただきたいと思います。ですから、今後そちらの学校につきましては、利用者増と、それから、もしこのまま少ないのだったら、皆様方からご提案いただいたように、使用料を全体の一般開放の中で工夫したりとか、そういったこととして工夫はできるんですけれども。","voiceIndex":37,"id":"exchange-018"},{"speaker":"井上副委員長","kind":"質問・要望","question":"部長のおっしゃることはわかるんですけれども、使用料全体に見直しというところに今ちょっと方向が行ってしまっているので、私はそういうこと言っているわけではなくて、伊藤学園について、単純に２６万８,０００人の方が全員お金を払っているとか、そうではないのでわからないですけれども、これで１人１０円上げれば２６８万円というふうに考えれば。","respondent":"安藤文化スポーツ振興課長","answer":"１点目の考え方のいろいろシミュレーションしたかというお話ですけれども、今回も初めのとっかかりが、部長がご説明したように、伊藤学園の光熱費が高いというところから入ってきました。","voiceIndex":40,"id":"exchange-019"},{"speaker":"井上副委員長","kind":"質問","question":"文教委員会の議論もあるかと思いますけれども、ここで取りやめる予定であるということではなくて、こういうことを検討して、やめることありきでスタートしているなという、こういうふうに考えて、電気料の問題は初めからわかっていたことじゃないですか。全天候型で屋内プールでない温水プールを始めようといったときには、構造上かかるということはわかっていた。","respondent":"安藤文化スポーツ振興課長","answer":"今回、恐縮ではありますけれども、とりあえず区として伊藤学園の温水プールの温水はもう取りやめということで、一般開放の取りやめについてということで決定をさせていただきました。それで、つけ加えしますと、ご案内のとおり、学校の生徒も温水はすべて中止にするです。","voiceIndex":42,"id":"exchange-020"}]},{"id":"topic-02","title":"のプレミアム商品券発行事業への助成","agenda":"のプレミアム商品券発行事業への助成","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"プレミアムについては、私ども、非常にいい取り組みだと思っているんですけれども、正直これで景気がどこまで対策として効果、それがなかなか具体的なものとしては、ちょっと私どもつかみ切れないところが正直あるんですけれども、ただ、非常に関係者からの、また区民の方からの要望があるので、やっていただいているというのは非常にいいなと思っているんですけれども、ただ、実際、これを何回かやってみて。","respondent":"米田商業・観光課長","answer":"そういった意味では、いわゆる一定の金額が区内の商店街のほうに必ずお金が動くというようなことでの検証ということになろうかと思いますけれども、これまでもいろいろ関係者の方々のご要望等踏まえまして、現在も経済状況は厳しい状況ですので。","voiceIndex":51,"id":"exchange-021"},{"speaker":"武内委員","kind":"質問","question":"それはその方がそういうことを言って、実際どうなのかわかりませんけれども、そこは実態調査をやってもつかめない部分かもしれませんけれども、いずれにしても何かそういうことをやらないと、区内の景気対策、商店街振興ということで続けてきて、我々も賛成しているので、それは責任の一端を共有しているんですけれども。","respondent":"米田商業・観光課長","answer":"確かに完全にその辺のところを調べることは難しいかと思いますが、それをやられてしまうと、この商品券の事業自体が破綻してしまいますので、その辺のところは厳に各商店主の方に慎んでいただくというか。","voiceIndex":53,"id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"それとあと、今、ミニスーパーとおっしゃいましたけれども、スーパーの名前忘れた、名前はちょっと忘れちゃったけれども、まいばすけっとですか、そこもこれは使えるんでしたか。","respondent":"米田商業・観光課長","answer":"やはりその辺のところはプレミアム商品券の機会を生かした商店街独自の商売の仕方というようなことでは、中延のほうも比較的パーセンテージは高いものというふうに考えてあります。","voiceIndex":55,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"この間、取り扱っていますという商店に入ったら、「取り扱いやめちゃったの」と言われてびっくりしたという話を聞いて、当初の加盟店舗と今の状況というのは、増えているのか減っているのかを教えてください。","respondent":"米田商業・観光課長","answer":"そういった意味で、最近、２,２００店舗で使えるというようなことですし、この辺のところはほぼ横ばい、ただ、若干やりたいというところが少しずつ増えているというようなことは商店街連合会のほうから聞いてあります。","voiceIndex":57,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういった商店が増えていかないことには、このプレミアム商品券の意味がないなというふうに思うんですけれども、そういった増加させようとしたり、実質的な効果を上げるために改善してきたことは今まであるのでしょうか。","respondent":"米田商業・観光課長","answer":"これもなかなか難しい話ですけれども、我々、プレミアム商品券というものを使い始めて、その辺のところでやっていく中で、いろいろ商店街の方のお声とかを聞いているところです。","voiceIndex":59,"id":"exchange-025"},{"speaker":"井上副委員長","kind":"意見","question":"先ほど、特別助成分というところで、印刷費系の内容があったんですけれども、販売場所への何か取り扱い謝礼ではないですけれども、そういうものがこの中に入っているのか、いないのか、いるとしたら、どのぐらいの経費が使われているのかということと、先ほど、加盟店で換金手続が商店主さんの考え方で大変かもしれないということと、手数料の登録のことが。","respondent":"米田商業・観光課長","answer":"そうすると、基本的に残りの商店街の商店主さんについては取り扱いができないということにはなるんですが、個人的に一つの商店として商品券を取り扱いたいということになりましたときには、商店街連合会のほうに通常は加盟していないものですから。","voiceIndex":61,"id":"exchange-026"},{"speaker":"井上副委員長","kind":"意見","question":"その１冊８０円は、今、売れたらということの答弁だったみたいなので、預かりではなくて、売れたときに金額ということで、ほとんど完売ということだったので、そこは前もって預けるという仕組みなのかわからないですけれども、その辺は全部が売れているということになっていますか。","respondent":"米田商業・観光課長","answer":"こちらの商品券ですが、通常、かなり早期に完売しております。そうすると、その実績に基づいて、その各所で何冊売れたか、それで１冊当たり８０円の販売手数料をそちらの取扱事業者にお渡しするということの内容になってあります。","voiceIndex":63,"id":"exchange-027"},{"speaker":"井上副委員長","kind":"質問","question":"１冊８０円のその手数料というのは妥当なんですか。何かどうかなと思うんですけれども、その辺はどういう算出根拠でされているんですか。","respondent":"米田商業・観光課長","answer":"一般的に郵便局で物事を仲介するときには、郵便局は、いわゆる率にすると０.８％の率なんですけれども、そういう０.８％の率での取り扱いは基本的に郵便局はしないというような流れになっているようですが、品川区の郵便局が一体となって品川区の各商店街、商店と連携しながら。","voiceIndex":65,"id":"exchange-028"}]},{"id":"topic-03","title":"の高齢者の消費者被害防止に向けた地域での見守り","agenda":"の高齢者の消費者被害防止に向けた地域での見守り","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"「銀行に預けていた２００万円の定期預金が」というところから、「銀行を信用していたのに生命保険の証券が送られてきてびっくりした」という相談例だったと思うんですが、一つだけでいいので、こういう相談を受けて、消費者センターはどういう解決に向かって動いたのか、どういう結果になったか教えていただけますか。","respondent":"米田商業・観光課長","answer":"銀行の方も、営業の方と、それからその上司の方、数人でいらっしゃって、きちんと説明して、書式も整ってやったはずなんだけれども、そういうふうに考えられているとすれば非常に不本意だというようなことではありましたが。","voiceIndex":72,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"消費者センターが入って、そういうふうに契約が誤解を受けないようにやり直してくれたということなので、今後も消費者センターにはいろいろな例が来ると思うんですけれども、やっぱり消費者センターを強化して、その辺も法律に基づいて、法律を担保にどんどんやれることはやっていっていただきたいと思うんですけれども、その辺に関して、担当の課長として消費者センターをどういうふうに今後考え。","respondent":"米田商業・観光課長","answer":"本当になかなか全部が全部解決に向かうようなものではなく、調整に入ってもうまくいかないというものもある中では、最近の傾向といたしましては、この高齢者もそうなんですけれども、１件当たりのいわゆる対応時間が非常に長くなっているということがあります。","voiceIndex":74,"id":"exchange-030"},{"speaker":"山内委員","kind":"質問・要望","question":"やはりこの品川でもそういった相談があるかちょっとわからないんですけれども、そういったことがあるという例を伺ったので、そういった意味で、こういう高齢者を守るといった意味で、やはり区のほうからそういった周知もちょっとしていただきたいなという要望があるんですけれども、もし何かあったら。","respondent":"米田商業・観光課長","answer":"そういう機会だったり、あるいは、今、区のホームページにもありますが、品川区の職員を名乗るうその電話がかかっておりまして、それで高額医療費の払い戻しがある等を言って、結局ＡＴＭを操作させて、その金額を振り込ませるというような手口もありますので。","voiceIndex":76,"id":"exchange-031"},{"speaker":"武内委員","kind":"意見","question":"第二庁舎の３階の奥のほうに、前、環境情報活動センターがあって、今はあそこは消費者関係の部屋になっていると思うんですけれども、あそこは位置づけとしては消費者センターとはまた別なんでしょうけれども、例えば相談とか、啓発が主だと思うんですけれども、あそこの位置づけというのはどうなっているかということと、活動内容とか、また消費者センターとの連携、その辺を。","respondent":"米田商業・観光課長","answer":"その他、あと最近、私どものほうでも、先ほども申し上げました、いわゆる話を掲載していくというだけではなく、実際にそこで消費生活の教室を開くというようなことも行っておりますので、その辺のところ、消費者センターの啓発展示室で実施して。","voiceIndex":78,"id":"exchange-032"},{"speaker":"武内委員","kind":"質問・要望","question":"消費者センター自体は４階なので、あんまり目立たないので、こういう啓発をしていただいて、またいろいろな方をつないでもらえば、連絡をとってもらってできるんですけれども、なかなかそういうのが行き届かない方は、区役所に来たときにあそこにそういう啓発のものがあると、そこに行けば、そこからつないでもらうとか、そこでいろいろな啓発を見て、ああ、気をつけなければとなると思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"やっぱり町会とも、それと民生委員さんとも、なかなか交流のない高齢者もたくさんいると思うので、やはり区としてこういったことを本当に防いでいくというところでは、もうちょっときめ細かな対応が必要だろうなと思うんですけれども、いかがでしょうか。","respondent":"米田商業・観光課長","answer":"そういうことをまた考えながら、消費者センターとして悪質商法にだまされないためにどのような手段が適切なのかということは考えてまいりたいと思いますが、やはり高齢者の方々の周りにいる方々が、ひとりぼっちにさせないで。","voiceIndex":81,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"出前講座というのは、結構すぐに来てもらえる、簡単にというか、気軽なものなんでしょうか。","respondent":"米田商業・観光課長","answer":"それについては特に費用はかかりませんということで行っておりますが、原則としては、ある程度日程調整も必要ですので、一応１カ月前にお申し出いただければというようなことでやっておりますが、その辺はある意味、柔軟な対応もとることはできると思ってあります。","voiceIndex":83,"id":"exchange-035"},{"speaker":"本多委員","kind":"質問","question":"２枚目のしなかんＰＬＡＺＡなんですけれども、平成２３年度の実績で、来館者が２,５１１人、あまり数字が伸びていないと思うんですけれども、大体１日何人ぐらいでしょうか。","respondent":"米田商業・観光課長","answer":"全体の数字で行くと２,５００人ということなんですけれども、実際のところ、１日にならしますと１０人から２０人の間ということで推移しています。この辺のところは、なかなか数字の伸びとしては見られないというようなことが開所当初から続いてあります。","voiceIndex":90,"id":"exchange-036"},{"speaker":"本多委員","kind":"質問・要望","question":"その次なんですが、こだわりグッズで、平成９年から始めているサンリオ関係ですけれども、事業を始めた当初はすごく周知が広まって売り上げも伸びたと思うんですが、最近この売り上げが非常に低迷しているなと思うんですけれども、いろいろな事業を見ていると、始めたもので一番長いもので平成９年とか、平成１０年ですけれども、工夫というか、新たに肉づけをしていかなければいけない。","respondent":"米田商業・観光課長","answer":"そういった中では、ほかにも品川の海苔ですとか、あるいは品川巻きですとか、あるいはおそばですとか、たくあんですとかということで、しながわ観光協会のブランドとして展開しているところではありますが、それとあわせて、品川の名物を、これは食べ物に限らないと思いますが。","voiceIndex":92,"id":"exchange-037"},{"speaker":"本多委員","kind":"意見","question":"この全体を通して、いろいろ観光協会とか、品川区や港区のホテルが相当連携されているのは承知しているんですけれども、旅行会社とのタイアップとか連携というのは、どのぐらいまで進んでいるものなのか。","respondent":"米田商業・観光課長","answer":"旅行会社持ち込みの企画でしながわ観光協会が事業を起こそうというようなことでの検討もしているというようなことも伺っておりますし、特に品川・大田の連携事業の中では、大田区のほうが比較的旅行会社と連携した取り組みを進めているということもありまして、連携事業の中で。","voiceIndex":94,"id":"exchange-038"},{"speaker":"武内委員","kind":"確認","question":"一つは確認です。観光課ができましたので、それで観光協会があって、観光課ができて三、四年ぐらい。それで、これまでの総括というか、観光課ができたことで、観光行政がどう進んだか、観光協会との連携など、今もそうなんだけれども、そこの総括みたいなところの中で、よかった点、また課題があれば教えてもらいたい。それをどう位置づけているのか教えてください。","respondent":"米田商業・観光課長","answer":"その辺は観光協会の取り組みとあわせまして、基本的には後方支援というような形では考えておりますが、また前面に出ていくときには前面に出ていきつつ、今後とも品川区の商業・観光課としての役割を果たしてまいりたいと考えているところです。","voiceIndex":96,"id":"exchange-039"},{"speaker":"武内委員","kind":"質問・要望","question":"なかなかふだんあまり自分たちで調査できないんですけれども、観光課ができて、今までよりもやっぱりこういう点とこういう点とこういう点が重点的、今まではなかったということよりも、前進したんだよというものが多分あると思うので、またそれはぜひつかんでおいていただきたいのと、あと、そういう面では、例えばいわゆる区内の観光の表示みたいなもので、いろいろな看板があって。","respondent":"米田商業・観光課長","answer":"そういうものをご指摘を踏まえまして、よりよい情報発信の方法、事業の組み方、しながわ水族館との連携、この辺のところをまた考えてまいりたいと思います。","voiceIndex":98,"id":"exchange-040"},{"speaker":"井上副委員長","kind":"質問","question":"1)のほうで、こちらの観光資源、補助金なんかを利用するときは、区を通してというお話しだったんですけれども、これは、単費なのか、補助金が入った事業なのかというのを、平成２３年度で結構なので、どういう割合になっているのか教えてください。","respondent":"米田商業・観光課長","answer":"平成２３年度につきましては、特に補助事業等がございませんでしたので、基本的に区の単費でやっているというふうにお考えいただければと思います。","voiceIndex":100,"id":"exchange-041"},{"speaker":"井上副委員長","kind":"質問","question":"２枚目のほうで、しながわ観光協会の事業ということなんだけれども、この辺にも、運営費の９００万円の中に入っているのかよくわからないんですけれども、この辺の事業というのは、観光協会の予算というのがあると思うんですけれども、それですべてやっているということなのか、ここに品川区として事業助成ということで単品で入るのか、それとも全体運営費という形で入って補助金という形になっているのか。","respondent":"米田商業・観光課長","answer":"１点だけ、機内ガイドブック記事掲載パンフレット作成というものが下から６番目になりますけれども、こちらは区の単独で、協会とは一応連携はしているんですが、区の単独でやっておりますが、それ以外のものについては、協会なり。","voiceIndex":102,"id":"exchange-042"},{"speaker":"井上副委員長","kind":"提案","question":"どういうふうにここを分けているのか、事業提案が、観光協会があって、その事業に対しての補助をするという関係なのか、区がここの事業を企画をして、じゃあ、担い手として観光協会やってくださいねというふうに、そういうふうなことが増えていくと、観光協会の独立性というか、自前でやっていくというようなことがどんどん減っていく、区に頼り過ぎてしまうというのは。","respondent":"米田商業・観光課長","answer":"実際これでやってうまくいったねというようなことがあれば、例えば今年度やっております夏休み子ども水辺探検隊のように、もうすべて観光協会でやりましょう、そうすると、あまりもうけるわけにもいきませんけれども。","voiceIndex":104,"id":"exchange-043"},{"speaker":"井上副委員長","kind":"質問","question":"ただのものでずっと続けたら、次、有料になったら絶対参加しづらくなるので、そういうところはお金を入れるだけではなく、その先の拡大につながるような視点を持ってやっていくべきだというふうに思うんですけれども、その辺はどうでしょうか。","respondent":"米田商業・観光課長","answer":"そういった取り組みが、いわゆる区の経費の見込みがなく進めば、それはそれで望ましいとは思いますが、その辺のところの兼ね合いは、いろいろな事業、事業によって変わってまいりますので、見極めつつ判断してまいりたいと思ってあります。","voiceIndex":106,"id":"exchange-044"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"武内委員","kind":"質問","question":"この中に出てきていますが、外国人の、南の玄関口と言うぐらいですから、外国人、特にアジア地域、韓国とかに近い立地条件の中で、外国人を、たしか年間１０万人という目標を立てて、１０万人を鹿児島に呼びこもうという中で、結果として５万人ぐらい、その辺のほかの数は比較的達成されている、だけど、外国人をあれするのが結果として半分ぐらいの数字になっていたので、その辺の難しさというか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2648#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":47352,"voices":131}},{"id":"h24-20120925-7","meetingId":"h24-cm09","date":"2012年9月25日","dateIso":"2012-09-25","committee":"厚生委員会","time":"午前１０時００分～午後３時２８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「品川区おたがいさま運動」標語募集結果","agenda":"「品川区おたがいさま運動」標語募集結果","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"これはこれで非常にあれなんですが、お聞きをしたいのは、こういう標語を募集するとき、例えばこれは小学生の部とか中学生の部があるんですが、学校というか教育委員会にはどういうふうにアプローチをかけているのか教えてほしいんです。","respondent":"原高齢者福祉課長","answer":"そういった中で、すべての学校ではございませんけれども、学校の中で応募いただいたということで、結果としてこういうような審査をさせてもらったという状況です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"でも、これだと７月１１日からだと、もう限りなく夏休みに近いから、短期間だったのかななんて思いますけれども、ぜひこういうのは教育委員会を通じて、１００人とかいうレベルじゃなくて、もっと声をかければ、もうちょっと協力的に、子どもたちにはいろいろそういうのが宿題であってもいいと私は思うんだけれども、そういう担任の先生とかとも連絡をとって、子どもたちにしっかりそういうものを区内で。","respondent":"原高齢者福祉課長","answer":"こういった標語の募集の結果ですので、この結果を学校のほうにも十分にお知らせする中で、今度この標語を各学校で考えていただきながら行動に移してもらうような形を、教育委員会とも相談しながら進めていければと考えているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"意見","question":"今のは私も同じ気持ちなので、そういう機会を増やすには、やってくれない学校とか、それはどういうふうになるのかわからないけれども、子どもたちだって、その中で出てくるという子どもはこのくらいの数になっちゃうのかなと思っているので、そういう勉強の機会も含めて、子どもたちに教育の部分をもっとやるのであれば、それは教育の一環だから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"要するに、毎年時期は多少変動があったんですけれども、こういう時期に毎年の恒例行事にしたいということなのか、今後の見通しを伺いたいのと、あと、今、高齢者福祉課が所管しているということですけれども、例えばまちづくりやバリアフリーとなれば、ハード部隊もあるわけです。今、伺ったように、子どもたちに考えていただきたいとなれば教育委員会もあるわけで、また高齢者や障害者はみんな町の一員だと。","respondent":"原高齢者福祉課長","answer":"こういった中に、このおたがいさま運動があります。そこのおたがいさま運動で取り出したところは高齢者福祉課ということで、事務局を務めて実施しているという経過です。","voiceIndex":10,"id":"exchange-004"}]},{"id":"topic-02","title":"平成２３年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"平成２３年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"これは初めて私が伺う内容なので、基本的なことを伺いたいと思います。この総括シートというのは、それぞれの事業部か、施設の指定管理者なのか、どこがつくるのかということと、この経営会議なんですけれども、これがいつどのような形で、どれぐらいの時間で行われているものなのかを教えてください。","respondent":"原高齢者福祉課長","answer":"およそ年間の流れというものがございまして、それは１年の指定管理ということではなく、基本は５年ということですから、５年の中で１年を第１回といったことで実施をしていくような仕組みです。","voiceIndex":20,"id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。今ので大分この経営会議のコメントの内容が何となくわかったというか、納得というか承知をいたしましたけれども、いわゆる経営会議において、要するに場合によってはいろいろ厳しい評価が出ると、この指定管理を見直すとかいうところまで行ってしまうところもあり得る会議と、非常に高い権限を持った会議という捉え方でよろしいでしょうか。会議が強い権限を持つか。","respondent":"早津健康福祉事業部長","answer":"直ちに指定管理者を変えるとか云々ということになるか、あるいは指定管理者のやり方を強力に指導するという場合もあろうかと思います。それは施設の性格などを総合的に判断してということになりますが、ここで下された結論というのは、そういう意味では重いものだです。","voiceIndex":24,"id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"事業計画書であったり、６月の報告書だったり、その後の概要を教えていただけると、またその状況がわかるのではないかと思うんですけれども、そこを伺いたいと思います。それと、共通する基本的な考え方を伺いたいんですけれども、その管理運営委託費というのは、それぞれどういうふうに歳出されるのか。","respondent":"原高齢者福祉課長","answer":"そういう意味で、６月等で事業計画等々が出てまいりますけれども、指定管理をお願いする品川区としてそういったものを評価し、またそうしたものが区民サービスにどう活用されていくのか、あるいは課題はどういったところにあるのかというところを。","voiceIndex":26,"id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それの違いがちょっとよくわからなかったので、改めて伺いたいと思います。今回の総括シート全体の特徴をどうとらえているのか伺いたいと思ったんですけれども、例えば特別養護老人ホームなどを見ると、いわゆるショートステイがどこも利用率１００％を超えておりまして、利用者からするとなかなかとりにくいという状況がここにあらわれているのかなと思うんですね。","respondent":"原高齢者福祉課長","answer":"ただ、そうは言いましても、全体的な評価と、それから個々の施設の中である課題といったところは、それぞれ分けながら、その課題に対してはどのように対応するかというところを浮き彫りにしながら、さらに区民サービスの向上に努めてもらうというところを。","voiceIndex":28,"id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"特徴として、全体的に私が見て思ったのは、やはり東日本大震災を受けまして、防災訓練だったりそのための計画づくりだったり、いろいろ進められているのかなと全体を見て思ったんですけれども、一方で、やはりそこに苦労も施設ごとにあるのかなと思いまして、なかなかその状況が総括シートそのものからは読みとれないなという感じは常にするんですけれども。","respondent":"原高齢者福祉課長、永尾障害者福祉課長、江部健康課長","answer":"それを検討する中で、こういう場合はどうするんだという課題が出てまいりますので、その課題を、今、防災課と話をしながら調整するという段階です。保守点検の管理会社の方や、あと品川総合福祉会館には専門の技術者もおりますので、その方たちに逐次報告をうけ。それで、今回３５０万円返還をしたという点につきましてですが、これは教室返還金とありますが。","voiceIndex":30,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"けれども国はあれを求めているんだろう。ああいう小規模多機能像、在宅。今日、在宅支援というのがあるから、ここで言うべき話でもないかもしれないけれども、国は在宅支援ではああいう小規模多機能を求めているんだろうと、それぐらいまで私も思ったし、皆さんも多分思っている部分もあると思う。それでやはり利用率を上げていくということが１つだと思っていて、もし限界があれば教えていただきたい。","respondent":"原高齢者福祉課長、永尾障害者福祉課長、江部健康課長","answer":"そういった意味では、この小規模多機能というものを家族の方、あるいはケアマネジャーを含めた援助側のスタッフに対しても十分周知を図り。心身障害者福祉会館の修繕の関係ですけれども、現在大きいものについて、例えば建物の躯体に関係するものとして、トイレの改修だとか機械浴槽の改修だとか。健康センターの貸しホール等の収入、利用料についてのお尋ねですが、品川健康センター側に７階に貸しホール。","voiceIndex":34,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"別の機会でやりますけれども、いろいろ法的な部分もあったり、例えばグレーゾーンの部分もあるけれども、それは区でどうしろって行政でやれということではないけれども、現実的にデイサービスのお泊まりサービスだって、結構大きな規模であったりとか、それはいろいろな部分があって、もちろん東京都もあって国もある。これぐらいにしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-011"},{"speaker":"向委員","kind":"質問・要望","question":"私が気になったのが、全体的にやはりいろいろな利用者の方からのご意見とか、改善にどうつなげていくかというのを、すごく大変な思いをされているなというのはこれからもよくわかったんですが、ちょっと文言で違和感があったのが、１１ページの業務改善のための肥やしで、細かいことなのかもしれないんですけれども、いろいろ、今、民間企業とかでもすごくカスタマーサポートのこととか。","respondent":"原高齢者福祉課長","answer":"そういったところは朝礼とかそういう中で、やはり職員は褒められて伸びる場合も多くありますので、そういったことをきっかけにしながらさらにサービス向上に努めていくための方策として、朝礼等を使っているです。","voiceIndex":40,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"そういうふうにしなくてはいけないと思うと、例えばここには平成２１年から出ていますけれども、こういった継続的にいわゆる課題として、ここで言うと改善が必要とされた原因の分析とかいう言葉遣いがされていますけれども、こういうのが果たしていっぱい指摘があって、また次年度、次年度でクリアできなければその次の年度とか、そういう継続した視点というのは。","respondent":"原高齢者福祉課長","answer":"それからもう一つは、災害というその事象事象に合ったきっかけをもとにもう一回見直しをし、足りない分については改善をしていくということで、戸越台特別養護老人ホームなどについては、ＢＣＰとあわせて。","voiceIndex":42,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"一方、今、改善の点でしたけれども、例えば各施設、特別養護老人ホームでもサービスセンター等でも、いろいろ積極的に評価をするところがありますけれども、こういった部分の、逆に今度横の広がり、いいものは取り入れていく、改善すべきはみんなでも気をつけていく、その横の広がりというか連携はどういう仕組みになっているのか、既にお話があった中で理解もするんですが。","respondent":"原高齢者福祉課長","answer":"こういったモニタリングの結果と、先ほどそのほかにもご利用者の満足度ということで、施設であれば施設ごとのサービス向上委員会というのを、これは特別養護老人ホーム、老人保健施設、それからケアホーム含めての施設長が集まって。","voiceIndex":44,"id":"exchange-014"}]},{"id":"topic-03","title":"では、報告事項(3)、障害者虐待防止の取り組み","agenda":"では、報告事項(3)、障害者虐待防止の取り組み","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"この取り組みについて、もう少し伺いたいんですけれども、このしながわ見守りホットラインの設置ですけれども、この専用ダイヤルというのは、開設の時間は何時から何時なのか、それとも２４時間なのか、要するに時間と、それとこの受付の体制というんでしょうか、どういう資格のある人といいますか、そこの体制をご説明いただきたいと思います。一時的に距離をとるというか、そういう保護も必要だと思います。","respondent":"永尾障害者福祉課長","answer":"ですので、やはり関係機関、施設もそうだし関連している施設や、また区のケースワーカー、また生活支援センターの職員、それぞれの役割が発揮できる人たちと丁寧な打ち合わせ会議を行いながら、時間をかけてカンファレンスしていくような感じのことをしていかないと。","voiceIndex":52,"id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問","question":"やはり例えば障害者手帳を交付したときに、品川区の障害者福祉のしおりをどのように周知配布をされているのか、そのときだけでなく、日常的にどういうアプローチをしているのか、虐待につながる前の芽をしっかりキャッチしていく取り組みがとても大事になってくるのかなと思うんですけれども、手帳交付のときや、また日常の事業の取り組みの中で、現状を伺いたいと思います。","respondent":"永尾障害者福祉課長","answer":"１月には区民の方向けの講演会を予定しておりますので、そういうところから区民の方々に浸透させていきたいと考えております。最初に障害者手帳を交付したときの説明の内容につきましては、しおりは、一番最初に手帳を交付したときに全員にお配りしています。","voiceIndex":54,"id":"exchange-016"},{"speaker":"中塚副委員長","kind":"質問","question":"やはり精神障害のお子さんをお持ちのご家族の方に聞くと、家族の方も障害に対する理解も乗り越えなきゃいけない、わからなきゃいけない、受けとめなきゃいけない部分もある一方で、周りの方の理解もすごく大切だという話もよく伺いますので、いろいろな機会をとらえていろいろ広報活動しておりますけれども、今後の取り組みについての方向を改めて伺いたいと思います。","respondent":"永尾障害者福祉課長","answer":"高齢者に比べますと、やはり障害者のほうはまだまだというところはあります。それで、平成２４年４月の法律の改正によって、指定特定相談支援センターというのが新たにできて、高齢者に近づけていこうというような取り組みが始まっているところです。","voiceIndex":56,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私が全然理解していないので教えていただきたいんですが、６月に設置された品川区虐待防止ネットワーク推進協議会というのは、具体的にどういう組織体になっていて、具体的に今の段階では何を目的として行おうとして、何を具体的にやっているのかというのを教えていただきたいと思うのが１つ。個人情報もその部署は見られるというふうに、そこはその係がしっかり見ればいいんだから。","respondent":"永尾障害者福祉課長、原高齢者福祉課長","answer":"虐待防止ネットワーク推進協議会ですけれども、平成２４年度６月に、区としてやはり１本で対応していったほうがいいという考え方に基づきまして、児童、高齢者、また配偶者暴力。ただ、このかかわりは１回確認をしてそう言わなかったから、はい、それで終わりということではなく、継続的に情報収集等、緊急性をまず判断して、その後情報の収集を継続的に実施して、経過を見て、また関係者が集まって。","voiceIndex":58,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"障害者福祉課専用ダイヤルは、括弧づけじゃないですか。だからここの係というのか、これは誰が受けてどうするのか。ＤＶなんて、これは夫婦間だったり何なりすると、誰がどういうふうに来るかなんてわからないじゃないですか。啓発だったら、こうというのがあったほうが私はいいと思うんだけれども、そこら辺の何か、ここの説明でもそういうのがよくわからないなと思っていて、そこら辺を教えてほしい。","respondent":"原高齢者福祉課長","answer":"それからＰＲについては、区内に走ります私どもの庁有車に、今、言った番号を高齢者の部分、ＤＶ、子どもの部分ということで番号を表示して、そこに電話をすればつながるということと、それから間違って例えば高齢者福祉課のほうにＤＶの話が来る場合もありますけれども。","voiceIndex":61,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ、これはお願いしておきます。人件費をかけろとは言いません。それ用に１人置けとも言いません。それは物の考え方であって、電話の鳴り方を変えたっていいわけじゃないですか。私はそんなに毎日その電話が鳴るとも思えないわけで、そうすれば、例えばフリーダイヤルでもいいんだけれども、何でも、今、電話の鳴り方だけでも変わるじゃないですか。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これ、２の２）の1)に「虐待被害者の一時保護のための居室の確保」と書いてあるんですけれども、例えば児童虐待だったら家庭あんしんセンターだとか、あるいはお年寄りだったらいろいろ老人施設とかがあると思うんですけれども、障害者というのはまたちょっと違いますから、特殊ですから、じゃあ、具体的に実際これは障害者に関連した虐待が発見されたときに、一時避難ってどこにされるんですか。","respondent":"永尾障害者福祉課長","answer":"やはりそれぞれの特性がありますので、障害者の支援のできる職員がいないと一時保護は難しいかなと考えております。具体的な場所については、やはりこの性質上、公表ができないというような状況になっております。そういう場所については確保をしているところです。","voiceIndex":64,"id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"１０月１日からの施行を前に、いわゆるこの障害のある方への虐待について、品川区内の現状について、まずお知らせいただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"年に１件か、せいぜい２件ぐらいの話になっています。それで、やはり入ってくる情報としては、やはり民生委員だとか、あと家族の中でのものもありますので、ご家族やご本人からの訴えですね。","voiceIndex":66,"id":"exchange-022"},{"speaker":"若林委員","kind":"質問","question":"そうすると、今度新しく2)とか3)、いわゆる施設の従事者、それから障害者の会社、企業関係ですね。身近な区でされたほうがいいんじゃないかなというのが一つ、ちょっと感じとして持ちましたので、それを一つお聞きしたいのと、それぞれ2)、3)についても、これも例えば東京都等から、いわゆるこの仕組み、法を区として実施するに当たって何か情報をいただいているのか、その２点をまず。","respondent":"永尾障害者福祉課長","answer":"それでその中で、虐待じゃないかと疑われる場合については、区のほうで現場を確認しに行ったり、実際の支援をした人や施設長からのヒアリングをしながら、その辺のなぜこういうふうになったのかというところを原因追及しながら、実際には対応をしているところです。","voiceIndex":68,"id":"exchange-023"},{"speaker":"若林委員","kind":"質問・要望","question":"いや、実は１）の4)としてこういう対応も実はやっていて、当然これも継続するんですよという説明をいただきたいのが１つと、あとこれは障害のある子ども、障害児はどういうふうに扱われるというか、このシステムの中でどういう位置になるのかというのを最後にちょっと教えてください。","respondent":"永尾障害者福祉課長","answer":"それと、子どもについての考え方なんですけれども、法律の対象範囲というのが障害者虐待防止法の中で決められておりまして、在宅の方につきましては、１８歳未満は児童虐待防止法の範囲に入るということになるんです。","voiceIndex":70,"id":"exchange-024"},{"speaker":"若林委員","kind":"質問","question":"今のは在宅で過ごされている障害児、通所とかもいらっしゃるんですか。それは児童虐待防止法で、施設にいる子どもは自立支援法。","respondent":"永尾障害者福祉課長","answer":"いろいろな生活のパターンがあって、なかなか難しいところはありますけれども、在宅の方については児童虐待防止法になります。","voiceIndex":72,"id":"exchange-025"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"在宅でこれから高齢者の方を支えていくという方向性の中で、特におひとり暮らしをされている方で、客観的にはもうちょっとこれは限界だろうというような周りの区民の方とかの判断というか意見がある中で、本人は全く自覚をされないというか、大丈夫だというような形で一切の支援を受けないような方というのが、なかなかご近所の方も心配されるというような形での難しさがあるかと思うんですが。","respondent":"原高齢者福祉課長","answer":"本人の状況を細かくご案内するわけにもいかないことも当然ありますので、近所の方がご心配なところについては何なのかというところをきちんと把握する中で、そこについてはご心配はこうです、こういう対応をとりますというところはあわせながらご案内をさせていただき。","voiceIndex":79,"id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"もう一点なんですが、３ページの３の（２）の認知症専門チーム、これは要するに、この方は、今、認知症なのかどうなのかよくわからないというような、客観的に見てちょっとどうなのか、もしかしたらそうなのかな、いや、そんなことないのかなというような、よくわからないグレーゾーンという方々について。","respondent":"原高齢者福祉課長","answer":"そういう意味では、ご家族とかがいて、医療に、あるいはご本人にも医療を一緒にということで行っていただける方はここのところではなくて、医療もこの状況ではもうかかったほうがいいんだけれども、どんな形をとってもなかなか医療につながらないというようなところの中で。","voiceIndex":81,"id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問","question":"は１つの入り口として大事な事業だと思いますけれども、今後これを地域の中で、それこそ先ほど地域の中でのネットワークづくりというのをここのリーダーを中心にどうつくっていくのか、そこを伺いたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった意味では、品川区においても同様に認知症の高齢者の方々は増えていくということで想定し、その上で長期的あるいは短期的な取り組みということで、今後も認知症については、ほかさまざまな在宅サービスが充実してきておりますけれども。","voiceIndex":83,"id":"exchange-028"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"このサポーターの方々、そしてキャラバンメイトが２６８人いる。現状一人一人が大変頑張っていらっしゃるのはわかるんですけれども、やはり地域の中の仕組みづくりとしてどうつなげていけるのか、そこが、今、大事なのかなと思うんですけれども、その点だけ、もう一度ご説明いただきたいと思います。","respondent":"原高齢者福祉課長","answer":"そうは言いながら、その中で課題が発見されたときに、きちんと関係機関につないでいただくというところも大きな役割と考えておりますので、そういったところを含めながら、今後の課題にしていきたいと思っているところです。","voiceIndex":85,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"所管事務調査なので、いろいろ教えていただきたいことと考え方とかを聞くだけじゃなくて、我々の部分で内部で議員同士も意見が交わせられればと思いますが、そもそも論として、在宅介護で認知症高齢者の取り組みということで、目的があります。それと、あとよく人口統計みたいなのを出すじゃないですか。先を見越して、どういうふうに捉えられているのかという全体的なものを教えてほしいと思うんだけれども。","respondent":"原高齢者福祉課長","answer":"地域で生活を支える部分ということで、必要な介護サービスの充実を図るというようなこともありますし、医療、それから地域といったところが連携をしながら、こういった増えてくる認知症への対応をしていくというような国の政策がありますので、区の中でもそれに従いながら。","voiceIndex":87,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"いろいろすみません。そうすると、さっきの割合で行くと２０２５年に約１万人くらいに品川区もなるのかなと思っておりましたけれども、もう一回伺いますが、本当に在宅と施設に入ったときというのは、もし品川区の施設に入ったとして、幾らぐらい違うと思われていますか。けれども、区の施設に入るとしたらどれくらい違いがあるのかなと思われているのか、そこら辺のところをお聞きしたいです。","respondent":"原高齢者福祉課長","answer":"いずれにしましても、認知症の高齢者にならないように、日ごろの中から地域の中で、その方々が地域のほうに出て交わることによって、なるべく家の中に閉じこもる機会を少なくしていくということも、大変認知症の発症をおくらせる。","voiceIndex":89,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"意見","question":"私の考えなので、逆に所管事務調査では皆さんからいろいろな違うとかいうのも言っていただいていいんだけれども、私はそういうのは結果として認知症予防になっていくんだろうなと思うので、ぜひそういうのは取り組んでほしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-032"},{"speaker":"若林委員","kind":"質問・要望","question":"だけど、やはり相談の部分、全部これは大事で、もう一回、厚生労働省のほうの動きもあって、当然国でよかれといういろいろな専門家、研究の方、現場を知っている方が積み上げたオレンジプランでしょうから、そういうものにまたいいものはとり入れ、そこを基本に独自にやっていくということでいいのかなと思うんですけれども、出発するに当たっては。","respondent":"原高齢者福祉課長","answer":"ただ一方で、それぞれが無責任な対応をしますと、家族が当然混乱し、結果、本人がそういう形になるわけですから、そういった意味で連携をという言葉を使わせてもらいますけれども、この方は例えば成年後見が次の段階で必要だからということであれば。","voiceIndex":93,"id":"exchange-033"},{"speaker":"若林委員","kind":"意見","question":"ありがとうございました。品川区のいわゆる医者、専門医が１名ですけれども、さっきオレンジプランの中で、厚生労働省ではかかりつけ医の認知症の講習を広げていくと。語弊があったらすみませんね。全体の数も出ていらっしゃる中で、やはり頼りになるというか頼りになってほしいのは、申しわけないけれども医者ということになるので、ちょっと力強い答弁が聞きたいと思います。","respondent":"原高齢者福祉課長","answer":"一方で、先生方に対しての、国が言うその研修の充実というところも、国としても少しそこの部分が足りないという認識の中で、医療の先生方にも研修をさらに受けてもらうということで、オレンジプランで言ってありますので。","voiceIndex":95,"id":"exchange-034"},{"speaker":"鈴木（博）委員","kind":"意見","question":"私は医師会の会員なんですけれども、まず第一に、今、医師会で認知症の講習会というか、それの担当というか手を挙げる人、要するに回覧が回ってきて組織はしているんです。それと、今の課長のお話なんだけれども、１年間に１回やっていますというお話なんですけれども、１年間に１回というのは、ほとんどそれは１年たつと忘れちゃいますよね。医師会の会員として、見ていてそう思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問","question":"私はさっき質問すればよかったんだけれども、さっきこの自立度IIとあるじゃないですか。これぐらいの状態の人で、医者にかかっていないと言ったほうがいいのか、認定を受けていないという人というのはどれぐらいいるんですか。","respondent":"原高齢者福祉課長","answer":"IIというところでいきますと、先ほど９段階の中の下から２番目ということで、非常に軽い方から含めて６,０００人という数字です。","voiceIndex":101,"id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういう意味じゃないわけですか。よくわからないのだけれども、そこら辺のイメージだけ教えてください。","respondent":"原高齢者福祉課長","answer":"認知症の中で９段階とありますけれども、在宅生活の中で、例えば服薬管理ができないとか、あるいは留守番が１人でできないとか、問題行動になるのは物を口の中に入れてくるとか、あるいは外から捨ててあるものを拾い集めてくるとか、そういったことになると家族の方も。","voiceIndex":103,"id":"exchange-037"},{"speaker":"若林委員","kind":"質問","question":"最後です。さっきの続きというか、いわゆる医者の件について、ここには鈴木博委員もいらっしゃってご発言がありまして、やはりまだ２つの団体というんですか、すごく敷居があったり壁があったりというのを、やはり今の品川区の認知症の医療と福祉、医療と行政の現状というのはやはりそういうことなんだなというのを改めてわかりました。感じました。","respondent":"原高齢者福祉課長","answer":"いろいろな形で、医師会と行政の中では関係を持ちながら来てありますので、これから認知症高齢者、あるいはかかりつけ医という制度の中で、区と医師会がさらに連携できるよう、区のほうでも働きかけをしていきたいと思っているところです。","voiceIndex":105,"id":"exchange-038"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"言うなというのならやめておきますが、漏れ伝わるところですと、おかし工房は、品川区とってはすごくいいことなんだけれども、このとき平成２１年ですごくうまくいっていたんだけれども、今は大分落ち込んでいるという話を聞いたんだけれども、かえってそういうのを聞いたほうがいいかなと私は思って、逆にすごく参考になるなと思っているの。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで今はどういう状況ですかと聞くとか、多分、今は悪いんだって。これは平成２１年ホームページなので、今、平成２４年でしょう。結構悪くなっているわけだけれども、不安なんかも聞いたっていいじゃない。それも含めて、そういうときにどういうふうにするのかというのを聞きたいんですが、その辺はそういうことばかり聞いちゃいけないかなと。","respondent":"早津健康福祉事業部長","answer":"いや、承知していません。ただ、受け入れるんだから、そんなに大変ということではないんじゃないかと。","voiceIndex":123,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3336#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":81791,"voices":126}},{"id":"h24-20120925-8","meetingId":"h24-cm09","date":"2012年9月25日","dateIso":"2012-09-25","committee":"建設委員会","time":"午前１０時００分～午後２時２２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、報告事項を行います。 はじめに、(1)平成２３年度指定管理者による管理に対するモニタリング・評価","agenda":"の１、報告事項を行います。 はじめに、(1)平成２３年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"委託料というのはどういうふうに決まっているのか、決められているのかということを１点お聞きしたいのと、あと今回、収納率向上を重点テーマに取り組んできたけれども、下回ったということなんですが、９８.何％とか９９.何％という収納率になっていますけれども、滞納者の人数というのはどれぐらいの人数なのかと、理由もちょっとお聞かせいただきたいと思います。そのところを、もう一回お願いします。","respondent":"大串住宅担当課長","answer":"区民住宅におきましては、全体では３カ月以上となりますと３１名の方が、今現在ではなっております。昨年も大体これぐらいの同じ数字で推移しているというふうに考えていおるところです。","voiceIndex":8,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"忘れたというのであれば、また払っていただくということになると思うんですけど、滞納の理由というのが、今、失業だとか倒産だとか、いろんな事情でそういうふうになっているという、そこら辺の区民の実態というのがそういうところにあらわれているのかどうかということで、ちょっと滞納の理由をお聞かせいただきたいと思ったので、そのことを一つ教えてください。","respondent":"大串住宅担当課長","answer":"ただ、こちらの入居期間につきましては、実はちょっと国のほうからももう少し延ばせないのかというようなお話もあります。そういったところがありますので、こちらのほうとしても現在検討しておるところです。","voiceIndex":10,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それからあと、避難者については、私もいろいろとお話を伺ったときに、家もあり仕事もあり、本当に子どもたちもすべてスムーズに生活していたのを、原発の事故のためにすべて奪われたというふうなことで、本当にそういう話も伺って、帰りたくても帰れないという状況がありますので、引き延ばすということで検討しているというところですけれども、十分な支援をお願いしたいというふうに思います。","respondent":"大串住宅担当課長","answer":"耐震補強につきましては、順次現在行っておるところでございまして、平成２６年度終了を考えておるところです。","voiceIndex":12,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それともう一つお聞きしたいのが、東急コミュニティーのほうの管理のところで、震災による住戸内の被害が東館１１１件と西館７件発生したが、速やかに被害状況の確認を行い、修繕工事実施に当たっても問題なく完了することができたということで書いてあるんですが、これはおよそどんな被害になっていたのかということをちょっと教えてください。","respondent":"大串住宅担当課長","answer":"そちらを調査いたしまして、こちらに書いてあるように東館で１１１件、西館では７件、こういった事例があったということで、これの補修工事を実施いたしました。補修工事の金額といたしましては、約１,２００万円ほどかかったです。","voiceIndex":14,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"もう一点、駐輪場のことでお伺いしたいんですが、駐輪場の経営会議における評価結果というところに、「引き続き、安定した運営に努めるとともに、きめ細かな料金設定の導入等、多様化するニーズに対応できるよう検討を進めること」と書いてあるんですが、ここで言うきめ細かな料金設定の導入、それから多様化するニーズというのは、どういう中身を検討しているのかということをお聞かせください。","respondent":"谷口交通安全担当課長","answer":"運営につきましては、利用率を高めていくということで、こちらで検討しながら考えているところです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その検討の中に、民間なんかでは２時間までは無料とか、そういうのがありますけど、そういうふうなこととか、それから、ずっと区民の中からも要望が出されていました学割とか、そういうものをぜひ検討いただけないかなと思うんですが、いかがでしょうか。","respondent":"谷口交通安全担当課長","answer":"無料につきましては、正直言って、今のところ検討はしてございません。特に利用者は限られておりますので、利用者に対していろいろご負担いただくということですけど、全区民の税金を使っているということを考えますと、一応、今のところ無料化というのは検討していないです。","voiceIndex":18,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"なるべくダブらないように質問します。品川宅建管理センターと東急コミュニティー、指定管理者のことなんですけれども、質問の中で空室率というんですか、どのぐらいあいているかという質問は多分なかったので、それをちょっとそれぞれ教えていただければと思います。お願いします。","respondent":"大串住宅担当課長","answer":"借上型としては３３.２％の空き室率というふうになっております。","voiceIndex":21,"id":"exchange-007"},{"speaker":"浅野委員","kind":"質問・要望","question":"それと、こちらの使用料、これはあくまでも使っているというか、埋まっているところに対しての本来取るべき料金が取られていないというふうに認識をしていると思いますけれども、この点、１点お伺いしたいのと、あと、滞納者１件当たりの対応回数で、やはり業者で随分違うなというところが先ほども指摘されておりましたけど、本来どのぐらいやっていったほうがいいのか、そういうもくろみというんでしょうか。","respondent":"大串住宅担当課長","answer":"収納率に関してですが、委員おっしゃるとおりです。入居されている方の本来だったら取れる、納められるべき数字に対してです。２点目の対応回数です。こちらの目標数値といいますか、本来だったらどれぐらいが一番適正かですが、個々のケースによって違いはあろうかと思います。","voiceIndex":23,"id":"exchange-008"},{"speaker":"浅野委員","kind":"質問・要望","question":"予算執行の視点で、震災後の節電対策により電気代を年間約２５％削減したということで、さまざまな節電の取り組みをされていると思いますけれども、具体的にどんなことをやられたのかということをちょっと教えていただきたいのと、こちらの東急コミュニティーだけで終わっちゃったのか、それともそれを何か横に展開をして、例えば区営住宅なり、また区民住宅なりで適応させたというようなことをされたのか。","respondent":"大串住宅担当課長","answer":"それ以外の、例えば品川宅建管理センターのほうの管理している区営住宅、あるいは区民住宅ですが、こちらにつきましても、共用部分の電気の関係ですとか、そういったところで節電をするようにということで、節電に関しましては区全体で取り組んでいるところですので。","voiceIndex":25,"id":"exchange-009"},{"speaker":"浅野委員","kind":"意見","question":"そうすると、なかなか住民サービスというのか、そういうものが進まないというのが国も都も、品川区もそうなんでしょうけど、そういう傾向にどうしてもなりがちになってしまっているんですね。ただ、やはり今当たり前のように使われているものであることは間違いないので、区民サービスの観点から、この点についてはぜひとも、相手のあることですし、またお金のかかることでもあります。","respondent":"谷口交通安全担当課長","answer":"大体平均、ちょっと確認したんですけど、二、三％生じるということで、例えば２億円の収入があれば、４００万円から６００万円ぐらい税が使われるということになりますので、委員ご指摘のとおり、また前向きにいろいろ検証しながら取り組んでいきたいと考えています。","voiceIndex":27,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"１点だけお願いしたいんですけど、駐輪場のところで、真ん中の表のところの自転車定期利用のところで、平成２３年のところで６６.７％と前年度に比べて件数は減っていて、パーセントは上がっている、このところを教えていただきたい。","respondent":"谷口交通安全担当課長","answer":"耐震補強工事の関係で、結構大井町の台数が減ってありますので、その関係でこういう数値の差になっております。分母が減っております関係です。すみません。","voiceIndex":29,"id":"exchange-011"}]},{"id":"topic-02","title":"品川区環境計画の策定状況等","agenda":"品川区環境計画の策定状況等","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"私のほうから何点かにわたってお伺いします。２番目の実行計画の件なんですけれども、確かに２５％の目標というのが地域推進計画に出されていて、それについてはかなり難しい状況であるというのは新聞報道からも明らかなんですけれども、逆に今までの実行計画第２期のほうとの連続性というんでしょうか、これはどのように考えているのかなということを一つお伺いしたいと思います。とりあえずここまで。","respondent":"野呂瀬環境課長","answer":"これにつきましては、これから温室効果ガス削減の国の方針等と、それからまだ決まっていないですけれども、動向を注視しながらそれを取り組んで、実行計画と整合性を含めて見直し等を考えていくところです。","voiceIndex":35,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"それと、あとほとんど答弁いただきましたけれども、３番目の品川区域の二酸化炭素排出量の実績ですね。こちらについて、先ほどのオール東京６２市区町村共同事業ですね、ＥＣＯネット東京６２ですか、こちらのほうの数字ということなんですけれども、この数字とやはり出ている区の実績値がちょっと乖離がありますよね。火力発電の件だと私は存じ上げておりますけど、この点についての説明をお願いします。","respondent":"野呂瀬環境課長","answer":"１点目の報告の時期につきましては、排出係数が発表された大体年末ぐらい、年明けぐらい、２月ぐらいになるかと思うんですけど、それぐらいをめどに当該年度の排出係数で計算した報告をさせていただきたいと考えています。それと２点目のご質問です。","voiceIndex":37,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"環境計画を改定するということで、個別の施策ごとに目標を作成するということで今説明がありましたけど、これは具体的にはどんな施策ごとに、どういう目標なのかということを一つ教えていただきたいのと、それから６月から１０月まで懇談会を５回開いてきたということなんですけど、この懇談会の中でどんな意見が出され、それをどう反映させていくというあたりをちょっとお聞かせください。","respondent":"野呂瀬環境課長","answer":"ですから、細かいところは今後また詰めて、実際、今週第４回目の策定懇談会が金曜日にあるんですけれども、それと来月、５回の懇談会でそういう細かいところを決めていくということで、また素案の中でお示しできるかなと考えています。","voiceIndex":39,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その懇談会というのは、今週金曜日にあるということなんですけど、傍聴とかはできる仕組みなのかちょっとお聞かせいただきたい。それとあとは、やっぱり何と言っても環境、それから地球温暖化というところでは、今回の原発事故を受けて、根本から見直しというのが求められていると思うんですね。","respondent":"野呂瀬環境課長","answer":"新計画による考え方ですが、実は自然エネルギー等々につきましては、先ほど申しました地球温暖化対策地域推進計画の中でも、いわゆるクールシティしながわを目指す、そういうキャッチフレーズでやっているところですけれども、またそこから２年たちまして、今度。","voiceIndex":41,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やっぱり、原発に頼るというエネルギー政策からは転換しなくちゃいけないと、そういうところを迎えていると思うんですけれども、そういう中で、自然エネルギーの爆発的な普及をしていくというふうなところで、区としてもできる限りのそういう方向、できる限りの施策をとっていくという姿勢が今度の環境計画なり、そして地球温暖化防止対策実行計画ですか、そういうところにぜひとも盛り込んで。","respondent":"野呂瀬環境課長","answer":"自然エネルギー、いわゆる再生可能エネルギー、今パーセンテージで言うと全国でもまだ１％で、ご承知のとおり原発が３０％ぐらいあったのが、これからはなかなか稼働が難しいような状況です。そうすると、再生可能エネルギーというのはこれからの主流になってくる。","voiceIndex":43,"id":"exchange-016"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと基本的なことをお伺いしたいんですけど、品川区地球温暖化防止対策実行計画というのは、ここに書いてあるとおり庁舎とか区有の施設とか、区が持っているところの排出、温室効果ガスを減らすという実行計画ということで、下の３番の地球温暖化対策地域推進計画というのは、品川区全体で温室効果ガスを減らすということでよろしいんですか。","respondent":"野呂瀬環境課長","answer":"一方、地域推進計画というのはエリアのもので、これは任意計画で、別につくっても、つくらなくてもいいんですけど、ただし品川区の実績等、やはり２３区、または６２区市町村、東京都全部で集計しておりますので、実績として参考にするためにということで数字をもらっています。","voiceIndex":45,"id":"exchange-017"},{"speaker":"沢田委員","kind":"意見","question":"それで、今、課長からそういうお話があったんですけど、先ほど例えば品川火力発電所があるから、その分は抜くとかということだと、例えば大田区は羽田空港があるとか、品川区は国道がいっぱい走っていると車の量が多いとか、そうなってくると、今度品川区で地球温暖化対策地域推進計画というのは、区に限定して、区内の温室効果ガスを調査するというか、計画を立てるという考え方というか、意味というのは。","respondent":"野呂瀬環境課長","answer":"全体の数値も、あくまでもこれはその区、または市の参考にしていただくということで、それに基づいて、どれぐらい昨年度より多くなっているか、少なくなっているかというめどにしていただく、そういう目的で、各オール区市町村で集計したものです。","voiceIndex":47,"id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"そういうことだと思います。ということは、やっぱり区が主に進めていくという、区が区役所でというか、区でできることというのは、できるだけ区の庁舎とか区有施設とかの地球温暖化防止対策実行計画のほうが主に確実な計画を立ててやっていけるということでよろしいんですか。","respondent":"野呂瀬環境課長","answer":"地域推進計画というのは、区役所が率先しているんですけれども、区役所はあわせて区が率先しているほかに、広く区民に対して省エネ・ライフスタイルを推進していくＰＲだとか、事業所に対しても環境に配慮したような事業活動をしていくように。","voiceIndex":49,"id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"具体的にどのようになっているかを先ほど伺いまして、これからというお話なんですけれど、私は一般質問でお話しさせていただいたんですが、二酸化炭素排出量の削減というのが今お話に乗っているんですけれど、私のほうは海を汚さないという考えで、海洋生物がＣＯ２をとても削減するということで、品川区でも家庭排水とかいうこともお考えに入れていただきたいんですけれど。","respondent":"野呂瀬環境課長","answer":"それはもちろん今後もいろんな形でＰＲに努めて、またブルーカーボンにつきましても、今、環境課の窓口等にそのチラシ等を置いているところなんですけれども、今後また広くいろいろな場面を通じて啓発に努めていきたいというふうに考えているところです。","voiceIndex":51,"id":"exchange-020"},{"speaker":"吉田委員","kind":"意見","question":"直結して、要するに家庭でもできることが、ブルーカーボンというとちょっと難しくなっちゃうかもしれないんですけど、地球温暖化対策につながるということを明記していただいて、しっかりわかっていただけるような、そういうような発信をしていただけるようにお願いしたい、その辺、ちょっとお願いします。","respondent":"野呂瀬環境課長","answer":"さまざまなところを通じて、カーボンにつきましても、いわゆる生活そのものを見直すというのをきっかけにして、地球温暖化、ひいては環境保全に取り組むような形でＰＲに努めていきたい、そのように考えております。","voiceIndex":53,"id":"exchange-021"}]},{"id":"topic-03","title":"旧荏原平塚中学校跡地多目的広場整備工事","agenda":"旧荏原平塚中学校跡地多目的広場整備工事","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"それとあとは、植樹の落ち葉、こちらの処理がその次ぐらいかなと私は認識しているんですけれども、樹のほうはいかんせん植物ですのでいたし方ないんですけれども、グラウンドの土というのは、今回、多分風で飛びにくいとか、またさまざまな覆いをしながら対策をとられているかと思いますけれども、この点の、何というんでしょうか、大丈夫そうだというのをひとつお聞かせいただければと思うんですけれど。","respondent":"多並公園課長","answer":"あわせまして、先ほど防球ネットと、いわゆる球が出ないようにフェンスはあるんですが、そのフェンスに防塵のためのネットを張りつけるということで、そのようなところで防塵対策を進めていきたい、そのように考えてあります。","voiceIndex":59,"id":"exchange-022"},{"speaker":"浅野委員","kind":"意見","question":"とはいいながら、なかなか完璧というのは難しいかと思いますので、これが完成して、またさまざま地域からご意見があるかと思いますけれども、丁寧に対処していただければと、そのように思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-023"},{"speaker":"木村委員","kind":"意見","question":"このグラウンド、スポーツを通じたということなので、スポーツ、いろんな、各種のスポーツが行われると思いますけれども、そこの中に例えば野球の設備だとか、あと何かテニスだとか、サッカーだとかそういうもの、どういうものができるようになりますか。","respondent":"多並公園課長","answer":"区といたしまして想定しておりますのは、今までの利用の実態を踏まえまして、少年野球、少年サッカー、またグラウンドゴルフが主なスポーツとして認識しています。","voiceIndex":62,"id":"exchange-024"},{"speaker":"木村委員","kind":"意見","question":"それと、この周りに、例えばスポーツをする人だけではなくて、いろんな木が、高い木とか低い木が、いろんな木が植えられますけれども、それを楽しむということで散歩ができるような道、ちょっと一番右下のほうが狭いですけども、そういうものが何かつくれないか。","respondent":"多並公園課長","answer":"植栽のお尋ねかと思います。","voiceIndex":64,"id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"それに対処して、弱者、女性のそういうときの便器の使い方というものも、初期のときですから、そこで計画を立ててくれたほうがいいので、今まで単なる広場があって、災害用トイレをつくっているよということではなくて、今度は一時避難的なものとして考えられるということを加味すると、もう少しそういう防災的な面を考えていただけたらいいと思うんだけど、いかがでしょうか。","respondent":"多並公園課長","answer":"災害用トイレにつきましては、まず１基となっていますけれども、実際には穴が５個あるような形のものですが、この中のいろいろ配置の中で検討しながら、何とか可能な限りやってきたです。","voiceIndex":68,"id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"隣に京陽小学校があるからということも承知しながら質問しているんだけど、せっかくこんなにスペースがあるから、そうしたら京陽小学校に避難している人を予想して、いろんな被災地の人に聞いたら、トイレが大変だったという話を後で我々は聞いているんで、せっかくこういうスペースがあったときに、万が一のときに対応できるような仕組みを、この際だからつくっておいていいんじゃないだろうかというので。","respondent":"多並公園課長","answer":"防災機能、先ほどの、例えばですけれども、マンホールトイレについてですが、これもいろいろ検討いたしまして、今回、下水道に直結するマンホールトイレというのを設置しております。","voiceIndex":70,"id":"exchange-027"},{"speaker":"須藤委員","kind":"質問・要望","question":"東西に来るのか、南北に来るのか、いわゆる五つあるよというのが、あと二つ、三つとか、少なくとも増やせるんじゃないかなという思いがあるので、私はできるだけそのあたりは整備をしてあげておいたほうが、最初にやるときに少し金がかかっても、万が一のときに安心になるので、五つで終わりということじゃなくて、最大限配慮をしていただきたい。あえてお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、防火水槽、防火貯水槽なんですけど、これも１基ということなんですが、何トンあるのかということと、ここの地域も木造住宅がすぐ隣接して密集しているところでもあると思いますので、そういうときに、本当に初期消火がすごく大事だけど、水が足りないというのがやっぱり阪神・淡路大震災のときでもすごく課題になっていたと思いますので。","respondent":"多並公園課長","answer":"これにつきましても、周りがそういう密集地というか、それに活用できるようにということで、真ん中にあるのではなく、やはり道路側、広場側の両方から取水が可能ということで、配慮しながら、今回、設置位置についてもそのような形で設置したものです。","voiceIndex":73,"id":"exchange-029"}]},{"id":"topic-04","title":"国文学研究資料館跡地の公園名称決定","agenda":"国文学研究資料館跡地の公園名称決定","exchanges":[{"speaker":"木村委員","kind":"質問","question":"この文庫の森なんですが、近所の方々からいろいろなことでちょっと言われたことがあるんですが、名称のことなのでちょっと違うんですが、犬の散歩をするときに、戸越公園は今入れてくれないということで、この文庫の森ですか、跡地の一部を犬の散歩ができる何かをつくるというような話を聞いたことがあるんですけれども、どうなっていますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-030"}]},{"id":"topic-05","title":"目黒川浚渫工事に伴う水質調査結果","agenda":"目黒川浚渫工事に伴う水質調査結果","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"一番最初に、品川区長と目黒区長が東京都に要望したので、浚渫をしたという話があるんだけれども、(3)の考察で一時的なものであるというような結果になった。一時的な結果で、そのときはきれいになったけど、また再度、根本的な原因を除去しなきゃならんぞというような話は今後、やはり品川区長と目黒区長が連携をとりながら、東京都のほうに要請をしていくお考えでしょうか。","respondent":"武藤河川下水道課長","answer":"はい、まさに委員ご指摘のとおりで、私も実際に目黒川を見るたびに、やはりこの汚れの状況を改善していかなければならないと強く思っておりまして、まさに委員ご指摘のように引き続き、この河川に関係する品川区だけではなく、目黒区や、また上流の区である世田谷区とともに。","voiceIndex":91,"id":"exchange-031"},{"speaker":"浅野委員","kind":"質問・要望","question":"１点ですけれども、この浚渫工事を行った際に、放射性物質濃度を測定したというふうなことをちょっと記事で見たんですけれども、その結果がすぐにわかりましたら、直接関係ないことかもしれませんが教えていただきたい。","respondent":"武藤河川下水道課長","answer":"土砂の下のほう、下層部分につきましては、両放射性物質とも１０ベクレル以下という結果だったというふうに聞いております。","voiceIndex":93,"id":"exchange-032"},{"speaker":"浅野委員","kind":"質問","question":"河川全体がどうなっているかというのは、まだまだこれからだと思いますけれども、これがある意味だんだんおさまってくればよろしいんでしょうけれども、今後そういう意味では、都のほうに河川の放射性物質の検査というのもある意味定期的にお願いして、それも例えば都のホームページとか、品川区のホームページでもよろしいかと思うんですけれども、公表していって。","respondent":"武藤河川下水道課長","answer":"区としましても、そういった状況とあわせまして、東京都にも相談しつつ、こうした測定が進むよう対応してまいりたいと考えています。","voiceIndex":95,"id":"exchange-033"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも区民の不安の払拭のために取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-034"}]},{"id":"topic-06","title":"所管事務調査、木密地域不燃化１０年プロジェクト","agenda":"所管事務調査、木密地域不燃化１０年プロジェクト","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"道路のほうではない、木密地域不燃化１０年プロジェクトについてお伺いしたいんですけれども、今回、品川区の提案書というところで、特別な支援とコア事業ということで提案をされたということなんですけど、提案の中身はコア事業はコア事業で同潤会のところを進めていくということはわかるんですけども、それ以外の地域に関してはどういう地域にしていく、そのためにこうしていくというような目標ですとか。","respondent":"品川防災整備担当課長","answer":"基本的に建替えすることによりまして、道の狭いところを建築基準法にのっとりセットバックするような形ができるということで、それがどんどん続いていけば、４ｍのきれいな道ができるというようなことを考えております。","voiceIndex":104,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この同潤会のところはコア事業ということで進めて、あとこの全体の４町会での不燃領域率をここまで持っていくとか、そのために具体的にコア事業以外のところでは公園をもっとこういうふうにしていくとか、そういうような具体的なところというのはないのか、そこのところをもう一回教えていただきたいのと、もう一つは、ここの中にも老朽住宅の除却の支援、それからあと。","respondent":"品川防災整備担当課長","answer":"公園の件について、１点目と３点目とちょっと共通していますのでまとめてお答えしますが、木密１０年プロジェクトで出しているものの中では、公園の整備というのは基本的に考えておりません。","voiceIndex":106,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それともう一つは、ここの中での最も提案の中の一つがコア事業の同潤会のところになると思うんですけど、今この同潤会の中でどういう課題があるのか、まだ共同化に対して賛同されていないという方もいらっしゃると思うんですけど、そういうところに対しては、どういう合意を得られるための支援というのがあるのか、そこら辺のところをちょっと、どれぐらいの方が賛成されていなくて。","respondent":"品川防災整備担当課長","answer":"資金面の問題でやはり悩んでいる方等もいらっしゃいます。こういったところをもう少し我々も整理しまして、こういう木密１０年プロジェクトを機会に事業を進行していきたいというふうに考えております。","voiceIndex":108,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"自己負担になるというのがなかなか合意に至るまでにすごく大変だという話を聞いているんですけれども、ここのところは８６世帯でしたか、それで、９階建てのマンションができるということで聞いているんですけど、そうすると９階建てのマンションで８６世帯だと、保留床というのは何割ぐらいになっていくのかというあたりと、自己負担があるためになかなかそこに行けないという方に対しての支援というのは。","respondent":"品川防災整備担当課長","answer":"こういった点は、まだまだ検討段階ですので、それをもとにして、採算性のとれない方はどうだとか、そういったお話ではなくて、全体として採算性がとれるプランをどういうふうにしていこうかということを今現在考えている状況でもありますし。","voiceIndex":110,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このコア事業の共同建替えというのもまだまだ固まったわけではないということですと、今回も建替えの助成の新たな支援をされるというふうなところで言えば、この同潤会そのものの実態も１軒１軒の方々がそういうふうな形で耐震化、または建替え、そういうことで地震に強いまちをつくっていく、共同建替えではない。","respondent":"品川防災整備担当課長","answer":"ただ、やはり不燃の面、それから安全なまちをつくる面を考えてみれば、共同でマンションを建てていただくという形が一番安全な形ですので、区としてはそういう状況を見ながら考えていきたいというふうに思っております。","voiceIndex":112,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今協議会もやられていて、先日は課長にもおいでいただいて、こうやって説明もしていただいてという、ああいうやり方がすごく地域の方の意識づけにもなっていきますし、みんなでコミュニティをつくり、安全なまちをつくっていくということがすごく大事なんだなというのを改めて実感したんですけども、そういうところで言えば、あわせて建物を不燃化、それから耐震化、そういうふうなことをすると同時に。","respondent":"品川防災整備担当課長","answer":"まさに委員おっしゃるとおりでございまして、やはり防災面で言うハードの面、それからソフトの面を一緒に充実させて安全なまちづくりに取り組んでいきたいというふうに考えております。","voiceIndex":114,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"道路のところをお聞きしたいんですけど、先ほど同時期に補助３１号線も進めていくという方針があったと思うんですけど、そのところはどういう状況になるのかということが一つと、それから昨日の補正予算の審議の中でも、道路の脇は不燃化をしていくんだということなんですけど、沿道の不燃化というのは３０ｍずつやっていくということになっていくのか。","respondent":"藤田都市計画課長","answer":"そういうような空間があれば、延焼遮断は防げると、あとは一定程度の高さがあればというような話もありますけれども、今回、この地域の中にどういうような手法を入れていくか、それが３０ｍがいいのか、２０ｍがいいのか。","voiceIndex":116,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ここの中でも避難や救助活動の空間ともなる防災上効果の高い道路ということなんですけど、地震のときに避難や救助活動の空間になる道路を加工するというのは、結構かなり大変なことなんじゃないかと思うんですけど、例えば渋滞ですとか事故があったりとか、すごい強い地震でハンドル操作を誤って横転しちゃったりとかというのが映画の中でも出てきますけど、そういうことだったり。","respondent":"藤田都市計画課長","answer":"委員ご心配のいろんな項目もありますけれども、そういう心配があるからといって、空間をつくらないと、そもそもそういう活動ができませんので、まずは空間をつくることが重要であるというふうに考えてあります。","voiceIndex":118,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、もう一つ、沿道の建物という点では、先日のＮＨＫの、火の粉は７００ｍ先に飛び火して火災を起こすというような、そういう報道でしたけども、昨日の部長の答弁では、火の粉を遮断するような高い建物ということを延焼遮断でつくるんだというお話でしたけども、そうなると、火の粉を飛び越えさせない高さの建物というと、何ｍぐらいの沿道の建物の高さというのを考えられているんですか。","respondent":"藤田都市計画課長、片田都市環境事業部長","answer":"建物が１０階建てのものが燃えてしまうとか、そういうことにはなりませんから、そういうものは燃えない建物ですので、そういう中で、その高さが適正なのがどれぐらいなのかも含めて、この後の私どもの委託を検証する中で。たしか、４６号線沿いも一応そういう規制がかかってきているところがありますので、やはりそういう周辺での取り組み状況を踏まえながら、どういう効果があるのかというところが考え方になると。","voiceIndex":120,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、家の耐震建替えをしたばっかりでマンションには住みたくないとか、いろいろ沿道の方はたくさんいらっしゃると思いますので、そういう方のご意見も本当に受けとめていただきながら、ただ、決まったからそれをやっていきますというやり方ではなくて受けとめていただきたい、検証とあわせて要望をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-044"},{"speaker":"沢田委員","kind":"質問","question":"木密不燃化１０年プロジェクトの先行実施ということで、この１２地区ということなんですけども、最初から品川区は東中延と中延ということで出されたかと思うんですけれども、最初からこの全地区が先行の実施ということで選定されるということで、この２地区を出されたのか、最初聞いたときには３地区ぐらいを選考してという話だったかと思うんですけども。","respondent":"品川防災整備担当課長","answer":"ちょっと細かい話になってくるんですが、説明不足で申しわけございません。最初、先行実施地区という東京都から募集があったときには、３地区程度という限定がありました。","voiceIndex":124,"id":"exchange-045"},{"speaker":"沢田委員","kind":"質問","question":"今後、また第２、第３の地区ということで、本格整備ということでまた出されていくというお考えでよろしいんでしょうか。","respondent":"品川防災整備担当課長","answer":"本格実施地区のほうは、大体５０地区程度ということで、東京都のほうは挙げております。品川区のほうも現在やっている例えば二葉地区、豊町地区とか、こういったところを中心として何地区か実施地区に関しては挙げていこうということを考えております。","voiceIndex":126,"id":"exchange-046"},{"speaker":"須藤委員","kind":"提案","question":"不燃化のほうで、区が提案するというので１０項目支援を出していただいて、これがこのとおりじゃないよと。それでも、プロジェクトとしては進めていかなきゃいけないだろうと思うので、そのあたりのお考えというか、そういう覚悟というか、そういうものを持っていなきゃいけないよというお願いを一つしておきます。","respondent":"品川防災整備担当課長","answer":"その辺の時期になりましたら、こういう委員会の場で報告したいと考えています。それから、いろいろ東京都のほうが出しております先行実施地区の状況を見れば、先ほど私が２０ha程度と言ったんですけども、本当に４倍、５倍の広さで先行地区になっているようなところもあります。","voiceIndex":128,"id":"exchange-047"},{"speaker":"浅野委員","kind":"提案","question":"この３の(2)の区が提案する特別の支援の１０項目については、説明の中では、例えばコア事業の上限ですとか、そういうような話も出ていたんですけど、これは先行実施地区２９.４haですね、これは全体に、全部当てはめようという形でやっているのかどうかということが一つと、あとその中で、先ほどのようにコア事業だけが対象となるところも加えているようなので。","respondent":"品川防災整備担当課長","answer":"すみません、説明がちょっと不十分で大変申しわけございません。番号で言いますと、５番、それから６番、これについてはコア事業地区のみのお話になります。これ以外の部分につきましては、この先行実施地区全体のお話になります。","voiceIndex":131,"id":"exchange-048"},{"speaker":"浅野委員","kind":"質問","question":"わかりました。１月ぐらいが公表の時期だったんですけれども、やはり先にやらなければならないということで早まったかと思いますが、これは全１２地区ですね、すべてが一斉に公表されるものなのか、そのときに特別の支援ですか、これもすべて、ある程度なのかもしれませんけど、どれがよくて、これはだめだよということがある程度わかるのかどうか、その点について教えてください。","respondent":"品川防災整備担当課長","answer":"こちらは、あくまで東京都と区のほうで９月に都区協議会というものを１回行ったんですが、その中で、東京都のお話になってしまうんですけども、整備プログラム、これは先ほど説明しましたように、各区独自でやるものもあります。","voiceIndex":133,"id":"exchange-049"},{"speaker":"浅野委員","kind":"質問・要望","question":"３月の時点では不燃化特区制度の創設というからには、やはりこの１２地区がまとまって結論が出て、じゃあ１２地区のうち、どこからどこまでというのが正式にわかるという、そのような意味合いだと思うんですが、そこの中で不燃化特区というのが改めてこのように決まったということで、うちが、この２９.４haが入るかどうかということが正式に決まるということだと思いますので、この確認をさせてください。","respondent":"品川防災整備担当課長","answer":"それで、実際、本格実施地区に入るときに、どういうような要望が入れられるかとか、結局のところ、ある程度はこの３月のところで制度が構築していますので、それにのっとって必ずやってくださいというふうになる場合も考えられますし、そうは言っても、やっぱり各区、各地域。","voiceIndex":135,"id":"exchange-050"},{"speaker":"浅野委員","kind":"質問","question":"それとあと１点、同潤会地区の０.６haですけれども、強制力のある手法で、防災街区整備事業というふうに出ているんですけど、あまり調べられなかったんですけども、荏原町のあそこのところは、これとはまたちょっと違って、あそこはとにかく一つの建物を建てるという形だと思うんですけれども、この同潤会地区の整備については、全体を大きなビルにしなくても、ある程度のビルを建てて。","respondent":"品川防災整備担当課長","answer":"そういう点から見ますと、やはり区としては、できれば一つのマンションという形で建てられればなというふうには思いますが、そこら辺は住民、住んでいる方の意向がありますので、その辺はまた調査しながら進めていきたいというふうに考えております。","voiceIndex":137,"id":"exchange-051"},{"speaker":"浅野委員","kind":"質問","question":"いろいろな方がおられるということだったので、ちょっと質問させていただいたんですけれども、何とかうまくまとまるように、また災害のほうにも強いまちづくりということで進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4052#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":59788,"voices":167}},{"id":"h24-20120925-9","meetingId":"h24-cm09","date":"2012年9月25日","dateIso":"2012-09-25","committee":"文教委員会","time":"午前１０時００分～午後３時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を115件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の(1)伊藤学園プール温水運用および地域一般開放の取り止め","agenda":"の(1)伊藤学園プール温水運用および地域一般開放の取り止め","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"突然のことという、そういう印象です。それから、説明会については団体にはこうやっている、一般利用の方については今後速やかに、ということなのですけれども、こういう結論を出す前にやはりこういう状況だというところを知らせていただいてご意見を聞く、そういうことが大事ではないかと私は思っているのですけれども、そのあたりはどういうふうに考えるかお伺いします。","respondent":"和氣学務課長","answer":"基本的に伊藤学園は荏原平塚学園と同じ形のプール運用をしたいと考えた工法であります。次に、設計の話ですが、先ほどご説明したように、当初の予定では加温式のプールですので、温水を想定してございません。は逆に温水にしています、この施設についてはですね。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"その辺については、今、身近なプールで健康を増進するという区民の思いはかなり強く熱いものがあると思うし、プールについては２０年も３０年も前から区民の切実な要望の一つであって、それが地域の中にこうやって分散して活用・利用できることについては、本当に区民の皆さんは喜んでいらっしゃるし、その辺について。","respondent":"和氣学務課長","answer":"本当に今まで近くにあってというところで遠くまで行くご不便はおかけいたしますけれども、今度はもっと快適に、冬は寒くなくて、夏も暑くないプールをしっかりご利用いただければと考えているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"そのことで加温をする。当初から、では品川学園だとか八潮学園だとか、あるいは豊葉の杜学園でも温水プールを一般開放することが計画に入っているから伊藤学園で加温するその設備が不十分ということが想定できるので、その部分も含めて、当初、いずれ終息していくことも含めて判断していたのかどうかというあたりはどうだったのですか。よくわかりません。","respondent":"和氣学務課長","answer":"その設備をあえて温水として年間利用するためにヒーターを増設したり、もしくは加温の電気の熱線量をもう少し上げたりという形で対応したのです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"確認","question":"確認なのですけれども、伊藤学園をオープンした際に、一般開放するに当たっては、当初の設備に手を加えて温水プールとして対応できるような設備にしたと。その時点では、いずれほかのところが整備されていけば、ここでは止めることはいいのかなという、そういう考え方もあって当初の状況の中では判断をしたという、そういうことなのですか。","respondent":"和氣学務課長","answer":"八潮学園が温水プールになるのも決まっていませんでした。品川学園が温水プールになるのも決まっていませんでした。そういう段階での判断と、今はもう既にそれが決まっている、もしくは運用しているときの判断はおのずと変わってくるものと、そういうふうに考えてあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"その判断をした理由は、大きな理由としては電気代がかかることが一つ大きくあるわけですね。ここでただ単に伊藤学園の問題だけを議論するわけにはいきませんので、区民の要求との関係で、確かにランニングコストは大きなポイントだとは思いますけれども、要望との関係でどういうふうに考えたらいいのかというそのあたりをどう見ているのか、そのあたりの見解を伺いたい。","respondent":"和氣学務課長","answer":"委員ご指摘のことは区民委員会で議論することですが、この一般開放の取り止めについては、地域振興事業部文化スポーツ振興課と十分協議の上決定したことですので、地域振興事業部文化スポーツ振興課のほうでも十分足りるという判断をしたところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今の質疑の中で少し話があったのですが、当初からそういう構造的な問題があるのはある程度理解した上で、要望があって改装した経過は理解したわけですが、となると、やがて将来はこの伊藤学園プールについては先ほど質疑にあったように使えなくなる可能性があったわけです。","respondent":"和氣学務課長","answer":"その抜けるために実はタービンをつけようとか、フィルムを張ろうとか、いろいろ考えたのですが、どうもその効果は期待できないということが最近またわかりまして、ずっと悩んではきたのですが、この際、このタイミングで中止したいということで。","voiceIndex":16,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"今言ったさまざまな理由が明らかになって、止める方向性は理解するのだけれども、この２万何千人の方々がどう理解するかということを今度は議員としてはやはり指摘せざるを得ないわけで、幾ら、確かに近接にできたということはわかるけれども、伊藤学園に行っていた方々が、今度、八潮学園なり豊葉の杜学園へ行かなければいけないそれぞれの人が出てくるわけであって、そのことに対しては、張り紙。","respondent":"和氣学務課長","answer":"周知自体は実際に利用を管轄している文化スポーツ振興課のほうでやることになりますが、事前の打ち合わせの中では丁寧にしっかりと説明していこうとなっておりまして、今のところは張り紙と広報でありますけれども、具体的にもう少し。","voiceIndex":18,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"確認","question":"そうでなかったら、やはり行政もそういうことに対して、今、これこれをこういう理由でこういうふうな方向性を品川区として確認できたその結果として何十万ｋＷも電気量が節約できるということをやはり合理的に目に見える形で、できればさまざまなメディアがもし使えればいいのだけれども、要は２万何千人の方々がはっきりと理解してもらえる努力はどうしても必要だと思うのです。","respondent":"和氣学務課長","answer":"そういうご提案も含めまして文化スポーツ振興課と十分話をして丁寧にご説明いただくようにお願いしたいと考えております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"確認","question":"１点、確認だけで。この伊藤学園プール温水運用はこれからは止めるということですか。つまり、一般開放は一定の時期で終わるという考え方でよろしいのでしょうか。","respondent":"和氣学務課長","answer":"豊葉の杜学園の温水プールの運用が始まって止めるという考え方です。当初に設計で予定したとおりの全天候型の加温プールということで伊藤学園が十分使えるようにするということで、温水として今後運用していくことはないと考えております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"そうしたら、伊藤学園プール温水運用をしていた団体の方々は、やはり定期的に使うことがあるでしょうから、豊葉の杜学園は、できれば難しいかもしれないけれども優先枠を設けるとか、そういうことをしていったほうがいいのではないかと思うのですけれども。それは難しいと言うかもしれないけれども、伊藤学園プール温水運用の方々は今まで２万何千人の方々がいるわけです。品川区の責任なのだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鶴委員","kind":"質問・要望","question":"今、二人の委員からあったことと若干重なるところも、確認も含めてあえてお聞かせいただきたいと思います。これ、当初の設計段階ということで、そういう要望があって変更になったということと、設計業者ないし施工業者等々の中でそういうプール自体の運用のやり方を変える中にあって、その設計の中で想定としてそういうふうになり得ますよという、冬寒くて夏暑い、そのような説明は当時あったのかどうか。","respondent":"和氣学務課長","answer":"そういう想定がされるという話はありました。それをどこまでマイナス面をカバーできるかということでいろいろな協議をした結果です。","voiceIndex":25,"id":"exchange-011"},{"speaker":"鶴委員","kind":"確認","question":"私も資料を見たら、どこかの大学の方が研究して、施設一体型の建物の部分という論文を読んだら、たまたまここが出ていたので、その辺のくだりがたまたま歴史として載っていたので、私も見たことがあるんですけれども、大きい買い物というか、区としては大きいつくりものなので、例えばそういう声があったときにどこまでの、どの段階でつくりそのものが変えられるかというところでは。","respondent":"和氣学務課長","answer":"何キロ圏という形でしっかりとは設計上もできておりませんので、それも一応、文化スポーツ振興課とは協議の中で十分吸収できるだろうということでご回答いただいている部分等ではあります。","voiceIndex":27,"id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"私からもお話を幾つかお伺いしたいと思うのですが、まずそもそもの話まで戻るんですけれども、なぜ伊藤学園では温水の設計をされなかったのか。敷地に関して言えば、もっと狭いところもありますし、伊藤学園では何か温水ではできない理由があったのかどうかということをまず。","respondent":"和氣学務課長","answer":"そもそも一般開放を前提に設計しているわけではないので、伊藤学園を設計するには、学校で１年生から９年生までが使うに当たって、どれだけの期間プールが使えるようにすればいいかという発想で全部設計しています。","voiceIndex":29,"id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"なので、そこがなぜかなのです。要はプールの配置などを見ると、むしろ豊葉の杜学園温水プールなどのほうが荏原文化センターに近いわけですから、区内に均等に配置するということですと、本来、立地としては伊藤学園のほうがいい部分もあるのかなと思えるのですけれども、なぜ伊藤学園では一般開放ということも考えた設計にしなかったのか。その理由が知りたいところなのです。","respondent":"和氣学務課長","answer":"先ほども説明しましたけれども、最初から小中一貫校が全部温水プールということではなくて、普通のプールですので、全部、荏原平塚学園を見ていただくように、別に学校で使えればいいわけです。","voiceIndex":31,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問","question":"前半のご回答はちょっと質問の意図とずれていたのですが、何で小中一貫校なのにないんだということではなくて、伊藤学園をつくるときに温水にするか加温にするかということで選択肢があった中でなぜ温水を選ばなかったのかということを伺いたかったので、ご答弁の後半のほうはわかりました。前はずれていたと思います。だから、ひっかからないでほしいんです。よろしくお願いします。","respondent":"田村教育次長","answer":"ですから、伊藤学園も、先ほど言ったように敷地が狭いというのもあるんですけれども、やはりプールを上に持っていって、できるだけ常温のただ普通の屋上にあるプールだと、早くても５月の末か６月ぐらいからスタートで９月いっぱいぐらいなので。","voiceIndex":33,"id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"ようやく流れがわかりました。それで、結果的に加温プールという形で建物をつくった上で温水運用をスタートしたということなのですけれども、加温プールを温水運用するためのプラスアルファの投資額はどのくらいだったのでしょうか。","respondent":"和氣学務課長","answer":"金額はすぐには出ませんけれども、数千万円はかかっていると思います。数千万円単位で。その後もちょっと換気を変えたりしていますので、そのときに数百万円かかっております。数千万円単位でプラスになるかと思います。具体的に数字は持ち合わせてございません。","voiceIndex":35,"id":"exchange-016"},{"speaker":"阿部委員","kind":"質問","question":"先ほどからのやりとりを聞いていると、教育委員会としてもよかれと思っていろいろ努力されたことは非常によくわかるのですけれども、やはりここで投資した数千万円がわずか６年間で使わないものになってしまうのは、税金の使い方としては意思決定がどうだったのだろうかと。その点、どうお考えでしょうか。","respondent":"和氣学務課長","answer":"その判断ですが、その当時、平成１９年当時段階の判断ですので、そこを問われましても、なかなかこうだという、今、後づけに言ってもなかなか難しいものがあります。それと、逆に、このまま運用していくほうが税金の無駄遣いになってしまうと考えます。","voiceIndex":37,"id":"exchange-017"},{"speaker":"阿部委員","kind":"質問・要望","question":"次に、伊藤学園のこの経費、３,３７０万円と、それから電気使用量、たぶん、非常に多いのだろうと思うのですけれども、ほかのプールとの比較がないので、どの程度多いというふうな判断が私ではつかないものですから、ほかとどの程度違うものなのでしょうか。ざっくりでいいのですけれども、現実の比較はどうなっていますか。","respondent":"和氣学務課長","answer":"電気使用量も、実は日野学園と単純には比較できないのですが、例えば平成２３年度で言いますと、電気使用量が日野学園が４０万４,８０７ｋＷだったところを、伊藤学園は、これはプールですが、プールは５６万７,２３３ｋＷという形で、かなり使用量が高いというのは事実です。","voiceIndex":39,"id":"exchange-018"},{"speaker":"阿部委員","kind":"質問","question":"それぞれのプールで現に政策は税金に来るというのは、それはわかります。今まではこちらのほうで加温式プールを無理くり使っていたけれども、そちらのほうに移っていただくことでより快適になりますよという、ちょっとプラスの話で説明をしていかないと納得していただけないのではないかと思いますけれども、いかがでしょうか。","respondent":"和氣学務課長","answer":"先ほどの説明の中でも言わせていただきましたが、私どもとしては、より快適なプールをお使いくださいという形で説明をしていただくように文化スポーツ振興課にお願いしています。","voiceIndex":41,"id":"exchange-019"},{"speaker":"高橋委員","kind":"質問","question":"所管課が違ってしまうので、先ほどこの話を伺ったところですが、もう１回聞きたいのですけれども、先ほど要するに加温プールにするというときのいろいろないきさつをお聞きしたのですが、教育委員会としてはこうだ、しかし、こういう意見もあったといって、最終的に加温になったということですね。区役所の中の事情になるのでしょうけれども、その政策の決定の過程をお尋ねしたいのが一つ。","respondent":"和氣学務課長","answer":"変更過程ですが、もちろん関係各課から全部集まってしっかり協議をさせていただいて、それぞれ改善のときも今回のときにも協議をしております。ですから、私ども学務課と地域振興事業部とはしっかりと協議をさせていただいて決定させていただきました。","voiceIndex":43,"id":"exchange-020"},{"speaker":"高橋委員","kind":"質問","question":"変更のほうは地域の方のことなのですが、今、関係の部課が集まって協議をやっていますというお話だったのですが、ということは、先ほども何度も出ましたけれども、よかれと思って進めてきたことなのですけれども、こういった過程でこういうふうになったというのは、責任という言い方ではないですけれども、それは「再び関係の部課が集まったところなのです」でいいんですか。責めるという意味ではなくて。","respondent":"和氣学務課長","answer":"これは区の意思として決定したですので、それは区長を含めてご了解いただいて決定したものです。","voiceIndex":45,"id":"exchange-021"},{"speaker":"渡部副委員長","kind":"質問","question":"子どもたちなのですけれども、今まで一般開放している中で伊藤学園の子どもたちはどのような利用をされていたのか。例えば月ですとか、夏休みですね。特に普通の学校だと集中的に夏季期間はやっていたと思うのですけれども、その辺の状況、来年以降、伊藤学園の子どもたちはどうなるのか、決まっていれば、わかる範囲で教えてください。","respondent":"和氣学務課長","answer":"今のところ、学校プール利用が５月から１０月ぐらいまで使えれば十分運用できるということで、逆に占用できますので、今まで調整が大変でございまして、一般とか団体と調整することが大変だったわけですので、学校で占用できれば十分ですということでおこたえいただいております。","voiceIndex":49,"id":"exchange-022"},{"speaker":"渡部副委員長","kind":"意見","question":"そうしましたら、普通の学校と同じような形になってくると思うのですけれども、たしか言葉がわからなくてすみません、夏休みの間だけ指導員の方が来て一般開放の短い期間ですけれども、あいている学校があると思うのですね。あれ、区内で何校ぐらいありましたか。","respondent":"齋藤庶務課長","answer":"１０校ほどです。","voiceIndex":51,"id":"exchange-023"},{"speaker":"渡部副委員長","kind":"意見","question":"ここの伊藤学園が一般開放をやっていることによって、逆にこの地域でそれをやっている学校がどこなのか。逆に言うと、もし夏休み中だけでも少し子どもの占用が外れる期間があれば、あそこに常温でも普通に使えるあれだけの施設であれば、その辺の学校と同じようにせめても２週間とか３週間か忘れましたけれども、そのような貸し出し方ができないものかとは思ったのですが、その辺はどうなのですすか。","respondent":"和氣学務課長","answer":"そこら辺のバランスは、少し考えてありますので、今回、運用中止について、この後どうするかについてはまた伝えておきますので。","voiceIndex":53,"id":"exchange-024"},{"speaker":"渡部副委員長","kind":"質問","question":"わかりました。最後に、伊藤学園の施設全体の中で、一般開放を今までやっていたことによるスペースが多分にあると思うのですが、そのようなところはどのように今後活用していくのか。要するに一般の人しか入れない部分があったと思います。だけれども、これから学校占用になりますと、それはもう全く意味のない施設になっていくと思うのですが、その辺はどのように改修していかれるのでしょうか。","respondent":"和氣学務課長","answer":"そもそも狭くて、専用ドアは別に後からつけたものですから、客だまりがなくて、そこに地べたに座るとか、そういう問題がございましたので、逆に閉鎖することによって学校は運用しやすくなるです。あいた箇所については、学校と十分協議して活用してまいりたいと思います。","voiceIndex":55,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"簡単に。したがって、当初のイニシャルコストと加温してやっていくランニングコストというあたりをどういうふうに判断したのかということについて改めてその１点だけ伺っておきたいと思います。","respondent":"和氣学務課長","answer":"先ほどもご説明いたしましたけれども、平成１９年当時、プールがここしかないという判断と、今、これだけプールが７校目ができるときの判断はおのずと違いがあります。その当時はそういう地域のご要望におこたえすることに意味があるということであえてやったものです。","voiceIndex":57,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"コストも含めて判断したということですけれども、そうであるならば、ほかの伊藤学園以降の小中一貫校を建設する計画があったわけですけれども、そこをプールの一般開放をしなかった場合には伊藤学園でこういうふうにコストが高くつく、４割にも相当するような電気使用になったとしても、プールのバランス的にはここも必要だということで続けていく、そういう考え方もあるということなのですか。","respondent":"和氣学務課長","answer":"今の状況で温水プールが豊葉の杜学園も含めて伊藤学園も含めて６箇所もあるというところでの判断、しかも、範囲的に大井町でということは６箇所に至るということの意味で言えば、快適ではないプールを廃止して快適なプールを使っていただくというのは相応の形になります。","voiceIndex":61,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"今の説明についてはよくわからないのです。伊藤学園のプールは結果的に快適ではなくてずっと来ていたわけですよね。そういう点では、快適にするための抜本的なやり直しも含めて存続させていくという、そういう考え方なのかどうか、そこも含めて答弁をお願いします。","respondent":"和氣学務課長","answer":"躯体そのものをいじらなければいけないとかというところまで発展します。機械も全部入っていますから、全部解体して出すという話になりますので、そういう技術的な問題も含めて非常に困難だということで今回取り止めをするですので、手入れ等はしないということです。","voiceIndex":63,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"それと、住民のニーズをどこまでどういうふうに共有していくか、組み合わせていくかというところの判断だと思うのですけれども、大事なところは子どもの教育をしっかり進めていくという、小中一貫校教育そのものということではなくて、子どもの全面的な発達を学校の教育の中でどういうふうに促進させていくかというそこのところをより太くしっかり置いて教育行政を進めていただきたいということを要望として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-029"}]},{"id":"topic-02","title":"の(2)平成２５年度小・中学校における土曜日の授業の実施","agenda":"の(2)平成２５年度小・中学校における土曜日の授業の実施","exchanges":[{"speaker":"南委員","kind":"意見","question":"たしか、今年度は１７日ですよね。来年度は２０日にするという。そうすると、これからさらに再来年はもう少し増やしていくのかなとも心配なのですけれども、そのあたり、土曜日の授業の設定、基本的な考え方、そのあたりをちょっと。","respondent":"太田指導課長","answer":"増やしていくということではございませんで、その年度のカレンダー上の第１・第３土曜日を原則にしておりますので、その年度ごとに多少の日数が変わるです。","voiceIndex":70,"id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"そうすると、カレンダー上のことだと。今年度についての１７日は、土曜日のカレンダー上の事情で１７日だったと、単純にそういうことなのですか。それ以上、第１土曜日と第３土曜日ですから、カレンダーによっては増えるかもしれないけれども、第１土曜日と第３土曜日のそこの設定の基本的なところは変わらないと、こういうことなのですか。","respondent":"太田指導課長","answer":"そのとおりです。","voiceIndex":72,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"非常に土曜日の授業については賛成もあるけれども、しかし、子どもの体力的な部分も含めて危惧する、そういう声もあるのは事実だと思うのです。そういうあたりも含めて、第１土曜日と第３土曜日ということであればそれ以上のことは何も言えなくなってしまうわけですけれども、子どもの体力的なところも含めてしっかり教育委員会としてはキャッチをしてかかっていただきたいと述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"これ、今出たように今年度１７日間、３５週分の半分の予算だったかと思っていたのですが、カレンダー上の設定だったということで、ちょっとびっくりして聞いていたんですけれども、年度によって日数が変わってくるということで、授業時数もカレンダーによって年間の授業時数が変わってくるというところもあって、そうすると、平成２５年度は授業時数は何時間になるのでしょうか。","respondent":"太田指導課長","answer":"平成２５年度、各学校で教育課程を編成する段階でその時数は決定してまいります。","voiceIndex":75,"id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"品川区ではカレンダーに沿って年間の授業時数が変わっていくということなのでしょうが、結構珍しいことだと思います。それは一つ。それから、これは学校の裁量の余地は全くない運用ということでよろしいのでしょうか。","respondent":"太田指導課長","answer":"学校の裁量というよりは、地域等の祭礼等、そういったような不都合がある場合には、指導課と相談をしてということでの対応をしております。","voiceIndex":81,"id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"２０日間という決定の中で、学校の裁量が許される範囲は、教育委員会はある程度考えていらっしゃるのですか。","respondent":"太田指導課長","answer":"その事例によって判断いたしますので、範囲というものを設定はしてございません。","voiceIndex":83,"id":"exchange-035"},{"speaker":"阿部委員","kind":"質問","question":"まだ大分先だとは思いますけれども、それぞれ学校の中で時間割その他、授業を組んでいくことになるかと思うのですけれども、２０日間、学校からは、あるいは教員のほうから１７日間でも相当しんどかったという声を今年度も聞いておりますけれども、その辺については教育委員会として何か思っているところはあるのですか。","respondent":"太田指導課長","answer":"逆に、例えば週時点の中で少し余裕の時間ができるというようなところで大変有効であったという声もいただいているところです。","voiceIndex":85,"id":"exchange-036"},{"speaker":"阿部委員","kind":"質問","question":"確かに学校の授業のやりくりは分母が増えるという面はあると思いますけれども、ただ、土曜日の教員の出勤を伴うことになるわけで、かなりの部分は夏休み消化ということになると思うのですけれども、それが２０日間になってしまうと、余計、タイトではないか、そういう話は出ていないのですか。","respondent":"太田指導課長","answer":"既にそういったことも考え、今年度から例えば７月の第１週・第３週等は教育委員会指導課主催の研修会等を入れないというような配慮もしておりますし、各学校で適正にその振り替えをとるようにということで指導をしております。","voiceIndex":87,"id":"exchange-037"},{"speaker":"阿部委員","kind":"質問","question":"それを経て品川区では近年、土曜日授業が始まり、１７日間となり、２０日間となり、そもそもの学校週５日制の導入のねらいと今の品川区のあり方とどのような整合性を考えていらっしゃるのか伺います。","respondent":"太田指導課長","answer":"週５日制の趣旨というものと、今回の土曜日授業、例えば結果といいますか、地域における教育に関する意見交換会等でも、地域の教育に関心のある方々がこの学校の内容についてもお話をしていただくなどの成果等も上がっていることを考えれば。","voiceIndex":89,"id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"品川区としては、学力向上が一つの目的というふうに以前に伺ったことがあると思うのですけれども、土曜日授業を１７日、２０日とやっていくことと、初期の目的である学力向上との間でどのような相関があるか、そういったような現在あるいは今後の調査等々をされていく予定はありますでしょうか。","respondent":"太田指導課長","answer":"この一つに対して学力を細かく検証するということはないですけれども、本区では区の学力調査、それから都の学力調査、全国の学力調査も実施しておりますので、そういった中で子どもたちの学力についての検証はしていきたいと思う次第です。","voiceIndex":93,"id":"exchange-039"},{"speaker":"阿部委員","kind":"質問","question":"それというのも、これとの相関がわからないので、これだけのことをするだけの費用対効果とコストと効果の関係が明らかにはしにくいかと思うのですけれども、ぜひ教育委員会としては年間２０日掛ける３時間で６０時間ですか、授業時数を増やすということは、何らかの効果があるということを客観的に示すような方向性があってもいいのではないかと思います。ご答弁をお願いいたします。","respondent":"太田指導課長","answer":"基本的には授業を土曜日授業に向けていただくということで原則としてやっております。","voiceIndex":95,"id":"exchange-040"},{"speaker":"阿部委員","kind":"質問・要望","question":"時間を増やすことで精神論で学力というような話にならないように、ぜひそこのところは客観的に土曜日授業をやっていただきたい。","respondent":"太田指導課長、若月教育長","answer":"精神論でやるというお話も今ありましたけれども、そういったようなことでやっているということではございませんので、そこのところは誤解していただかないようにお願いしたいと思います。誤解されると困るので。来年度は２０日間授業がありますね。ということは、よその自治体よりもうちの学校が授業時数がプラスアルファされるということではないのです。学習指導要領によって国から年間の授業時数は決められているのです。","voiceIndex":99,"id":"exchange-041"},{"speaker":"阿部委員","kind":"確認","question":"実は、私、最初に伺ったのは年間の授業時数はどうなるんですかと指導課長に伺ったときに、９１０時間から１,０５０時間にプラス６０時間であるとおっしゃっていたんです。現状、今年度より多いです。さらに言えば、今年度もプラス１７日掛ける３時間で５１時間増えましたけれども、月曜日から金曜日の間に減ったのは１時間だけですから、差し引きで言えば３４時間は増やしているわけですよね。","respondent":"若月教育長","answer":"どう説明したらいいでしょうね。","voiceIndex":104,"id":"exchange-042"},{"speaker":"阿部委員","kind":"意見","question":"学習指導要領で定められた時間と品川区での教育要領、あれでまた時間が違いますよね。さらに各学校で多少でこぼこあるものの、さらに多い時間数というのは現実に今とっているはずです。ですので、土曜日授業をやったからといって学習指導要領を超える時間ではないと言うのは、実態とは数字が大分ずれがあるのではないかと。","respondent":"若月教育長","answer":"ただ、確かに学校によっては何時間か学習指導要領に定められた個別学習だとか復習の時間だとかという時間が含まれているのは間違いありません。","voiceIndex":106,"id":"exchange-043"},{"speaker":"阿部委員","kind":"意見","question":"これ以上は個別の話になりそうなのですけれども、要は心配しているのは、教育長がおっしゃるみたいに学習指導要領の時間を超えませんよということでは、それはそれでいいんです。それプラスアルファ品川区ではもうちょっとやるんですよと、それはそれでいいんです。例えば学校の判断にはというだけでいいのだろうかという基本的な疑問は持っております。","respondent":"若月教育長","answer":"これが極端に増えた場合、これはまたそのとき、その状況に合わせ、学校とも相談をし、地域、保護者とも相談をしながら柔軟にこれは決めていくことであって、機械的にもうこうだというふうに運営していくことは考えていません。","voiceIndex":108,"id":"exchange-044"},{"speaker":"高橋委員","kind":"質問・要望","question":"今、第１・第３土曜日の授業日が決まったわけなのですけれども、これに基づいて各学校で年間の授業時数を組んでいると思うのですけれども、そのときに、先ほど地域の祭礼等で変更もあるというような話があったのですけれども、これは要望なのですけれども、各学校が地域とよく連携をとって地域の祭りなどとの関連でうまくすり合わせて地域連携ができるようにお願いしたいのと、逆に言うと祭礼等は実際。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-045"},{"speaker":"伊藤委員","kind":"確認","question":"土曜日授業のことをいろいろ今、議論していたんですけれども、確認で指導課長に伺います。品川区教育委員会として土曜日授業をやる目的を改めてお聞きしたいと思います。十分な教員の給与、それから、その体制を十分にしてあげて、目的としてはそれに注力することとだと思いますので、そのことの議論、方向性を確認しておきたいと思いますので、改めてご答弁をお願いしたいと思います。","respondent":"太田指導課長","answer":"土曜日における授業の目的については、授業時数の確保と地域に学校を開放するということが中心です。","voiceIndex":112,"id":"exchange-046"},{"speaker":"伊藤委員","kind":"質問","question":"私が申し上げたいのは、品川区が２０日間、平成２５年度にやるわけですが、そのことについて教育委員会としてはどういう目標・目的を持って対処していきますかということをお伺いしましたので、もう一度ご答弁をお願いいたします。","respondent":"太田指導課長","answer":"この土曜日授業を実践していくことで各学校とも、先ほども教育長のお話がありましたけれども、その授業を平日の授業等も多少余裕を持ってやるというようなことを通して子どもたちと接する教員の時間を増やし、また、学力を個別に指導したりという時間も確保するということ。","voiceIndex":114,"id":"exchange-047"},{"speaker":"伊藤委員","kind":"意見","question":"先ほどの質疑の中で、この土曜日授業で学力の向上の効果性などと言ったけれども、私はここだけでは測定できないと思います。だけれども、私の思いの中では、この２０日間きちんとやっていただいた上で、それでも足らない気持ちもあるのだけれども、やはりそのことについて品川区の教育委員会の基本的な考え方をどうしても聞きたいです。そういうことでお願いいたします。","respondent":"太田指導課長","answer":"そういったことから考えても、この土曜日授業を充実させていくことは非常に大切なことだと考えております。","voiceIndex":116,"id":"exchange-048"},{"speaker":"伊藤委員","kind":"意見","question":"もちろん、誰だってできないかどうかということも考えるのだけれども、なるべく土曜日授業の中でそういう人権のことについて考えるとか、例えばいじめのことについて総合的に勉強していくとか、そういうふうにしていくことでもいいから総合的な対策をしていきたいということをお願いしておきます。","respondent":"若月教育長","answer":"それを通して学力なり、今ご指摘になったいじめ等々の人権に関する問題であるとか、というような人間的な触れ合いの場をより多くする、そんな強い思いを持ってこの第１・第３土曜日に臨んでいきたいと、こう考えているところであります。","voiceIndex":118,"id":"exchange-049"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"一つだけ。公式に第１・第３土曜日を品川区として学校を開いていくということで、スクールゾーンは何とかならないですかというお願いなのです。そういう対応ができるのであれば、何とか品川区の子どもたちを守るためにも、この第１・第３土曜日、７時半から８時半までスクールゾーンというのを強く働きかけていただきたいと思うのですが、何かお答えできることがありませんでしょうか。","respondent":"齋藤庶務課長","answer":"そういうところで規制をかけると、取り締まりもしなければならない。警察としては対応ができないということで、ですから、これからも引き続き申し入れはいたしますけれども、原則としては法的安定性、そういうことでもってなかなかいい返事をもらえていないです。","voiceIndex":120,"id":"exchange-050"}]},{"id":"topic-03","title":"の「家庭の日」啓発事業","agenda":"の「家庭の日」啓発事業","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"勝手なことなのですけれども、このチラシに書いてある、黄色いチラシを見る限りでは、「ピエロがやってくる！たのしい大道芸をみよう！だから、もし目的として「家庭の日」というふうになれば、講演会はいいと思うのです、講演会の企画は。だから、いろいろな年齢層の子どもたちが集うような仕組みを検討してみたらいかがでしょうかという質問なのです。いかがですか。","respondent":"梶青少年育成課長","answer":"ただいまのご質問は、もっと多くの子どもが参加できるような形で、チラシのほうはこういった小さい子どもの絵が描いてありますが、中に実際に来てやるものにつきましては模擬店ということで、例えば食べる物で言えばクレープとかポップコーンを無料で配布するとか。","voiceIndex":127,"id":"exchange-051"},{"speaker":"伊藤委員","kind":"質問","question":"この企画自体は問題ないと思います。だから、今、いろいろちまたをにぎわしている青少年の非行の問題などということを考えてみると、こういう企画では旧式な感じがするのです、一元的に。来たとしても友達と来るような形になるのでしょうから、そういう子どもたちの実態に合わせた企画を検討してくださいということをお願いしておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-052"},{"speaker":"鶴委員","kind":"質問","question":"簡単なことで、このチラシは、どこのどなたがつくられたのですか。","respondent":"梶青少年育成課長","answer":"こちらのチラシですけれども、委託は区でやるわけなのですが、この案文を考えたのは私ども青少年育成課と青少年委員会と一緒に考えたところです。","voiceIndex":130,"id":"exchange-053"},{"speaker":"鶴委員","kind":"質問","question":"ごめんなさい、すごく細かいことばかり。デザインを含めてつくられた部署はどこですか。","respondent":"梶青少年育成課長","answer":"区の部署で言いますと、青少年育成課です。","voiceIndex":132,"id":"exchange-054"},{"speaker":"鶴委員","kind":"質問","question":"ごめんなさい、細かいことばかりで。課でつくられたということですか。","respondent":"梶青少年育成課長","answer":"そもそもの物自体を委託ということではなくて、案文のフォーマットにつきましては課でつくってあります。","voiceIndex":134,"id":"exchange-055"},{"speaker":"鶴委員","kind":"質問・要望","question":"これは報告事項ということなのですが、やはり広告効果というのですか、見た目ですよね。どうしても特に表など、講演会のほうはちょっとかたいというイメージがあるのでしょうけれども、お子様が見られたときに「わっ、行こう！私などはこれを見て、結構もう大変お忙しい中でつくられたのかな、職員が努力されたのかとちょっと思ったのですけれども、もう少し工夫をぜひしていただきたい。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-056"},{"speaker":"阿部委員","kind":"質問","question":"今、先ほどは委託と伺ったのですけれども、これはどういうふうに、カラーコピーで刷ったような。これはどこに委託、幾らぐらいかけた委託なのですか。","respondent":"梶青少年育成課長","answer":"うちのほうでのカラーコピーで。実は、これが仕上がるのが１０月に入ってからなので、ちょっと今年度からそういったものは違うのですけれども、地元のほうで印刷はする予定です。","voiceIndex":137,"id":"exchange-057"},{"speaker":"阿部委員","kind":"質問","question":"ごめんなさい。これは委託した印刷でないということを聞いてほっとしました。これ、イベントも講演会も荏原地域ということなのですけれども、これは今回、たまたまなのですか。あるいは、場所を変えて毎回、来年は大井地域とか八潮地域だったり、たまたま今回は荏原地域でやるのでしょうか。地域バランスというのはどうですか。","respondent":"梶青少年育成課長","answer":"実は品川地域でやったりとか、荏原地域でやったりしているのですが、今年はそれがたまたま荏原地域だったです。","voiceIndex":139,"id":"exchange-058"},{"speaker":"阿部委員","kind":"意見","question":"わかりました。どうしても同じ団体に毎年投げてルーチン化しやすいものですので、ぜひ毎年、内容は精査してやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-059"}]},{"id":"topic-04","title":"のすまいるスクールの移管","agenda":"のすまいるスクールの移管","exchanges":[{"speaker":"南委員","kind":"確認","question":"それから児童センターとの関係では、前々回、６月の委員会のときに児童センターのあり方検討会が報告書を出していただいて説明いただいて、そこでも議論をしたと思うのですけれども、私もたしか小学校の低学年の子どもの児童センターにおける処遇について、たまたま来たよ、子どもがそこで遊んでいるよという、そういう対応の仕方ではなくて。","respondent":"安井子育て支援課長","answer":"今までどおり、そういうお子さんについてはどうしていらっしゃったのかとか、そこら辺のところはいろいろご事情もあると思いますので、きちんと対応をしていきたいと考えているところです。","voiceIndex":150,"id":"exchange-060"},{"speaker":"南委員","kind":"質問・要望","question":"ここにも書いて一番最後の５番に「学校との連携」であえて出ているわけですけれども、教育委員会所管になって、すまいるスクールが小学校の全校で展開されることになって、いろいろと学校によっては位置づけの問題からいろいろちょっと違いがあったのは事実だし、数年たつ中で一定程度の整理がされてきたのだろうと思っているのですけれども。","respondent":"安井子育て支援課長","answer":"私どもも虐待というわけではありませんけれども、そちらの子どもについての相談等も所管しておりますので、そこら辺の重要性は非常に認識しておりますので、そこら辺については学校と必ず連絡をとっていくというふうなことを考えているところです。","voiceIndex":152,"id":"exchange-061"},{"speaker":"南委員","kind":"質問","question":"今度は所管が違ってしまうので、その辺が非常に、例えば今までストレートに子どもの状況についてすまいるスクール側で感じた部分について担任なり、先ほどおっしゃった校長先生なりにお伝えできていたのが、今度は所管が違うことによって、行政ルートでこういうふうに行かなければいけないのかなということも、そういう危惧はどうしても私としては感じてしまうので、その辺については。","respondent":"安井子育て支援課長","answer":"そこら辺で何か形に残すもので明確にしておく必要性があるということであれば、それはまた細かい部分については詰めさせていただいて、そうはいってもいちいちルートを別に大きく回って、すぐに伝えなければいけない情報等もありますので。","voiceIndex":154,"id":"exchange-062"},{"speaker":"南委員","kind":"確認","question":"そうすると、両方の課の認識を、今、確認したので、安心はしたのですけれども、現場にそれはどういうふうな形で伝えていくのでしょうか。担当の職員、あるいは行っている、いわゆる担当されているボランティアの方々も含めたそういう方々へのこの問題での今の情報等の認識を今までのままですよということでよろしいのでしょうか。","respondent":"安井子育て支援課長","answer":"議会にこちらの方針についてご報告した後、それぞれ保護者の方であるとか、職員、それぞれ、委託業者も入っておりますので、そちらについてはこれからはっきりそこら辺のところを周知していくというような形で円滑な移行を図っていくということで進めていくです。","voiceIndex":158,"id":"exchange-063"},{"speaker":"南委員","kind":"質問・要望","question":"今まで整理されてきたレベルは、それはそのまま引き継いでいただきたいし、さらに子育て支援課で発展していただけるようにということをちょっとお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-064"},{"speaker":"阿部委員","kind":"質問","question":"幾つかお伺いしたいと思います。移管後のイメージなのですけれども、これ、私、余りイメージできなかったのですが、「１．目的」の後半のところで、すまいるスクールは正規職員を中心に民間スタッフを活用して運営しているが、職員の確保が困難になってきていると。これは移管後は、子育て支援課の職員の方々が正規職員となって民間スタッフを活用して運営するという形に変わるということなのですか。","respondent":"安井子育て支援課長","answer":"基本的には、今、庶務課づけになっているすまいるスクールの職員は全部子育て支援課づけになりますという考え方ですので、そういう意味でも、子育て支援課の職員かと言われると、そういうふうな形になりますけれども、基本的には、今、すまいるスクールにいらっしゃる職員の方。","voiceIndex":161,"id":"exchange-065"},{"speaker":"阿部委員","kind":"質問","question":"今のご説明ですと、多分、そのひとり職場であるすまいるスクールの人材供給源は、結局は子育て支援課系の職員の方でないとなかなか難しいということであれば、人事上の忙しさということも含めてこの移管はメリットと考えていいのかと、今、伺いました。それとも、今後していくというようなお考えはありますでしょうか。","respondent":"齋藤庶務課長","answer":"そういうふうにうまくやることで、台風のとき、震災のときも含めて一体として現場サイドでそのまま引き継ぐということで考えております。","voiceIndex":163,"id":"exchange-066"},{"speaker":"阿部委員","kind":"確認","question":"この後、確認事項になっていくのですけれども、例えば特別支援の受け入れについての方針も変わるところがないのか。そこはどのように整理されていらっしゃいますか。","respondent":"安井子育て支援課長","answer":"基本的に大きな事故とかの話になれば、学校でも非常に大きな問題になってしまいますので、そこら辺は従来どおりという形になろうかと思います。もちろん我々のほうでも、それに私どもも関与して対応はしていくという形でお考えいただければと思います。","voiceIndex":165,"id":"exchange-067"},{"speaker":"阿部委員","kind":"意見","question":"逆に、移管することによって子育て支援課ないし児童館とは連携をとりやすい形にはなっていくことを期待していいのかと思うのですけれども、具体的にこの移管をするからこういうことができる。あるいは何か考えていらっしゃることはありませんか。","respondent":"安井子育て支援課長","answer":"そこですまいるスクールから児童センターにいらっしゃったお子さんはどうしているのかなというようなことで、逆にこういう気持ちのお子さんもおりますよというような話をすまいるスクールにも伝えられるというようなことが日常的に行える可能性もあるのかな。","voiceIndex":167,"id":"exchange-068"},{"speaker":"阿部委員","kind":"意見","question":"今のサービスについては、あるいは連携体系については崩さないままでいろいろやっていきたいということです。これ以上言うよりも、むしろ移管した後でどのように運用されるかというところで見ていきたいと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":169,"id":"exchange-069"},{"speaker":"伊藤委員","kind":"質問","question":"ずっと今、みんなから言ったんですけれども、移管の理由について大きく三つ述べられています。事業自体を整理統合していくことについては、それは行財政改革の一環でしょうから、賛成するのですけれども、すまいるスクールを教育委員会から離して区長部局に移すというその理由づけについて、すみません、もう一度わかりやすくご説明していただければと思います。","respondent":"安井子育て支援課長","answer":"その中で青少年委員との関係は、今、児童センターとしてはそれとのタイアップ等をいろいろやっているところですけれども、今後、すまいるスクールをこちらのほうで受け入れたときに。","voiceIndex":170,"id":"exchange-070"},{"speaker":"伊藤委員","kind":"質問","question":"ところが、それをこの整理・統合するに当たって教育面ではなくて、青少年対策になる。ですから、教育なのか、青少年対策なのか、ざっくり言うとそういうことになるのかもしれないけれども、新しいものをつくり出すということかもしれないけれども、そのことについてどうお考えですか。教育なのか、青少年対策なのか、すまいるスクールの事業についてこれからの方向性は。","respondent":"安井子育て支援課長","answer":"すまいるスクールの中で行っている勉強会であるとか、そういったものは教育の部分で、非常に重要なものだと考えています。それは決して青少年の健全育成の中でそれを全く抜きに考えているわけではありません。","voiceIndex":172,"id":"exchange-071"},{"speaker":"伊藤委員","kind":"質問","question":"むしろそちらのほうが私たちとしては注目する点だと思います。ここに書かれているように児童センターの連携、青少年対策委員との連携、それから学校ですから学校現場との連携もそうでしょうし、教育の場の提供もそうでしょう、いろいろな要素を含んだ上で新たな事業として展開していくことをやっていかなければ、結果としてこの手がたくさんあると思うので、そのことについてあわせて答弁をお聞かせください。","respondent":"金子子ども未来事業部長","answer":"そういう意味では、さらに今後のすまいるスクールを一歩でも二歩でも進めていくために私どもとしても努力していきたいと考えています。","voiceIndex":174,"id":"exchange-072"},{"speaker":"伊藤委員","kind":"意見","question":"だとするならば、すまいるスクールの教育の伝統もしっかり残した上で青少年対策なりさまざまな物事を入れ込んでいって、結果としてすまいるスクールに通う子どもたちがより健やかな、もちろん勉強もした上で、それから学校とも十分連携をとる中、格好いいことを言うかもしれないけれども、それを全部満たしていかないと、おそらくこの行政、議員、すべての思いは活かされないと思いますから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":176,"id":"exchange-073"},{"speaker":"鶴委員","kind":"質問","question":"聞きたかったこと、ほかの委員から伺ったのであれなのですが、１点だけ。単純に職員側というか区側だけのここで言うところの集約化の効率的な円滑な運営だけで、結局、子どもがどうなっているのだろうかというところに重きが置かれないとよろしくないのではないかと思います。","respondent":"齋藤庶務課長、安井子育て支援課長","answer":"そういった意味で言うと、幾つか出てきたことを、今度は区長部局に移るということで教育ということのプラスアルファの部分が出てくるのではないかということで引き継いでいきたいと考えています。うちもそういうノウハウは持っていて、なかなかすまいるスクールが外へ出るのは難しいんですけれども、そういう場があれば、そういったところをすべてまとめて、まとめてと言うと語弊がありますけれども、参加することによって。","voiceIndex":177,"id":"exchange-074"},{"speaker":"高橋委員","kind":"質問","question":"今、教育委員会から成果を出しているというお話があったのですが、所管がこういうふうに移ってしまったら、学校の希求であるべきですが、学校は本体だけで今のところは文部科学省の管轄なのですけれども、もう放課後は隣の所管だよというような形で判断するというか、今でも、ややすまいるスクールはすまいるスクールだというところも一部のところでは弊害があったりするので。","respondent":"齋藤庶務課長、安井子育て支援課長","answer":"私も庶務課長になったときに前任の課長からは学校の校長先生の中で認識強化はあるんだよということは聞きました。確かにそれぞれの時期で年間の事業計画などのすり合わせをしているところもありましたけれども、さらにそこら辺のところが連絡を密にとり合うような形で連携を深めていくというような方向性はひとつあるのかなと考えています。","voiceIndex":180,"id":"exchange-075"},{"speaker":"高橋委員","kind":"質問","question":"適正配置の館長数見直し云々とか、いろいろなそこもいかがですか。","respondent":"安井子育て支援課長","answer":"今のところは適正配置、基本的に児童センターのほうは１３町内にそれぞれ館長館がありまして、それとまた小学校部分のすまいるスクールの問題と、在宅子育ての部分はまた別にありまして、在宅子育ての部分についても、今のところ子どもたちも非常に増えておりまして。","voiceIndex":183,"id":"exchange-076"},{"speaker":"阿部委員","kind":"質問・要望","question":"１点だけ。そのときの区側の説明としては、すまいるスクールは教育だからおやつは出さないと。教育だから６時までだよという説明の中でそういうものだったと思うのですけれども、それが今回、移管することで、もう１回そういったことが、要望があれば議論の俎上に乗り得る可能性は出てくるのかということなのでしょうね。あくまでも理屈の上での疑問です。","respondent":"安井子育て支援課長","answer":"そういうお話がいろいろあるのは、課題としては認識しておりますけれども、今のところ基本的に今までのすまいるスクールをそのまま移行という形で考えておりますので、すぐそれを課題としてすぐどう対応するとかというところまではまだいっていないところです。","voiceIndex":186,"id":"exchange-077"},{"speaker":"南委員","kind":"確認","question":"もう絶対に学校に設置しているから、学校の数が減らない限りすまいるスクールは減りませんよという、こういう考え方なのかどうかを確認したいのと、児童センターとの集約の中でその辺、すまいるスクールの位置づけはどういうふうになっていくのか、その辺を確認しておきたいと思います。","respondent":"安井子育て支援課長","answer":"すまいるスクールは、放課後の子どもを教育する事業です。あくまでも学校の施設を有効活用して子どもたちに放課後で安全で安心な居場所を提供するという事業だと認識しておりますので、それを根本的に切り替えるというふうな考え方はありません。","voiceIndex":188,"id":"exchange-078"},{"speaker":"南委員","kind":"質問・要望","question":"考えていないということを確認しておきたいと思います。やはり世の中は子どもの問題に非常に関心が高くなってきている。そういう状況の中で児童センターの果たす役割は、今よりもさらに期待も高まって役割が重要になってくると思いますので、児童センターの数を見直していく、集約していくという、そういう方向性はやめていただきたいということを改めて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-079"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"要望、１点だけなのですけれども、地域の方々、保護者ではなくて地域の方々は、ほとんどすまいるスクールは学校がやっていると思っている方が大勢いらっしゃいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-080"}]},{"id":"topic-05","title":"平成２３年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２３年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"何点か聞かせてください。区立家庭あんしんセンターと品川区立ぷりすくーる西五反田を誰が評価したのでしょうか。評価者は誰なのですかという記載が多分あると思うのだけれども、それが明確になっていないと思われますので、そのことをまずお聞かせください。","respondent":"立川保育課長、安井子育て支援課長","answer":"所管しております保育課で第一次評価をいたしまして、その後、区の経営会議等で皆が検証するということでやっております。私どもも同様でございまして、まず子育て支援課で評価をいたしまして、それから経営会議へ出しております。","voiceIndex":197,"id":"exchange-081"},{"speaker":"伊藤委員","kind":"意見","question":"その点は、例えば子育て支援課でも保育課でもさまざまな団体と指定管理を結んでいるわけであって、そうすると、次に聞きたいのは、要はほかのこういう指定管理者に対するモニタリング評価をやっているのだろうけれども、それがなぜ今、この二つが出てきたのかということが１点、それから、そのほかのさまざまな指定管理者に対するモニタリング評価をやっていると思うのだけれども。","respondent":"立川保育課長","answer":"指定管理者のモニタリング評価の制度ですが、これは全庁的に行われることでございまして、文教委員会所管の施設としましては子育て支援課の所管と保育課の所管で一つずつ増えましたというところで今回お出しさせていただきました。","voiceIndex":200,"id":"exchange-082"},{"speaker":"伊藤委員","kind":"質問","question":"子育て支援課と保育課の所管の中では、指定管理者に委託するところはこの品川区立家庭あんしんセンターと品川区立ぷりすくーる西五反田だけなのですか。","respondent":"安井子育て支援課長","answer":"こちらの２カ所だけです。条例上に指定管理をするということで載せているものと、児童センター等で委託している部分については、総合評価によって委託業者を決めているだけなので、これは指定管理なものだけ別物で設定するものです。","voiceIndex":202,"id":"exchange-083"},{"speaker":"伊藤委員","kind":"確認","question":"そういう仕組みでこの二つのモニタリング評価をしたことは理解しました。となると、そうすると、平成２３年度はここでやったけれども、当然、来年度以降はこの品川区立家庭あんしんセンターと品川区立ぷりすくーる西五反田が指定管理でやる限りはモニタリングをして評価をしていくという意味ですか、確認をお願いします。","respondent":"安井子育て支援課長","answer":"毎年、この２カ所については評価して報告します。","voiceIndex":204,"id":"exchange-084"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうしたら、少し何点か確認させていただきたいんですけれども、品川区立家庭あんしんセンターの下のほうにある「依頼会員」、「提供会員」、それから「依頼会員ＯＢ」とあるのですが、教えてください。これは何なのですか。","respondent":"安井子育て支援課長","answer":"説明の枠が非常に狭かったものですからわかりにくいかと思いますけれども、ファミリー・サポート・センターは地域の皆様で子育てを支援をするということで、依頼会員・提供会員がいらっしゃいます。登録されている、私はこういうお手伝いをします。","voiceIndex":206,"id":"exchange-085"},{"speaker":"伊藤委員","kind":"質問","question":"だから、単純には言えないかもしれないけれども、品川区にもシルバー人材センターがあります。全く内容を知らないので勝手に言っているのかもしれませんけれども、要はいろいろな人材をいろいろな仕組みを通して集めたらいいのではないですかということもお話だけはしておきますので、これから実現できるかどうかは全く事業の内容がわかりませんので、念のためにお話だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-086"},{"speaker":"阿部委員","kind":"質問・要望","question":"確認をさせていただきたいのです。この二つの施設の指定管理の期間はいつからいつまでだったでしょうか。","respondent":"安井子育て支援課長","answer":"昨年、更新させていただきましたので、平成２３年度からですから、平成２８年度までです。","voiceIndex":209,"id":"exchange-087"},{"speaker":"阿部委員","kind":"質問","question":"引き続きお伺いしたいと思います。品川区立家庭あんしんセンターなのですけれども、トワイライトステイとショートステイと、この利用率、お手元でわかる範囲でよろしいので、この３年間のはわかりますか。","respondent":"安井子育て支援課長","answer":"ここら辺のところはちょっとリーマンショック以降、残業が減ってきておりまして、平成２０年度は３,５５９回ということでしたけれども、平成２１年に減りまして、今はまた盛り返してきているというか、利用率が増えてきていると考えています。","voiceIndex":213,"id":"exchange-088"},{"speaker":"阿部委員","kind":"質問・要望","question":"そのために福栄会にもぜひ今以上に努力していただきたいと思ているのと、こういった状況を私はまだ改善の余地があると思っているのですけれども、ただ、このシートの中ではそういったことについては全く触れられていなくて、品川区としては、そこは特に課題と考えていないからこういうシートになるのか、それとも１枚Ａ４裏表にまとめなければいけないからそこまで書き込まれていないのか。","respondent":"安井子育て支援課長","answer":"このシートについては、このサイズで統一のものなので、なかなか形を変えるのは難しい部分もありますけれども、子育て短期支援事業については括弧書きで利用料を書いてありますので、こちらについてはアルバイトを使いながらそれだけ多く受ければ歳入が増えるという。","voiceIndex":217,"id":"exchange-089"},{"speaker":"阿部委員","kind":"質問・要望","question":"そこは子育て支援課長も強調をされていますけれども、もっと例えば周知一つとってもやりようは幾らでもあるわけですから、ぜひ、せっかく品川区がこういう事業をつくって福栄会にこういった事業を指定管理としてやってもらっているわけですから、それは区民の皆様方によりきめ細かく取り組むように、ぜひ福栄会とも連携をとりながらよりよい、きめ細かいサービス提供に努めていただきたいと思います。","respondent":"立川保育課長","answer":"実は報告いただいたところによると、教材費を幼稚園部門はいただいているということです。その教材費の部分で若干、現在、保護者からいただいている額を少し増やしたいという、そういう内容のご報告があります。","voiceIndex":219,"id":"exchange-090"},{"speaker":"阿部委員","kind":"質問","question":"それは報告事項であって、指定管理者の裁量の範囲内ということで区としては見ていらっしゃるということですか。","respondent":"立川保育課長","answer":"その保護者からお預かりする金額について若干違ってくるというふうに思ってあります。","voiceIndex":221,"id":"exchange-091"},{"speaker":"阿部委員","kind":"質問","question":"値上げを検討することが悪いと言っているわけではないです。先ほど伺いました指定管理期間ですと平成２６年度まで、また、平成２７年度になる前に、一応、指定管理者を選ぶという手続に入ると思うのですけれども、いつまでもＮＰＯ法人でいいのかということは、この組織と区の間でも少しコミュニケーションをとったほうがいいのではないかと思っているのですが、いかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"今のところ、今のＮＰＯ法人を変えていきたいというお話は直接お聞きしていませんし、相手方の意向の問題ですので、それについてはコメントする立場にないかなと考えています。","voiceIndex":223,"id":"exchange-092"},{"speaker":"阿部委員","kind":"意見","question":"わかりました。今後もやはり幼保一体施設ということで区とは密接な関係にあるＮＰＯ法人であると思いますので、コミュニケーションをよくして、よりよい方法を一緒に目指していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":225,"id":"exchange-093"},{"speaker":"南委員","kind":"質問","question":"品川区立家庭あんしんセンターのショートステイ・トワイライトステイについて、先ほど実績の数字が示されましたけれども、これはキャパシティーに対してどの程度の割合なのか、その辺を伺いたいのですけれども。","respondent":"安井子育て支援課長","answer":"ショートステイは、キャパシティーというのか、地域に２部屋しかありません。","voiceIndex":226,"id":"exchange-094"},{"speaker":"南委員","kind":"質問・要望","question":"なかなか利用率が見えないと、どんな状況なのか、適切な使用なのか、まだ空きがあって、もっと宣伝も含めてご利用の拡大を広げていく努力が求められるのか、それがちょっと見えないので、ぜひ利用率で示していただきたいと思っているのです。イメージがよくわからないのですけれども、１部屋に２０人を見るわけではないですよね。","respondent":"安井子育て支援課長","answer":"年齢が必ずしも一定ではありませんので、大きい子もいれば小さい子もいらっしゃいますので、それはそのときに応じて余りきちきちと仕切ってしまうとかえって使いにくいというところもありますので。","voiceIndex":228,"id":"exchange-095"},{"speaker":"南委員","kind":"質問","question":"そうすると、例えば直近の平成２３年の２１人で７７泊というのは、この定員２０人に対してどういうふうに見たらいいのですか。すみません、私、２１人で７７泊がトワイライトステイだと思って今言ったけれども、そうではなくてショートステイ。では、平成２３年は２,７６８回というこの数字に対してどういうふうに見たらいいのでしょうか。","respondent":"安井子育て支援課長","answer":"ただ、２０人の大きい子だけ全員で入るということはなかなかきつい形になりますので、部屋自体の大きさが変わるわけではありませんので、そういうのはなかなか２０人定員といっても難しい部分もあるところです。","voiceIndex":230,"id":"exchange-096"},{"speaker":"南委員","kind":"質問・要望","question":"ほとんど毎日いっぱいで、それ以上のご利用はお断りしなければいけないという状況ならともかく、こういう状況であれば、やはり大いに検討する余地はあるのではないかと思いますので、その辺についてぜひ検討はしていただきたいと思っていますけれども、いかがですか。","respondent":"安井子育て支援課長","answer":"そういう意味で、それを必要だからということでむやみに拡大するのは児童福祉の観点からは望ましくないもので、やはりそこら辺については病気であるとか、そういうふうな特別な事情の場合、あるいはもうやむを得ず出張に行かざるを得ない。","voiceIndex":232,"id":"exchange-097"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、他の自治体でやっていないケースではなくて、やっている現状がある中では、かたくなにそういう考え方にとどまらずに調査・研究を重ねて、そういう方々を救うという、そして子育て支援をしていくという角度で物事を考えてフレキシブルにとらえていくことが大事なのではないかと思いますので、ぜひその点は強く求めて直接的なこの場合ではないので、この程度で終わりますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":234,"id":"exchange-098"}]},{"id":"topic-06","title":"認証保育所保育料助成制度の改定","agenda":"認証保育所保育料助成制度の改定","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"でも、昔のことですから、一応、お伺いをいたします。そこら辺の努力をぜひこの際やっていただきたいと思うのですけれども、以上、２点、よろしくご答弁をお願いします。","respondent":"伊崎待機児童対策担当課長","answer":"平成２２年度からの保育料助成の差額助成の関係の経過ですけれども、当時、待機児童対策を区の緊急課題としてとらえるというところで、そちらの助成も含めて認可保育園の定員拡大、学校を使った協力の観点ということで五つの施策を打ち出しております。","voiceIndex":239,"id":"exchange-099"},{"speaker":"阿部委員","kind":"質問・要望","question":"これについては、今の形になったことで少しまた軽減されることは期待できますので、これに関しては私としては賛成です。認可保育園だから来るべきだというだけではなくて、親子の、特に子どもが過ごす場としてよりよい場所を認可保育園としても模索していってほしいという思いですので、そこは誤解なきようにお願いいたします。おわかりだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-100"}]},{"id":"topic-07","title":"認証保育所の新規開設","agenda":"認証保育所の新規開設","exchanges":[{"speaker":"南委員","kind":"質問","question":"建設中だというお話なのですが、新築ビルと理解していいのですか。そして、定員なのですが、３歳児以上ゼロになっているのですが、３歳児以上も受け入れる、そういうキャパシティーはあるということなのでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"こちらは２歳児までの園として認証を受ける予定ですので、現在のところは２歳児まで。ただ、この定員の中で３歳児以上のお子さんの希望があれば、定員の変更等は可能です。","voiceIndex":246,"id":"exchange-101"},{"speaker":"南委員","kind":"意見","question":"そうすると、現在は２歳児までということでオープンはするけれども、希望があれば３歳児以上も受け入れていく、今後の開設した以降、来年の４月、新規の応募がもしあった場合には３歳児以上児も受け入れていくキャパシティーはありますよと、そういうことなのですね。","respondent":"伊崎待機児童対策担当課長","answer":"ただ、どちらの園にもお話はしておりますが、３歳からは保育園や幼稚園に転園をお願いしていますが。","voiceIndex":250,"id":"exchange-102"},{"speaker":"阿部委員","kind":"質問","question":"開設が４月１日ということですけれども、募集の方法とタイミングを教えていただければと思います。","respondent":"伊崎待機児童対策担当課長","answer":"認証保育所は事業所が直接募集をすることになります。ですので、区としましては広報でお知らせいたしまして、１０月１日の広報「しながわ」で区民の方にお知らせしてまいります。は事業者がホームページなどで周知をしております。","voiceIndex":252,"id":"exchange-103"},{"speaker":"阿部委員","kind":"質問","question":"新規開設の報告を時々いただくのですけれども、毎回、いつからどういう形で募集をかけるのかという質問するのですけれども、今後はそうされていると思うのですけれども、最初からそのくらいまでは書いておいていただいてもいいかなと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":254,"id":"exchange-104"},{"speaker":"伊藤委員","kind":"質問","question":"運営費補助金についての月額のこの算定の基準が、今、事務事業概要を見ていたのですけれども、認証保育所等運営費等補助制度があって、その中の運営費補助金だと思うのですけれども、この算定は品川区独自でやっているのでしょうかというのが１点と、それから、当然、施設の運営費、それからキャパシティーに金額がかかってくると思うのだけれども、それは当然、運営事業者とも調節ができないと思うので。","respondent":"伊崎待機児童対策担当課長","answer":"定員別に、年齢別に定められております。２点目の事業者との打ち合わせというか、協議ですけれども、開設の提案があった以降、継続して事業者の要望、あと区の要望等をお互いにすり合わせながら同じく完璧にこぎつけております。","voiceIndex":255,"id":"exchange-105"},{"speaker":"伊藤委員","kind":"確認","question":"今のことで確認なのですけれども、東京都の基準でやっていることはわかったのですが、これは東京都のお金だけなのですか。品川区のお金も出ているのでしょうか。つまり補助金が両方から出ているということなのでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"認証保育所の運営費につきましては、平成１７年度から都区財政調整制度に反映されておりまして、そういう意味では区の一般財源でやっております。","voiceIndex":257,"id":"exchange-106"}]},{"id":"topic-08","title":"の最後となります(8)事業所型家庭的保育事業（保育ママ）の新規開設","agenda":"の最後となります(8)事業所型家庭的保育事業（保育ママ）の新規開設","exchanges":[{"speaker":"高橋委員","kind":"質問","question":"先ほどの認証保育所もこちらもそうなのですけれども、補助金として品川区が支出しているのですが、その運営状況をどれぐらいの頻度で見に行かれているのですか。この運営費の使い道は家賃もあるのか、先ほど事務事業概要を見たけれどもわからなかったのですけれども、家賃もあるのでしょうけれども、何に使ってはいけないとか、その使い道がいろいろ限定されているのでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"ちなみにうみのくに保育園あっとほーむふどうまえについては、家賃補助はございません。事業所型家庭的保育事業につきましては、月額２０万円以内の家賃の分を含んだものです。","voiceIndex":263,"id":"exchange-107"},{"speaker":"高橋委員","kind":"質問・要望","question":"なぜこういうことを聞いたかというと、以前、この文教委員会で視察に行ったときに、ある保育所で床に敷いたりしている、乳児が動いたりするその敷物がビニールのシートで、そこに乳児がはいはいしてもいいのかなみたいなものがあったのです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-108"},{"speaker":"阿部委員","kind":"質問","question":"ここの連携保育所というのはどこの保育所なのですか。","respondent":"伊崎待機児童対策担当課長","answer":"連携保育所につきましては、品川区立西五反田保育園ということで連携しながらやっております。","voiceIndex":268,"id":"exchange-109"},{"speaker":"阿部委員","kind":"確認","question":"地域によっては保育ママも少しずつ増えてきて、一つの園で複数の保育ママの監督ということではないのでしょうけれども、連携をとるようなことになってくると、だんだん大変なところも出てくるのかと思ってもいるのですけれども、今のところはそういう状況ではないのでしょうか。一応、確認です。","respondent":"伊崎待機児童対策担当課長","answer":"連携保育所につきましては、今のところは１園１カ所ということでやっております。","voiceIndex":270,"id":"exchange-110"},{"speaker":"南委員","kind":"質問・要望","question":"とりわけ、事業所型の保育所だとか認証保育所については、公立並みのさまざまな職種の方がいるわけではないわけですから、皆さん、保育に当たっておられる方はもちろん積極的に環境改善とか環境整備はしておられますけれども、しかし、狭いスペースの中での保育なので、きちんとしたチェックは補助金も出している上でするのは公の行政の責任だと思いますので。","respondent":"伊崎待機児童対策担当課長","answer":"家庭的保育事業の保育ママの展開につきましては、現状でもチェックシートはつくって展開はしております。ただ、今おっしゃられたように、いろいろとあるところまで具体に見ますとそのあたり、今まで以上に気を配ってチェックはしていくことを徹底していきたいと思います。","voiceIndex":272,"id":"exchange-111"},{"speaker":"南委員","kind":"質問","question":"言葉じりをとらえるつもりは全然ないけれども、いろいろなところもあるというふうなことで、それぞれの努力はしていながらも、財政的な状況もあって十分にやり切れないところもあるのかもしれないけれども、やはりそれは必要な指導ですから、特にゼロ歳の赤ちゃんは、即、命の問題になってきますので、そういう点でやはり厳しくチェックするのが行政の責任だし、事業を補完的にしていただくという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":274,"id":"exchange-112"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"昨日も申し上げましたけれども、木村健悟議員の質問に対する答弁の中で、学校での武道の事故はありませんというご答弁であったのですけれども、逆に医師のほうでは、学校の柔道の授業で頭を打って来た子がいるみたいな話を聞いたものですから、学校から教育委員会に事故として報告を上げる際の基準ですとか、学校と家庭の間での事故の総体の把握の仕方ですとか。","respondent":"太田指導課長","answer":"こういったような基準をもとに小学校に武道を導入した平成１８年度以降、事故の報告はないです。","voiceIndex":277,"id":"exchange-113"},{"speaker":"阿部委員","kind":"質問","question":"教育委員会としての基準はわかりました。それはそれで妥当なものだと思うのですけれども、結果的に、今、私が紹介した例が事実でないことはないと思うので、別にそれは言う必要がないわけですから、結果的に捕捉できないケースがあったと仮定しますと、どこに抜けがあるのか。もし今回の柔道のようなケースがあったとすると、多分、それに当たる可能性が高いかなと。その視点でご答弁をお願いします。","respondent":"太田指導課長","answer":"今までも例えば家庭で病院へ行ったということがあれば、すぐ学校には連絡をいただけるような状況に、今、してあります。今後もそういったことはできるように家庭にも連絡を密にしていきます。","voiceIndex":281,"id":"exchange-114"},{"speaker":"阿部委員","kind":"質問・要望","question":"それは、教育委員会というより、それぞれの学校が時々、検知的に１回来たからオーケーではなくて、やはりそれは例えば年度初めですとか、土曜休業になる場合、頭を打つケースも多いときですから、そういう部分は始めましょうとか、つまり、適宜、機会をとらえて繰り返しそういったようにしていくことが必要だと思うのです。そういう具体的な行動をぜひとっていただきたいと思います。","respondent":"太田指導課長","answer":"それは非常におっしゃるとおりですけれども、今回も今年度、武道の授業が始まるに当たっても、各学校、学校だより等を十分に活用して、家庭との連絡体制が強化できるよう環境整備に努めていくものと考えております。","voiceIndex":283,"id":"exchange-115"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4772#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":80916,"voices":298}},{"id":"h24-20120925-5","meetingId":"h24-cm09","date":"2012年9月25日","dateIso":"2012-09-25","committee":"総務委員会","time":"午前９時５９分～午後１時３８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査」を行います。「第５９号議案 平成２４年度品川区一般会計補正予算","agenda":"議案審査」を行います。「第５９号議案 平成２４年度品川区一般会計補正予算","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ニッセイ世論調査で５割が否定的、朝日新聞でも「期待をしない」が８割、あと、日経ビジネスサービスのインターネットでも７割が招致の否定をしているということを紹介して、都民の支持はないと紹介したのですけれども、区民の反応はどうなのかということと、前回、２０１６年オリンピック招致のときに、都全体でどれくらい税金が使われ、区にどれくらい招致関係で来たのか、わかったら教えてください。","respondent":"本城企画財政課長、柏原行財政改革担当課長","answer":"繰越金の件ですが、前回ご説明させていただきましたとおり、前回の６月補正で一定額使いまして、今回のこの額をもちまして繰越金となっているものは全て財源として活用したです。支持率の関係ですけれども、いろいろ今ご案内いただきましたけれども、例えば招致委員会の調査によりますと、前回５８％だったのが、８月終わりの段階で６６％に上がっているということで。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"オリンピック関係なのですが、品川区にどのくらい招致のためにお金が来ているかというのもわからないのでしょうか。品川区としては政府や都に向けてもっと震災復興のために力を入れるべきと進言すべきところなのに、一緒になって招致をこうやって税金を使っていって、なかなか盛り上がらない雰囲気を盛り上げていくという姿勢はいかがなものかなと思うのですが、その辺はいかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"東京都を地震などの災害に対しても強いまちづくりをするという１つの方向性、ベクトルには大きく合致していますので、こういったところでも大きな意義があるところではないかと考えています。","voiceIndex":8,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前回の２０１６年の招致は失敗に終わったわけですけれども、東京都はここに２００億円投入しているのですよね。結局は失敗している。開発の問題なのですけれども、２０、２１、２２、２３ページに防災関係でまちづくりということで予算が追加になっています。もう１点、本会議場で質問させていただいたのですけれども、車両火災の危険性について品川区としてどう捉えているのか、その辺を聞かせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なので、延焼遮断帯が必要というだけでこの補助２９号線、放射２号線を進めることは、災害の面からも大変危険であると考えていますが、もう一度その辺をお答えいただきたいのと、あと、荏原町のやはり防災関係なのですが、２２、２３ページ、荏原町駅前地区防災街区整備事業と書かれていますが、これも防災のためということなのですけれども、具体的にどういう事業なのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"高さ６０ｍ余りということなのですけれども、住宅が密集している、防災の効果を高めなくてはいけない地域であるというのは全く認識は一致しているところなのですけれども、なぜここが共同化で６０ｍもの高さになるのかというところがよくわからないのですが、ここになぜ６０ｍの高さになるのかという点を１つ教えていただきたいのと、あと、ここに税金がどのくらい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"歳入と歳出で、１３ページと２５ページ、２６ページでお話をお願いしたいのですけれども、１３ページから申し上げますと、教育費補助金とその下の委託金ということで、上から読み上げますと７９万８,０００円、７２万円、４０万５,０００円ということで、２５、２６ページを参照すると入って出ているのですけれども、伺いたいのは、特色ある教育活動経費で、４０万円ちょっと入っていますが、出のところで。","respondent":"本城企画財政課長","answer":"その部分が合同部活動実施経費と特色ある教育活動経費ということで２つにまたがっておりますが、あともう１つ、先ほどご指摘がございました特色ある教育活動経費が都の委託金ということで、都の委託事業としてそれは１００％、１０分の１０の負担の部分ですので。","voiceIndex":22,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"それはわかっているのですけれども、出と入りで数字がそこのところで数字はどうなっているのですかという話です。ここで４０万５,０００円で入って、４０万６,０００円で出ているという、これはどこかほかに４０万５,０００円で入ったのがまたあるのかどうかというのを教えていただきたい。","respondent":"本城企画財政課長","answer":"これは、４０万５,０００円と４０万６,０００円について……。","voiceIndex":24,"id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"だから、それはその特色ある云々という教育活動経費が、土曜日補習外部……、表題があるから入っているのだけれども、この４０万５,０００円と４０万６,０００円は入って、出の数字がこれとこれで一致するのですかという話。","respondent":"本城企画財政課長","answer":"失礼しました。この事業は２つの……。","voiceIndex":26,"id":"exchange-008"},{"speaker":"大沢委員","kind":"意見","question":"事業の内容ではないので。１,０００円、なぜ違うのだということです。","respondent":"本城企画財政課長、日下部企画部長","answer":"事業が全体として計上されているので、その内訳の関係で差が出ているです。改めてご説明をしますと、補助基本額というのは、要するに全体の事業費の中で補助対象として東京都が認められる金額は幾らだというものです。","voiceIndex":28,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"そうするとこれは歳入と歳出ですから、あくまでも入りと出ということは、ここの補助事業である以上、実績に応じてある程度の多くかかったということで、必ずしも一致することではないということでいいわけですか。","respondent":"日下部企画部長","answer":"ですから、先ほど申し上げました４０万６,０００円に対して、補助金額がたった１,０００円ではありますけれども、４０万５,０００円というケースも出てくるということでご理解いただきたいと思います。","voiceIndex":31,"id":"exchange-010"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１点確認をさせていただきたいのですが、オリンピックの招致特別区共同事業助成、１５ページに、宝くじ等助成金収入とありますが、区長会から各２３区にそれぞれ一斉に回る費用と、東京都に２億７,０００万円ですか、招致のためにという話が私の記憶ではありますが、区長会がそういった財源をまず持っているのかどうか。","respondent":"柏原行財政改革担当課長","answer":"それから残りの２億７,０００万円をオリンピック招致委員会ということで、これも特別区には助成金という形、それからオリンピック招致委員会のほうには助成という形になろうかと思うのですけれども、そういった形で出しているという流れになってあります。","voiceIndex":34,"id":"exchange-011"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、この宝くじ等の収入は区長会で事業を企画して、別途区長会に助成がおりる、その区長会がそのお金を使える権限を持っているのでしょうか。","respondent":"本城企画財政課長","answer":"今の答弁と重なりますが、今回、もともとの元手としては宝くじの収益金として来たものですが、それが団体間の流れとしては、公益財団法人の区市町村振興協会から区長会にお金が流れまして、それを元手として支出するということでございまして、１回。","voiceIndex":36,"id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"意見","question":"そうすると、公益財団法人が５億円を区長会に流しますといって、区長会でその５億円を何に使おうかといってオリンピック招致に使う決定をしたのか、それとも公益財団法人がそもそもその５億円をオリンピック招致のために使ってくださいと言って区長会に５億円をお渡しして、区長会として２３区で１,０００万円ずつプラス東京都に残りの２億７,０００万円を渡すという決定をしたという。","respondent":"日下部企画部長","answer":"ただ、実際説明をご覧いただきますと、いわば事業費としてはこのようなオリンピック招致の特別区共同事業助成金という形で事業としての位置づけをさせていただいているですので、わかりづらい面がありますが、ご理解いただきたいと思います。","voiceIndex":40,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の件ですけれども、区長会に、最初からすると５億円が毎年入るように聞こえてしまうのだけれども、それはオリンピック招致、区長会が要請したのではないのですか。事業を区長会から推進していったわけではない。最初から区市町村振興協会から５億円区長会に毎年入るように聞こえてしまうのだけれども、そうとっていいのでしょうか。","respondent":"日下部企画部長","answer":"今回は、そういう１つの区市町村の振興を図るという趣旨のもとでオリンピックの招致活動が区市町村の振興という観点とまさしく一致した内容であるということで、オリンピック招致活動に幾ら使いましょうということになったわけでありますけれども。","voiceIndex":46,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"毎年の金額は確定していない。その年によって変わると。今年はオリンピック招致があるので５億円という。その前段として私が思ったのは、区長会なり市町村がある程度要請したのではないのかなと。そちらの意思が働いていないのですかという意味を聞きたいのですが。","respondent":"日下部企画部長","answer":"ですから、これは今発行額が毎年そんなに大きくは変わっておりませんので、そんなに大きく変わるということはありませんけれども、おおむねその夏と秋の宝くじの収益金の総額について、それをどう活用しようかということで毎年度決めている流れです。","voiceIndex":48,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。オリンピック招致も目的が決まっているし、他区でも具体的にどんどん事業計画が出ていますので、ぜひ有効に活用していただきたいと思います。それからもう１点、衛生費の予防接種費用について２億１,９８５万３,０００円、一般財源から２億１,４００万円という数字が出ておりますけれども、この一般財源というのはあくまでも自主財源ですよね。そこら辺をもう一度確認させてください。","respondent":"本城企画財政課長","answer":"これについては平成２４年度、幾らになるかまだ確定はしておりませんが、この値上がった部分を踏まえた額になる見込みだと考えているところです。","voiceIndex":50,"id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"確認","question":"そこを聞きたかった。要するに財調で歳入にならないのというのを聞きたかったので、ただ、今年度の予算の中にこの数字はまだ入っていないわけですよね。だから先にこの一般財源で出てくるけれども、これからの調整をどうしていくのかなということを確認したかったので。","respondent":"本城企画財政課長","answer":"それについては、これから平成２４年度分について、特別交付金の分も含めて年末にかけて都と協議することになりますので、その中で、かなりの部分が入ってくる見込みで考えております。","voiceIndex":52,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう１つだけ。最終補正でこの部分は財調が増えてくると考えておけばいいということですか。","respondent":"本城企画財政課長","answer":"その協議結果を踏まえて、来る見込みの分を最終補正の中で組んでいくです。","voiceIndex":54,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"提案","question":"反対します。意見表明をさせていただいてよろしいでしょうか。ところが、こういった高層化、税金を投入するのだったらば、低層でも燃えない、倒れないまちづくりをぜひ提案すべきと思います。これは品川区内、実績があるわけですから、こういった面も十分考慮しなくてはいけないといった面では反対ということで、以上、３点の理由を延べさせていただきましたが、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-019"}]},{"id":"topic-02","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"中身、大丈夫です。その中で、非常に細かいところで意味も変わらないのですけれども、昨日審議した請願の中では、記書きの中の「平成２５年度以降も継続する」とあります。請願は「以後」なんですよね。あえてそれを直したのか、そこだけ。意味合いは同じだから、どっちにしてもこのままでも変わらないのですけれども、そこだけ確認を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-020"}]},{"id":"topic-03","title":"所管事務調査」を行います。本日は、所管事務調査といたしまして、「契約","agenda":"所管事務調査」を行います。本日は、所管事務調査といたしまして、「契約","exchanges":[{"speaker":"石田（慎）委員","kind":"質問","question":"２ページの上段のところ、随意契約５６件、平成２３年度の部分なのですが、これは括弧内で１３０万円強のもので随意契約が５６件、１ページ目の随意契約にところでは工事に関して１３０万円以下とあります。ということは、あくまでもこの５６件はプロポーザル方式による随意契約が５６件だという認識でよろしいのでしょうか。それが１点。ほぼ倍の数字になっています。","respondent":"平澤経理課長","answer":"ただ、その積算に当たって具体的なこの部分が幾らなのかといったところは、積算における秘密というのですか、それが全部わかってしまったらもうけをどの部分まで見込んでいるかとかそういった部分までわかってしまうということもありますので、非常に難しい部分もありますが。","voiceIndex":77,"id":"exchange-021"},{"speaker":"石田（慎）委員","kind":"質問","question":"１点だけ、最後の部分で、労務単価を区として教えると積算のものがわかってしまうからと言いながらも、インターネット等でどこでも調べられるというのは理にかなっていないのかなと思うのですが。調べられるのであれば、別に区としてそれをお知らせしても何の問題もないと思うのですけれども、その矛盾点をどう考えているのか、教えてください。","respondent":"平澤経理課長","answer":"それを開示してしまったら、それは繰り返しになって恐縮なのですけれども、どこの部分がもうけにつながっているか、そういうところまで開示してしまいまして、それについてはやはり工事積算の秘密というのですか。","voiceIndex":79,"id":"exchange-022"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、例えばその予定価格を契約する際に示さないときには確かに積算がこれで幾らでどうこうというのがわかってしまうと、何となく予定価格がわかってしまうから危険だというのはわかるのですけれども、例えばア、イ、ウ、エ、オのエで、予定価格を事前に公表する部分に関しては、その積算がわかってはまずいというのが関係がないのかなと思うのですけれども、その点はどうなのか教えてください。","respondent":"平澤経理課長","answer":"予定価格の公表についてご説明させていただきたいと思います。","voiceIndex":81,"id":"exchange-023"},{"speaker":"阿久津委員","kind":"質問・要望","question":"私からは大きく１点と、あと意見を述べさせていただきたいのですが、まず大きな１点として３ページの総合評価方式についてお伺いさせていただきたいと思います。直近、平成２３年度で結構ですので教えていただきたいということと、平成１９年度からこれを導入されて、区としてどのような感触というか、評価をされているのか、お聞かせいただけたらと思います。","respondent":"平澤経理課長","answer":"平成１９年度から実施してきたですが、一番最初にやりましたのが品川区の総合庁舎の耐震化の工事で総合評価を入れてやりました。次にやったのが舗装の部分で、平成２１年度で２件ございました。","voiceIndex":84,"id":"exchange-024"},{"speaker":"阿久津委員","kind":"質問","question":"これはかなり前の話なのですが、これについて国の動向等を何かお聞きになっている部分があれば教えていただければと思います。","respondent":"平澤経理課長","answer":"ただ、始める前に意見を聞いたときに、これはという疑問がついたものにつきましては、実際に入札したときにもう一度やりなさいということになってございまして、そこの部分が始める前にやるということで、委員のご指摘のとおり、やっぱり年度末と申しましょうか。","voiceIndex":86,"id":"exchange-025"},{"speaker":"阿久津委員","kind":"質問","question":"実情はよくわかりました。国の動向をこれからも注視されていかれるということで、平成１９年度からずっと続けられていて、いずれにしても審査会を総務部長のもとで開かれて、そこでいわゆる価格以外の部分でいろいろ審査をすると。あるのかどうかというか、こういう考え方についてのご見解を伺いたいと思います。","respondent":"平澤経理課長","answer":"こちらにつきましては、国の考えそのものがそういったところにありますので、そういったところを試行の中でどうやって取り入れていくかということについて、十分検討させていただきたいと思っているところです。","voiceIndex":88,"id":"exchange-026"},{"speaker":"阿久津委員","kind":"質問・要望","question":"今すぐにということではないのかもしれませんが、まさに災害は本当にいつわかるかわからないということで、総合評価方式、例えば１件でも２件でもこういった評価項目を設けて出していっていただきたいというところが、今回の私が質問させていただいた趣旨です。前回ですか、前々回の総務委員会で、いわゆる辞退をした企業がたくさん出たという契約案件がありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"契約ということは本当に区民の税金を正しく使うという意味ではすごく重い部署であって、区長はじめ権限があちこちにおありという状況で教えていただいて、大変なお仕事であると思っていますが、まず１つに権限のところで、まず区長に権限があって契約事務規則でそれぞれの部長、課長、主管課長に委任をされていると書かれているのですが、実際に年間を通してどこでどのようにチェックをされて。","respondent":"平澤経理課長","answer":"２点にわたるご質問です。契約権限のことです。この権限がある課に対してどういったチェックをしているかということでございまして、まずはじめに、チェックというより未然防止ということで研修等を必ずやってあります。","voiceIndex":92,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１つは、ＪＶを組んだ後の実施の状況がきちんと確認されるのかどうか、その辺を教えていただきたいのと、最後ですけれども、公契約のところで、品川区の取り組みというところで書かれています、ぜひ品川区にもやはり業者がしっかりと生活できるような状況、労働環境もそうですが、賃金状況もしていただきたいという願いがずっと届いていますので、今後に大いに期待をしていきたいのですけれども、さっき。","respondent":"平澤経理課長","answer":"最後に公契約につきまして、いろいろな考え方ですが、まず１点、規範となるところがこちらにも書いてあるところではありますが、品川区の取り組みのところ、３番の上の欄に書いてあるところでございまして、区といたしまして。","voiceIndex":96,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひそういった方向に進んでいきたいなと、これは要望で終わりますけれども、よろしくお願いしたいと思います。","respondent":"平澤経理課長","answer":"先ほどもご説明いたしましたが、親になる会社の名簿、それから子どもになる会社の名簿をつくります。子どもになるところは区内事業者ということで私どものほうで作成しています。","voiceIndex":98,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほど総合評価方式の契約の件、たしか前の行革特別委員会か何かでも一覧表を出していただいて、ポイントと価格点と出していただいた記憶がある。今現在の、当然価格が重点的にはなっているのですけれども、価格点と評価点、どのくらいのバランスを見ているのか、そこをまず教えてください。","respondent":"平澤経理課長","answer":"５０％、５０％です。","voiceIndex":101,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先ほどもご意見が出ていましたけれども、その中に、当然その前の段階で区内業者というのはありますけれども、区に対しての協力度合い、この辺のポイントもやはり高めていただきたいなというのが私どもも以前から要望はしております。それからその下の公共工事代金債権信託と、次のページの中間前払いと前払い金、これは併用できるのですか。","respondent":"平澤経理課長","answer":"併用できます。","voiceIndex":103,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問","question":"債権信託制度を読んでいると、債権を現金で金融機関から受け取ることができるということは、これは借り入れではなくて、区が払うからということで、直接金融機関と業者の関係はどう考えたらいいのですか。","respondent":"平澤経理課長","answer":"債権を譲渡しまして、区は銀行にお金を支払う形になります。業者が先に債権を担保してもらってしまいまして、区がその工事ができ上がったときに銀行にお支払いするという図式です。","voiceIndex":105,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そこはわかるのだけれども、銀行から借りるのではなくて、極端に言うと区から借りているという感覚をとればいいのかな。銀行と業者間のお金の流れは、ちょっとはわかるのだけれども、貸し借り関係とか、手数料というのは区に対して業者が払う、年率２.０３７％というのは業者が区に払う分の金額と考えればいいのか。","respondent":"平澤経理課長","answer":"説明不足で申しわけございません。この年率というのは銀行の利息のことです。ですから、銀行から借りるという形です。区はこちらの代金の信託制度の契約には直接は関与しないということになります。","voiceIndex":107,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それからもう１点、随意契約の関係です。区の中であまりないかもしれないのですけれども、今、各工事の中で、具体的に言ってしまうと品川清掃工場がありますけれども、ああいう企業ですと焼却炉ですと特許を持っているから１回契約するとそのまま補修工事は随意契約でいきますよね。よく昔はコンピューター関係という話もあったけれども、その辺、品川区の場合ではそんなに影響がないのかどうか。","respondent":"平澤経理課長","answer":"付帯工事のところが随意契約になる場合がありますが、例えばなのですけれども、工事を実施するに当たって、地面を掘っておりまして埋設物が出てきてしまった、それを撤去する。","voiceIndex":109,"id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問","question":"最初に例を挙げたような大きい焼却炉の工事の中で、特許が絡んでずっとそこでないと、随意契約しないといけないというのは特別にないと判断しておいていいのですか。","respondent":"平澤経理課長","answer":"今のところ、そういった例はないということなのですが、緊急というのですか、例えば震災や嵐や何かがあった場合に、そういうもので随意契約でやるという場合が出てくるかもしれません。","voiceIndex":111,"id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"確認","question":"一般論としてわかりました。それで結構です。それから、電子入札案件１０６件と３５件とあるのですけれども、電子入札、いい面、悪い面、悪いと言っては変ですけれども、区内の業者にとって相手が、範囲が広いだけにどこまで条件を絞れるかわからないので、この辺は今後の方向性としては電子入札は増やしていく感じになっているのか。もう１回、確認をしたいと思います。","respondent":"平澤経理課長","answer":"増やしていくのかどうかですが、こちらにつきましては、事業者の動向や何かもありますので、それを見極めた上で今後判断していきたいと考えているところです。","voiceIndex":113,"id":"exchange-037"},{"speaker":"須貝委員","kind":"質問","question":"区の考え方をお聞きしたいということと、それから契約締結の権限ですが、ここに各課長なり学校長、また、経理課長の判断によるとあるのですが、これは課長の判断ということですが、ほかでチェックすることはこれに対してはもうないのでしょうか。ここで課長の権限が１,０００万円未満であれば、それはそれで課長の権限で通ってしまうのでしょうか。","respondent":"平澤経理課長","answer":"３つ目の談合防止で電話、ファックスのことですが、こちらにつきまして、そういった不正をやった場合、品川区からは、指名停止になるとか、社会的な制裁も受けるということもございまして、会社で電話をかけているところまでは私どもでチェックができないところではありますが。","voiceIndex":116,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"質問とかではなくて、委員長にお願いなのですけれども、よろしいでしょうか。契約に関して１回で終わりではないと思うので、要望を出しておきたいのですけれども、よろしいでしょうか。予定価格とか積算の基準のところがわからないので、調べてもどこをどう調べていいかわからないので、その点に関してわかるような、出せる範囲で結構です、資料を出していただけると要望したいのですが。","respondent":"松澤委員長","answer":"こちらの正副で考えて、後ほど考えを言います。","voiceIndex":119,"id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後の質問の中で、下請けのところで要望、委任があったときという話があって、これは区として法的にそれを受けることはできるのですか。難しいとなっているけれども、そこら辺どうですか。","respondent":"平澤経理課長","answer":"実際にそういった例が全くないので、わからない部分がありますが、ただ、事業者が潰れてしまったような場合ですか、そういった場合は債権者に金額をお支払いする例があるということでございまして、法律上ということで大変難しい話ですので、そういった事例があった場合。","voiceIndex":121,"id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"確認","question":"工事途中で会社が潰れたとき、下請け会社が代金をもらえないケースがあったので、そこら辺のことで確認をしたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-041"}]},{"id":"topic-04","title":"ここで議決をして本会議で決まった後に、議会事務局から改めて請願者にこういう意味で出しましたというご案内をいたしますので、よろしくお願いいたします。 それでは","agenda":"ここで議決をして本会議で決まった後に、議会事務局から改めて請願者にこういう意味で出しましたというご案内をいたしますので、よろしくお願いいたします。 それでは","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この視察先はどこも市のほうで、ご説明をいただけるということでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1926#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":49190,"voices":144}},{"id":"h24-20120926-14","meetingId":"h24-cm09","date":"2012年9月26日","dateIso":"2012-09-26","committee":"行財政改革特別委員会","time":"午前１０時００分～午後０時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"しいては、区民の関心も高いというわけですから、例えば初めから第１委員会室で開催するとか、また、案件によっては調整するとか、そういったことは検討していくべきだと思いますので、ぜひ議会運営委員会の委員長にこの旨を報告して、全体で議論を投げかけていくことが大事じゃないかなと思うんですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"委員会の場所を、どこで開催するかというのは議会運営委員会で話し合っていることですので、ぜひ議会運営委員会委員長に伝えていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-002"},{"speaker":"須藤委員","kind":"意見","question":"だけれども、それはまた、ここの中でする話じゃないから、それは各会派でそれなりに、自分のところで幹事長なり出している会派なんだから、そこから進めていくべきで、委員長がどうのするというのは違うと思うと私は思います。それも承ってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"旧第一日野小学校跡地の貸付","agenda":"旧第一日野小学校跡地の貸付","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それが基本協定書、契約書の中にどういう言葉で明記されているのか、伺いたいと思います。最後に、桜の木のこともありましたけれども、今度、９月２９日に見学会を行うと、同窓会の要望を聞いていただいたことは歓迎したいと思いますが、やはり卒業生から伺ったのは、卒業記念に焼いたタイルを壁に張ってあると。埋めてあるタイムカプセル、これが一体どうなってしまうのかという話を伺いました。","respondent":"柏原行財政改革担当課長","answer":"先ほども、これ、ご説明申し上げましたけれども、五反田ＴＯＣビルの、本社ビルのほうですね、整備方針といたしましては、先ほど申しました大きな点ですね、３点と、それからまちづくりビジョンとの調整、整合を図るということを申し上げました。","voiceIndex":14,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"こうした経過からも、実際どういう中身の協定書、契約書を結んでいるのか、そのことをしっかりと提出していただきたいと思いますが、いかがでしょうか。この間の説明不足の経過もあったから、いろいろ回覧板やＰＴＡの説明を行っているわけですから、地元住民への事業説明会も引き続き開催すべきだと思うんですけれども、拒む理由がよくわからないので、ご説明いただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"今後の解体であるとか、事業の、建物の建て替えであるとか、建築工事であるとか、そういったところでの説明会もその都度ありますので、であればそういったところに、どういった形で我々が関与できるかというのは調整していきたいと思いますけれども、そういったところで。","voiceIndex":16,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"区も説明責任を果たすべきだと思いますので、ぜひ実施していただきたいと思いますが、ここを改めて伺いたいと思います。例えば「事業終了後速やかに」というのも、建て替え時の完了というのをどう思うかというのは、区とＴＯＣで合意しているんでしょうか。つまり、協定書や契約書にこのことがどう明記されているのか伺いたいと思います。伺いたいと思うし、実際にどう明記されているのか、根拠も伺いたい。","respondent":"柏原行財政改革担当課長","answer":"何点かご質問いただきました。説明会等々につきましては、先ほどと同様の答弁になってしまいますけれども、説明会、例えば工事説明会であるとか、そういったところでもあります。","voiceIndex":18,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう契約書というのは信じがたいんですけれども、具体的にどういう言葉で書いてあるか聞きたいんですけれども、要するにおおむね８年を超えた場合は、いかなる理由でも更地にして戻してもらうという強い契約なのか、それとも例えば、ＴＯＣの経営が困難で、また計画が延びてしまったとか、予定したよりも都市計画決定に係る手続に時間を要したとか、経済が悪化してちょっと困ってしまったとか。","respondent":"日下部企画部長","answer":"ですから、これ、当然、議会、それから、近隣住民の皆様方のご要望も含めてできるだけ早い段階で、一方で、社会経済全体の動きもしっかりとにらみながら、できるだけ早い段階で跡地の本格活用、どうしていったらいいのかということで検討を進めるということで考えております。","voiceIndex":21,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に。先ほど、１つ伺った件がなくて。公の契約ですから、一つひとつの中身がどういう文面なのか、私は確認したいと思っているんですね。なので、出していただきたいと思ったので、改めて伺います。ぜひ地元説明会を継続して、ＴＯＣの貸し付けではなく、住民要望に沿った活用、保育園や、特別養護老人ホームや、防災公園や、こうした活用こそすべきだと思いますけれども、いかがでしょうか。","respondent":"日下部企画部長","answer":"確かに今回のＴＯＣにつきましても当初予定がおくれたという点、この辺、ですから、想定外といいますか、ということもあり得るわけですが、ただ、私どもはやはり、一度、２年間おくれたわけでありますので、ＴＯＣにもしっかりと私ども申し上げておりますのは。","voiceIndex":23,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、確認だけさせてください。それから、もう一つ、最大は、土壌汚染だよね。そこら辺のところはよく説明していただきたいなと思うので、調査して、はい、だめでした、ばあっといくのではなく、そこはよく、調査した結果、移植は非常に難しいとか、そこら辺のところは町会を通じる、同窓会、ＰＴＡを通じてしっかり説明していただきたいなと思うので、この２つだけ教えてください。","respondent":"柏原行財政改革担当課長","answer":"こちらのほうも、仮にそういった形しか選択肢がないといったような場合には、同窓会、町会の方々にはきちんとご説明させていただいて、例えば残った木でモニュメントをつくるとか、いろいろな考え方があるかと思うんですけれども、そういったところも含めて。","voiceIndex":25,"id":"exchange-009"},{"speaker":"鶴委員","kind":"質問・要望","question":"(6)の「その他」の細かいところの確認をさせていただきたいと思います。2)の最後のほうの解体工事に際しての「安全対策に十分配慮する」とあるんですが、これについては、校舎を解体する際に、１回ぐらい委員会をあれだったので、もしかしたら議論があったのかもしれませんけれども、地域の方の声としては、解体する際にアスベストとかそういうのはあるんですかという。","respondent":"柏原行財政改革担当課長","answer":"建て替え工事、それから仮設の工事、全てそうなんですけれども、例えば今、例として出ましたアスベストのことにつきましても、一定程度、工程表みたいなものを確認させていただいているんですが、既にアスベストがあった場合にはその処理をどうするかとかいうことも含まれて。","voiceIndex":27,"id":"exchange-010"},{"speaker":"鶴委員","kind":"意見","question":"たまたま似たような地域で、区の施設ではなかったんですけれども、民間の施設で、たまたまアスベストのある古い建物を壊すときに、いきなり、突然工事が始まって、説明がなかったという、これは民間のあれだったので、きちんとした説明がなかったというところで、それで区のほうに相談させていただいて、改めてそこに足を運ばせてやったということがあったので、そういったところで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-011"},{"speaker":"塚本委員","kind":"確認","question":"今回、建て替えによって卸売商業、流通商業機能を強化するとか、また中小、ベンチャー企業の活躍が可能な業務空間とかいうことで、まだ計画のしっかりした設計図が出ていませんけれども、現状よりもより一層店舗数とか、こういったスペースも増えて、具体的に物理的にも十分な店舗数とかいうものが増えていく、こういう理解でよろしいでしょうかというのを一つ確認をさせてください。","respondent":"柏原行財政改革担当課長","answer":"店舗数がどのぐらいになるかとか具体的にというのはまだ正確なものが出てこないのでわからない部分はあるんですが、ただ、今、こちらの協定で結ばせていただいたとおり、こういった行政の大きなテーマがありますので。","voiceIndex":30,"id":"exchange-012"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。ぜひよろしくお願いしたいと思います。おおむね８年ということで計画されていると思いますけれども、８年間というといろいろなことがあるかなと思いますが、一日も早く新たなＴＯＣがオープンして、地域の皆様、また品川区全体の活性化に、楽しみにされている方もたくさんいらっしゃると思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-013"}]},{"id":"topic-03","title":"の２、特定事件調査","agenda":"の２、特定事件調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"規模別所有状況、５０m2ずつに分けた理由は何か、基準ではなくわかりやすく分けたものという説明がありましたけれども、規模によって例えば土地の有効活用だったり、施設の利用だったり、区の政策的な判断というのは何か念頭に置いているものがあるのか、よく、昔どぶみたいだったところは、接している人は買っていただきたいと思うけれども、接している人はなかなかお金を払ってまでというところが。","respondent":"柏原行財政改革担当課長、平澤経理課長","answer":"こちらにつきましては、先ほども若干ご説明の際に申し上げたんですけれども、特に何か大きな意図を持ってというよりは、資料をつくっていく中で一定程度の傾向が見えてきたものですから。起債の関係につきましては、申しわけございません、起債が終わって教育財産が外れるかとか、そういうことにつきましては後ほど、お調べしてお答えします。申しわけございません。","voiceIndex":38,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"それと、財産について、例えば文化センターとか、社会教育施設とか、細かく見るといろいろ施設の特徴の名前を聞くんですけれども、位置づけによって何がどう変わるのか、例えば荏原文化会館と、五反田文化会館と、今度できる平塚のところの新しい文化会館と、社会教育施設であるか、ないかで何か変わってくるのか否か、きゅりあんとか、ホール的なものでもいろいろな位置づけがあると思うんですけれども。","respondent":"平澤経理課長、柏原行財政改革担当課長","answer":"前段の手続に関してご説明申し上げます。荏原第四中学校、学校としての使用目的を終了しますと、教育委員会から総務部長宛てに移管と申しましょうか、手続があります。すみません、ご質問にきちんと答えられるかどうかあれなんですけれども、文化センターということで社会教育施設という形で、逆に例えばきゅりあんであるとか、今度新しく平塚の部分のものですが、一定程度目的であるとか。","voiceIndex":41,"id":"exchange-015"},{"speaker":"鶴委員","kind":"質問・要望","question":"遊休地があれば早期に売却してくださいねということが財務省から話がたしかあるとは思うんですけれども、その早期にということに対して自治体としてというか、品川区としてもそういう感覚というか、考えでいるのかどうか、それを確認させていただきたいのと、あと、普通財産の中で、基本的には先ほどちょっとありましたけれども。","respondent":"平澤経理課長","answer":"初めに大きいものから、恐縮ですが、例えば福栄会の敷地、それから旧まちづくり事業用地と申しまして、先ほどちょっとご説明申し上げました劇団四季に大井町駅前のところで駐車場で貸している部分、それから今回話し合いをさせていただきました旧第一日野小学校の跡地。","voiceIndex":44,"id":"exchange-016"},{"speaker":"鶴委員","kind":"確認","question":"３,０００m2以上のところが全体の中でもありましたけれども、それを知りたいなと思って。それから、物納については寄附的なことの、そういう言葉で表現するのかどうかあれですけれども、例えば直接自治体に何かおさめるということはないのかもしれませんけれども、現金的なものでおさめなくて、それをまさに物納するという、そういう角度のものも含めてないんですかね。","respondent":"平澤経理課長、日下部企画部長","answer":"民有地に隣接する部分で、例えばなんですけれども、用水の跡とかそういった部分につきましては、これは販売を国と同じような考え方で行っているところです。財産として現金にかえて活用するというのが原則だと考えているところです。それを今度、ふれあい作業所の一つの施設を建て替えをすると。それにあわせて用地を財務省のほうから取得すると、そういう話は聞いてあります。","voiceIndex":46,"id":"exchange-017"},{"speaker":"稲川委員","kind":"質問","question":"ちょっとお伺いしたいんですけれども、行政財産、普通財産というのがここに件数が今、明記されていますが、これが基本的に、道路用地を除いた区が所有している土地という考えでよろしいのかをまず１点お聞かせください。それと、よく狭い、おそらくゼロから５０m2ぐらいだと思うんですけれども、無番地という、多分、品川区内に結構あると思うんですよね。","respondent":"平澤経理課長","answer":"ただ、先ほどちょっとご説明申し上げた普通財産の中で、非常に狭い土地で、用水の跡みたいなところがあって、そこを現在、交渉している最中のもの、そこの部分がそれに当たっているかもしれません。","voiceIndex":49,"id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"先ほどの質問で用水の跡という、道路は道路台帳という、あれで管理しているから別です。用水はこちらの一般というか、普通財産に入ってくる。そこをうまいぐあいに払い下げていかないと、今後いろいろと問題が出てくるんじゃないかなと思う、それを１点お伺いしたいのと、あと、先ほどの無番地なんですけれども、よくあるので、品川区、これだけ広い中で、あの土地、何なんですかとよく聞かれる。","respondent":"平澤経理課長","answer":"どういったところで、調べるのかですが、これは私有財産のところを勝手に調べるわけにいかないというところもありますので、そういったところでなかなか難しい課題なのかなと思っているところです。","voiceIndex":51,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"教えていただきたいんですが、この書類をつくっていただいてありがとうございました。「所有状況」と書いてあるので、この「所有」というのはどういう意味をあらわしているのかというのを教えていただきたい。具体的に言うと、これ、土地の所有じゃない。こういうのはここにカウントに入っているのか、入っていないのかというのを教えていただきたいのと、例えば船舶中継所みたいなものはどうしているのか。","respondent":"柏原行財政改革担当課長、桑村総務部長、平澤経理課長","answer":"ただ、現在使用しているところでも行政目的として使っているわけですから、それをすぐ何かというのはできないということは思いますけれども。そういう意味では、一定の緑がどこに必要かというのはまた別の考え方がオーソライズされている部分がありますので。箱根荘です。こちらの資料なんですけれども、最初に全体として申し上げましたとおり、３月３１日現在ということで、現在は普通財産となっています。","voiceIndex":53,"id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問","question":"今の話なんだけれども、そうすると、法的に行政財産から普通財産にはできるけれども、例えば公園を取得するときは、お金、簡単に言うと区が負担していないんじゃない。簡単に言うと。私の言い方が違っていたら違っていると言って。行政財産として公園だと。そういうのというので、現実的にとか、物理的には無理だと思うよとかいうのがあるのかというのを改めて教えてください。","respondent":"日下部企画部長","answer":"公園の場合は財調の絡みとか、都市計画交付金の関係というのは、それは別建てになりますけれども、先ほど総務部長がご説明させていただきましたように、これは都市計画法の縛りの関係ということで、ちょっとお金の問題とはまた別です。","voiceIndex":57,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、法律はわかりましたけれども、よく手当てを、補助金が出るわけじゃない、補助金が。それを、法律の問題はあるけれども、補助金は公園以外に何かかえちゃうとか何かするときは、最初のときに補助を出してくれた部分というのは、今、法的な部分は別にして、お金を返さなくていいということなのか、補助の部分は。というのを教えてほしい。","respondent":"日下部企画部長","answer":"補助金の関係、これは実は、ほかの学校の建設、今、起債のお話をしましたけれども、例えば学校の建設のために補助金が大体、今、通常であれば１割ぐらいお金が出ています。それ以外の施設の建設でも、国の補助金とか、都の補助金が出るケースがあります。","voiceIndex":59,"id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、やっぱり古さというのが出てくるじゃないですか、老朽化だから。今、こういう経済状況だったら。それは、世の中が例えば８年後、１０年後どういうふうに変わるかわからないんであれば、それまでの区有地はしっかりそういう収益が上がるような、そういう使い方も一つだし、慌ててぱぱっと建てようよという前に、そういう収入の部分もあるだろうし、いろいろな物事の考え方があると思うんだよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"旧西五反田職員待機寮が売却の募集がされて、広報のホームページには載っておりましたけれども、現状どうなのかということと、今、第３回定例会本会議中ですけれども、第４回定例会本会議の上での契約だ、条例だ、今の、現時点での現状と見通しだけ一応、状況をご説明いただきたいと思います。","respondent":"平澤経理課長","answer":"西五反田の職員待機寮につきましては、今週末、９月２８日が入札申し込みの最終日となっています。一昨日、昨日と２日間にわたりまして、現地説明会を実施しました。全体で９社ほど来ていただきました。現状ということで、以上です。","voiceIndex":67,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5932#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":43395,"voices":69}},{"id":"h24-20120927-17","meetingId":"h24-cm09","date":"2012年9月27日","dateIso":"2012-09-27","committee":"震災対策特別委員会","time":"午前１０時００分～午後３時０４分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"視察にまいりたいと思います。 今日の視察は、品川消防署のご指導、ご協力のもと、スタンドパイプの操法確認を行う予定です。実際に公設消火栓にスタンドパイプを接続して","agenda":"視察にまいりたいと思います。 今日の視察は、品川消防署のご指導、ご協力のもと、スタンドパイプの操法確認を行う予定です。実際に公設消火栓にスタンドパイプを接続して","exchanges":[{"speaker":"阿久津委員","kind":"質問・要望","question":"ご説明ありがとうございました。私からは災害時要援護者について、少しお伺いさせていただきたいと思います。確認ですけれども、名簿登録の対象者が４ページの1)にあるんですが、その中で特に登録を希望する者とあるんですが、これはほんとうに１年じゅう窓口に、防災課のほうに行けば、いつでも登録が大丈夫なんでしょうか。そこのところをまず確認させてください。","respondent":"高山防災計画担当課長","answer":"２点目の障害別の内訳ということに関しましては、申しわけございません、内訳の詳細については手元に資料がございませんが、先ほど申しました重複というのは、要介護と身体障害者の区分の中で重複するものについて、便宜上、要介護のほうに集計する形で。","voiceIndex":7,"id":"exchange-001"},{"speaker":"阿久津委員","kind":"質問・要望","question":"その方につきましては、そういう制度があるんだったらぜひ登録したいということで、私のほうで窓口までお連れして、スムーズに登録をしていただいたんですけれども、例えば、今日は障害者福祉課長もいらっしゃっているのでお伺いしたいんですが、視覚障害に特化してでも結構ですが、どういう形でご案内されているのか、普通に考えると、封書等でお送りされた場合、まず読めるのかというところがありまして。","respondent":"永尾障害者福祉課長","answer":"該当の方に対しては封書で通知をさし上げているところなんですけれども、やはり視覚障害の方は、なかなかそれを読み取るというのは難しいのかなと考えています。","voiceIndex":9,"id":"exchange-002"},{"speaker":"阿久津委員","kind":"意見","question":"こういう特別にＣＤを配るということではなくても、視覚障害者の方には例えば議会の議事録を音声で、希望されて送られている方もいらっしゃると思うんですけれども、定期的にそういうものを送る中にこういう制度のご案内とか、もしくはこういうＣＤ、音声で入るという取り組みを、区のほうもちょっと考えていただけたらと思うんですけれども、その点、お考えをお聞かせください。","respondent":"永尾障害者福祉課長","answer":"最近はいろいろな機器とか便利なものが出てきております。今後そういう、今、八千代市のご案内もございましたけれども、ほかの地域での例とかも参考にしながら、視覚障害者の方への周知について考えていきたいと考えています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"阿久津委員","kind":"質問・要望","question":"民生委員はほんとうに地元のご自分の担当のところを、３.１１のときも必死に回られたということで、今、お話がありました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、ご質問にあったように、この名簿の、今の経過をまず伺えればと思います。このように名簿の協力を要請して、返信を求めた、そして対象者の定義も要綱にはありましたが、どの程度、直近の形でいいんですが、どの程度ご返信があって、そしてまた希望しない理由があればご記入くださいとありましたが、その点の今までの経過を、まず伺えればと思います。","respondent":"高山防災計画担当課長","answer":"原則的には、防災区民組織の代表の方との間の名簿のやりとりということで、その上で個別の支援ができ上がる過程の中で、必要のある範囲内で情報の共有が図られる、このような認識でおります。","voiceIndex":16,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"ありがとうございました。もちろんいろいろな解釈がある中で、これはぜひ、必要最小限で投げかけて終わりではなくて、あるいは立ち位置的な、役職だとか基準というものは明確に示されたほうが、それも方向としたら複数名が情報を共有する必要性があるということで、これは言い切ってしまっていいのではないかと思うんですが、現状とあるいは今後どうなっていくのか、この２点をまたお伺いしたいと思います。","respondent":"高山防災計画担当課長","answer":"実際にお願いをする地域の防災区民組織の方々につきましては、この２月、３月に全町会長の方々に対しまして、改めて要支援者名簿の登録の仕組みについてご説明しまして、情報の取り扱いのあり方でありますとか。","voiceIndex":18,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問・要望","question":"当然想定される時間帯でも違ってくるとは思いますが、基本的な通常の職員配置あるいはプラスアルファの部分はどうなっているのか、通常の職員配置の中で全て対応できるものなのか、あるいは増員があるのか、そんなシミュレーション、また一番大事なのは、そういった中で特に要援護者の方は、ご家族はじめ地域人材の協力体制、これは限られた中でのやりくりになりますが、今どのような基準というか。","respondent":"高山防災計画担当課長","answer":"委員ご指摘の人材といいますか、マンパワーの部分が一番の課題でございまして、運用としましては、もちろん区の職員も行く一方で、やはり高齢者、障害者の方々のご家族でありますとかボランティア、他の地域からの支援というような形での。","voiceIndex":20,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"意見","question":"これは現実問題として、公共施設というのはおそらく区民の方が、災害の規模にもよりますが、当然心も含めたよりどころになるかと思うんですね。限られたスペースの中でいろいろなことがありますが、タイムラグという中でも、逆にいうと先にそこへ入られるケースもあると思うんですね、一般の方が。その辺はどのように考えられているのかなと思います。","respondent":"高山防災計画担当課長","answer":"トリアージということになろうかと思いますが、優先度の高い方を見極めて、一般の一次避難所からそういった属性を持った二次避難所にお移りいただくといった、ある種の選別のような作業が必ず必要になってまいると考えておりますので。","voiceIndex":22,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"はもう実践のお話の中で、例えばその施設が通常開いている、日中を想定した中でもどこでもいいんですが、表示の仕方、あるいは職員が、一般の方がとにかく場を求めていらっしゃったとき、ここは要援護者の方優先ですということを徹底はされるものなんでしょうか。僕は必要だと思うんですね。","respondent":"高山防災計画担当課長","answer":"そうした意味では二次避難所という大きなくくりの中でしか、この間ご説明してこなかったということもありまして、そういった意味では、より二次避難所という性格をわかりやすい形で伝えるような形で、計画の中に盛り込んでいきたいということが一つと。","voiceIndex":24,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど、回答があった中で希望しないという方は、家族の協力者がいるからということなんですが、希望しないという方が、回答者の中で何％あったのかも教えていただきたいと思います。それと、希望者というのが３２２名ですが、どういう人が希望することができるのかということについてもお聞かせください。","respondent":"原高齢者福祉課長、永尾障害者福祉課長、高山防災計画担当課長","answer":"そういった中で、高齢者を含め、名簿の重要性を十分認識した上で、この名簿登録といったところに防災課のほうと連携をして対応をすると。障害の方が少ない理由ということですけれども、いろいろ考えられるかなとは思うんですけれども、先ほど説明のあった。こちらのほうは、先ほどお話しした中で、おおむね回答率は５０％ほどなんですけれども、全体の送付の中で占める割合としてはおおむね２０％ほどの方が。","voiceIndex":28,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、希望できる方は、配偶者の方ということですけれど、それにしても結構、３２２名ということで多いなという思いがしているんですけれど、私、去年の一般質問でも、対象を知的障害、精神障害のところまでぜひ拡大をしてほしいという、知的障害、精神障害の団体の方からもそういう要望を受けていましたし、そういう質問をしたときに、研究をしますという答弁だったんですけれど。","respondent":"原高齢者福祉課長、高山防災計画担当課長","answer":"この事業の周知とともに、名簿に登録されることで、地域の中でどういう動きがあるのかという、そういったことも含めて区民の皆様にお知らせしていくことが大変重要で、登録だけではいざというときには実際に動かないわけですから。先ほどの要件の拡大のお話ですが、現時点で申しますと、この登録については拡大という検討は進めておりませんでして、具体的には現状の要件に該当する方については、知的障害をお持ちの方も取り込まれる形になってございまして。","voiceIndex":32,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それに対して、こういう指針を参考に、地域の実情に応じた対策マニュアル等を整備して、適切な対応をとれるように努めていただきたいということを、東京都も求めているわけですけれど、そういう点で要援護者というのは、先ほど課長が言われたように名簿登録に終わらない支援というのがすごく求められていると思うんですね。","respondent":"鈴木防災課長","answer":"要援護者としてもっと全体の、すべての援護がかかる方への把握と対応というのは、また各課と連携をして検討しておりますので、その部分で対象を拡大しないということではなくて、役割分担を今整理しているという段階です。","voiceIndex":35,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の説明がよく理解できないんですけれども、要援護者の名簿というところは防災課だけがやっていて、それ以外の要援護者に対してどう支援していくかというのは、全庁的にやっていると。ちょっとそこら辺のシステムというか、どういうことが検討されて、どういうふうにしていこうとしているのかというあたりを、もうちょっと全体的なことがわかるような形で説明をお願いします。","respondent":"鈴木防災課長","answer":"防災課の名簿でカバーできない方というのは、各所管課のいろいろな仕組み、ヘルパーさんであるとかそういう中で専門的な対応をする方ということで、分けて対応を考えるという部分を、今、庁内の分科会の検討をもとに調整を進めているところです。","voiceIndex":37,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしましたら、国や東京都が求めているような、要援護者に対してのマニュアルをつくって、平常時はこういうふうな取り組み、例えば横断的なプロジェクトチームをつくって、平常時と災害時という形で国のガイドラインの中にも示していて、平常時は要援護者情報の共有化、避難支援プランの策定、要援護者参加型の防災訓練の計画、実施、広報、災害時は避難情報の伝達業務、避難誘導、安否確認。","respondent":"鈴木防災課長","answer":"ご質問いただきましたように、国のほうの指針でも示されています具体的な所管課、もしくは区全体としての対応のマニュアルですが、現時点は地域防災計画本体の改訂作業を行っているところですが、その中で。","voiceIndex":39,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はそういう品川区としての支援マニュアルをぜひ、計画をつくってほしいということで求めていましたので、そういう方向で進んでいるということでよかったなと思うんですけれど、それはいつぐらいを目途に作成されるのか、ちょっとお聞かせいただきたいのと、私はその中にぜひ当事者も参加する形で作成していくことが、より当事者の大変な実態も反映され。","respondent":"原高齢者福祉課長","answer":"そういった中で現在も検討を進めておりますので、先ほど防災課長が言いましたように、地域防災計画の見直しを受けながら、そういったマニュアルと整合性をとりながら、というところで進めているところです。","voiceIndex":41,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、今年度中ぐらいを目途に、作成を検討しているということで考えていいのかということが一点と。そういうことであれば、私はその一歩先に進んだときに、そういう方も地域の中で組織をして、そして一緒に検討していくというところまでできるといいなと思っているんですけれど、そこら辺の検討というのはいかがでしょうか。","respondent":"原高齢者福祉課長","answer":"東京都なりで先ほど申し上げましたようなガイドライン的なものが出ておりますので、まずそれを品川区に当てはめたときに品川区のこういった状況に合うか合わないか、あるいはできるかできないかというところをあわせながら、現実的にそのまま横引きという考え方ではなくて。","voiceIndex":43,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つお聞きしたいのが、今年初めのプレス発表でも明らかにされましたし、委員会の中でも報告がされました高齢者の福祉避難所の件ですけれど、高齢者受け入れが１０カ所、障害者受け入れが７カ所、合わせて人数としては３４０人分受け入れの福祉避難所をつくっていくということですが、これは障害者の方々からもすごく切実な要望が出ていて。","respondent":"永尾障害者福祉課長","answer":"障害者の関係の福祉的避難所ですけれども、一応、二次避難所としてもともと決められているところは、心身障害者福祉会館と都立品川特別支援学校は、二次避難所として位置づけられているんですけれども、そのほかに区の施設として現在障害者の対応をしている施設に対して。","voiceIndex":45,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、最後にもう一つお聞きしたいのは、そういうことで全体の要援護者に対しての対応、マニュアルとか、そういうところはこれから整備をしていくということなんですが、福祉施設ごとの災害時の対応マニュアルというのは、３.１１でほんとうに機能しなかったというのを現場の声としても聞きまして。","respondent":"原高齢者福祉課長","answer":"各受け入れ施設側でのマニュアルというお尋ねですが、これは受け入れとこちらから区民の方々をご案内するときに、それがそろっていないと機能しませんので、そういう意味ではこちらが今作成中ですので、それができる過程の中で。","voiceIndex":47,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろいろなところと調整をしながらということなんですが、できるだけ早くつくっていただくように、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"要援護者のところから伺いたいんですけれども、一定期間というさっき課長の答弁がありまして、私は毎年やるのかと思っていたら、１月の震災対策特別委員会のところでもこの要援護者のことを議論しているんですけれども、そのときに一定期間は５年だということで、毎年２,５００件程度の新しい名簿に対応しているということで、先ほど委員からもあったんですけれど、私、視覚障害者の方にお話を聞いたら。","respondent":"高山防災計画担当課長","answer":"そういった意味では大きな災害の後ですので、改めてそういうふうな対象者についての声かけについては、予算との関係で調整も含めて検討させていただきたいと考えております。","voiceIndex":50,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"ダイレクトメールと区別がつかない。それで、そういう方たちと話をすると、穴を開けたり何かをする作業ぐらい、自分たちの協会で担ってもいいから、わかるようにしてほしいということだったんですけれど、工夫をしていますと答弁しているけれども、どんな工夫をして、視覚障害者の方たちにこの知らせが届くような配慮をしているのか、具体的に教えてください。","respondent":"永尾障害者福祉課長","answer":"視覚障害者の封書の件ですけれども、区の出すもの全部に対して、そういうことをやるというのはちょっと難しいかなというのが実態ですけれども、こういう災害時要援護者名簿のように、やはり命にかかわるようなものの場合でありましたら。","voiceIndex":52,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"もう一つ、防災区民組織なんですけれども、定義というのが、私はちょっとこの間、防災課長に聞いて驚いたんですけれど、この防災区民組織のメンバーというのは一体誰を位置づけているのか、要綱か条例があるかと思うんですけれど、そこでどんなふうに区が思っているのか教えてください。","respondent":"高山防災計画担当課長","answer":"防災区民組織の定義ですが、こちらは要綱の中で、町会を母体として自主的に結成する組織ということで、基本的には区民が全員入っているという、そういうふうな位置づけにはなります。ただ、中核を担っていただくのはやはり町会、自治会の方々ということにはなろうかと思います。","voiceIndex":54,"id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"やはり町会、自治会の方たちを中心にして流す情報と、そうではない、そこにはちょっと漏れてしまう地域の住民にも、直接アプローチをしていかないといけないと思うんですが、そのことはぜひ、検討とかそれよりも先に進んで、ぜひ実現していただきたいと思うんですが、そこについてはいかがでしょうか。","respondent":"高山防災計画担当課長","answer":"そのほかの方々へのさまざまな啓発につきましては、その他の手法などを交えて検討してまいりたいと考えております。","voiceIndex":56,"id":"exchange-023"},{"speaker":"井上委員","kind":"質問・要望","question":"そうしたときに、やはり昼の避難のシミュレーションだけではなく、シルバーセンターに行きたいと思っても夜はあいていないわけですから、行ってもだめで、だから夜のシミュレーションも、やはり幾つかやっていただいて、ここに児童センターはないんですけれども保健部局もいらっしゃるので、妊婦とか子どもを連れたお母さんたちというのは、割と児童センターとかそういった自分の行きやすいところを利用する。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-024"},{"speaker":"木村委員","kind":"質問","question":"ですからこの１ページ目にも、井上委員が言いましたけれども、防災区民組織をはじめとした地域住民、ボランティア、そういう支援がやはりどうしても不可欠であるということを考えますと、名簿云々よりも、やはりこちらが把握している要援護者に対しては、それに希望しないからどうのこうのということは私はおかしいと思うんですけれど、このことに対してちょっとご説明を願いたいと思います。","respondent":"高山防災計画担当課長","answer":"それ以外の方々の安否の確認とかいうことは、次の方策として講じていくべき事項かと考えております。","voiceIndex":59,"id":"exchange-025"},{"speaker":"木村委員","kind":"質問","question":"確かにプライバシーというものが、私は逆に、かえってそういう意味では問題をややこしくし過ぎているというところもあると思いますし、またそういう意味で防災区民組織、そして警察、消防などがプライバシーをしっかり守っていただいて、ちょっと話が飛びますけれども、回答がなかった方々は、希望するとかしないということを表明しているわけではない、ですからどちらにもとれるということを考えますと。","respondent":"高山防災計画担当課長、永尾障害者福祉課長","answer":"先ほどご説明の中に、希望しない方には希望しない方なりの理由がありまして、それは支援者がいる場合もありますが、やはり障害があるなどの情報を他の方に知ってほしくないといった意向なども考えますと。災害時要援護者名簿は今説明したとおりになっておりますけれども、障害の方の場合だと、その特性の中でやはり希望されない方がいる中で、強制的にやるというのは非常に、心情的にもいいことではないのかなと思います。","voiceIndex":61,"id":"exchange-026"},{"speaker":"武内委員","kind":"質問・要望","question":"お伺いしたいのは４ページのところで、災害時要援護者の名簿関係のところで、先ほど鈴木委員の質問であったのは、知的障害、精神障害等については、庁内の専門分野の検討会みたいなところで、今、対応を検討しているというお話だったんですが、それからまた今、避難所ごとの名簿というお話もあったんですけれども、例えば発達障害と難病、また希少疾病、特に難病対策というのは都道府県の事業ですから。","respondent":"高山防災計画担当課長、福島荏原保健センター所長、永尾障害者福祉課長","answer":"次の段階としてマッチングというところがあるというお話は聞いておりまして、そうした意味では、１つ。もうリストアップもされていまして、今現在は個別支援をどういうぐあいにしたらいいかということを、医療機関。発達障害の件ですけれども、発達障害がやはり一番難しいかなと考えています。","voiceIndex":64,"id":"exchange-027"},{"speaker":"武内委員","kind":"質問・要望","question":"それから問題は、防災計画担当課長からもお話があったんですけれど、１年たっているんですけれどなかなか、でもようやくマッチングまで進んできたということなので、期待はしたいと思うんですけれど、そうするとその中で、資料でいただいた地域の助けあいカード、これは区のほうでつくられたと思うんですけれど、今後こういう形で、これを参考にしていただいて町会の方に個別支援計画をつくっていただく。","respondent":"高山防災計画担当課長","answer":"こうした取り組みは続けつつ、個別支援プランがよりスムーズにでき上がるような方策などについては、引き続き考えてまいりたいと思いますので、よろしくお願いいたします。","voiceIndex":68,"id":"exchange-028"},{"speaker":"武内委員","kind":"質問・要望","question":"これをぜひ品川ナイズしたもの、また障害に応じた内容、何を書けばいいかというのは当然障害の種別によって違うので、団体の方たちにもお聞きした上で効果のあるものをつくっていただいて、もちろん同時並行で個別支援プランもやっていただきながら、そうすることでまだ手が届かない方は何かあったときにそれを見せることで、避難所でもそれを見せることで心ある方が助けてくれる、こういうものも。","respondent":"永尾障害者福祉課長","answer":"緊急的につくったものですので、今後そのヘルプカードのお話も東京都等からお聞きすると思いますので、そういうものも含めて考えていきたいと考えています。","voiceIndex":70,"id":"exchange-029"},{"speaker":"向委員","kind":"確認","question":"ちょっと素朴な質問かもしれないですけれど、この災害時要援護者名簿の調査票を資料でいただいたんですが、これは１パターンだけなんでしょうか。高齢者の方も障害者の方も、これ一部だけしか送付していなくて、例えば高齢者の方用とか、障害者の方もいろいろな方がいらっしゃると思うんですけれど、ちょっとその点だけ確認を先にさせてください。","respondent":"高山防災計画担当課長","answer":"自助・共助・公助のどのような位置づけかですが、これにつきましては共助を引き出す仕組みというふうに考えておりますので、共助というような位置づけになろうかと思います。","voiceIndex":72,"id":"exchange-030"},{"speaker":"向委員","kind":"質問・要望","question":"先日、内閣府の障害者制度改革推進会議の議事録をちょっと見ていて、やはり東日本大震災のときも、例えば福島とかも、支援センターが国とか県とか自治体に名簿を求めたときに、唯一そういった内部的な名簿、ほんとうに行政としてのきちんとした名簿を出してくれたのは南相馬市だけだったというのを拝見したとき、やはりいざというときには、個人情報の法律はありますけれど、個人情報の法律といっても。","respondent":"高山防災計画担当課長","answer":"そのご覚悟はという点ですが、もちろんその災害の規模にもよるかと思いますが、当然生命、身体に危険が及ぶという判断に至った場合には、当然開示する覚悟はあるということで、名簿のほうは運用してまいりたいと思います。","voiceIndex":74,"id":"exchange-031"},{"speaker":"向委員","kind":"質問・要望","question":"ありがとうございました。よくわかりました。ということで、品川区としても共助と公助の部分としては、安心してもいいというようなご回答だったので、ほっとしました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-032"},{"speaker":"大沢委員","kind":"確認","question":"担当の課長は、防災課長は同一で、あと障害者福祉課、高齢者福祉課ということになっておりますけれども、防災の体制云々というよりも、まずこのことについて伺いたいんですが、確かに先ほど来、障害者の方はいろいろな症状の違いがあるということで課長からご答弁をいただいて、さまざまな部分に対応しなければいけないという部分はわかるんですけれども、４ページのほうは事細かにふりがなを振ってある。","respondent":"高山防災計画担当課長","answer":"実は、今日お話しする中で、断片的にしかお話をしてこなかったんですが、毎年、全対象者の方々にお声がけをしているわけではございませんでして、新たに認定を受けた方など、新たに対象になった方に対しましてお声がけをするような仕組みでございまして。","voiceIndex":77,"id":"exchange-033"},{"speaker":"大沢委員","kind":"質問","question":"今、事務改善ということでお話を伺いましたけれども、「災害時要援護者について」のほうの資料の４ページの名簿登録者数というところ、これはへ理屈と言われればそうかもしれないんですけれども、名簿登録対象者、身体障害者手帳所持者のうち肢体不自由者、聴覚障害者、視覚障害者、ここに対象する方たちが、果たしてふりがなが要るものだろうかと。字を読む上において、今の４ページは。","respondent":"永尾障害者福祉課長","answer":"要綱のほうにも書いてあるとは思うんですけれども、知的障害の重複を含むという定義づけになっておりまして、障害者の方は単独の障害だけではなくて、幾つか組み合わさっている方もたくさんいらっしゃいますし、聴覚障害者。","voiceIndex":79,"id":"exchange-034"},{"speaker":"大沢委員","kind":"質問","question":"今は識字率、ほとんど読めるので必要はないと思うんですけれど、何かふりがなを振ってある書類と振っていない書類、おまけに名前まで全部ふりがなが振ってあると、何かこの書類に関して違和感を感じるんですけれども、先ほど事務改善ということでお話を伺いましたけれども、そこの部分の改善の仕方を、私お話ししたんですけれども、何か違和感は感じませんでしょうか。","respondent":"高山防災計画担当課長","answer":"できるだけ多くの方に対してやさしくというようなことからすると、ここまでの必要がないというご意見もあろうかとは思うんですが、こういうものを必要とされている方への対応ということでこういう通知に当たっては。","voiceIndex":81,"id":"exchange-035"},{"speaker":"大沢委員","kind":"質問・要望","question":"ですからここのところは、非常に細かく、やさしくということで心配りは非常によくわかるんですけれども、ちょっと私、違和感を感じるので、今後必要がないというのであれば結構ですけれども、違和感を感じている部分も１人か２人いるのではないかということで、少数意見として聞いていただきたいと思ってお話しさせていただきたいんですけれど、どういうふうにお考えになりますでしょうか。","respondent":"高山防災計画担当課長","answer":"そうした意味では、見直しの視点としてはできるだけ多くの方に伝わりやすい、優しくという視点で、ちょっと直させていただいたものです。ご指摘の点も踏まえて、この登録の案内につきましてはより伝わりやすい内容に、今後も研究してまいりたいと考えております。","voiceIndex":83,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"ワークショップのことについてお伺いしたいんですけれど、地域住民の力で適切に救助、避難誘導、原則としてそういうものを目的としているんですが、皆さんできるだけ名簿に名前を挙げていただいてというお話が今出ているんですけれど、現に町会活動でしっかりとした誘導等ができないと、せっかく名前を挙げていただいても、いざというときに助けられないということもあると私は思うんです。","respondent":"鈴木防災課長","answer":"ワークショップにつきまして、地域のほうで実際に役に立つワークショップをどれぐらい行っているかという、浸透度のお話だと思いますが、実は今年度も先ほどのワークショップと防災アドバイザー研修を実施しておりますが、さらに昨年度の防災アドバイザー研修は１２８名でしたが。","voiceIndex":85,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後の行動に移すことに関して、それと最後までちゃんとフォローをして、ちゃんと皆さんが習得できているかということ、せっかく名乗りを上げていただいているんですから、はっきり言って車いすを押すことも、結構大変な作業だと思うんですが、やったことのない方がいっぱいいらして、町会活動も、私は自分の町会、周りの町会しかわからないんですけれど、活動を一生懸命やっていらっしゃる方もいますが。","respondent":"鈴木防災課長","answer":"ご意見いただきましたように、実際に地域の方たちの意識、またその実行するための必要な知識、これは不可欠なものですので、ご指摘ありましたように、今までの研修、もしくはそれ以外のいろいろな啓発の機会を捉えまして、さらに浸透させて拡大していく方向で。","voiceIndex":87,"id":"exchange-038"},{"speaker":"高橋委員","kind":"質問","question":"どなたかが聞いたかもしれないですけれど、ちょっと実務的なところで、実際にこのご案内を出して返信が来て、名簿を具体的につくられるのは防災課のお仕事ということでよろしいんでしょうか。","respondent":"鈴木防災課長","answer":"ご質問のとおり、通知の発送、その受理、それを名簿に登録する作業については、防災課のほうで担当しております。","voiceIndex":89,"id":"exchange-039"},{"speaker":"高橋委員","kind":"意見","question":"ではちょっと細かいですが、先ほどのご案内は２種類あって、片方は防災課が上になっていて、片方は防災課が下になっていて、問い合わせ先に防災課の宛先がないんですけれど、障害者福祉課のほうがいろいろ把握しているので、そこが窓口になってつくるのかなと勝手に思っていたんですけれど、今のお話だと防災課がつくるということなので、障害者関係のほうのご案内は防災課の問い合わせ先がないので、もし。","respondent":"高山防災計画担当課長","answer":"実はこの問い合わせ先も、いろいろと配慮といいますか、区としても考えた上での問い合わせ先ということでございまして、障害者の方向けのものに防災課が載っていないというのは、やはり日ごろ窓口などでかかわりのある障害者福祉課を窓口としたほうが。","voiceIndex":91,"id":"exchange-040"},{"speaker":"沢田委員","kind":"質問","question":"避難誘導ワークショップと防災アドバイザーのことについてお伺いしたいんですけれども、どちらも６年前からやられているということですけれども、今回の東日本大震災を受けて、いろいろな状況が変わってきているかと思うんですけれども、平成２３年度というのはその状況を受けての避難誘導ワークショップだったり、防災アドバイザー研修であったかと思うんですけれども。","respondent":"鈴木防災課長","answer":"このステップアップ研修のほうは、今年度も実施しましたが来年度以降も継続していきますので、まだ過去の防災アドバイザー研修修了者でステップアップを受講されていない方、また今年度以降防災アドバイザー研修を受ける方も、引き続きこのステップアップ研修で。","voiceIndex":94,"id":"exchange-041"},{"speaker":"沢田委員","kind":"質問・要望","question":"それと、先ほどもちょっとお話がありましたけれど、避難誘導ワークショップのほうですけれども、実施の町会数ということで、以前やられているところもあるのかもしれないですけれど、状況的に減ってきているのかなという感じがしますけれども、この辺は町会としてはそれぞれ、以前もやっているし、それぞれの町会等でやっているかと思うんですけれども、この辺に関しては。","respondent":"高山防災計画担当課長","answer":"もう一つ、ワークショップ単独でやる場合もあるんですが、避難所を運営する訓練に合わせてやるという町会、自治会も多いものですから、そういった機会を捉えて、引き続き、区としてもワークショップの実施回数が増えていくよう、働きかけをしてきたいと考えております。","voiceIndex":96,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺の改めての確認と、そういうことで考えたとき、精神障害者と知的障害者の方が入っていなくて、そこも検討されていないということなんですが、知的障害者と精神障害者の方で移動に支援が必要な人は、いないということで捉えてしまっていいのかなという思いがあるんですけれど、精神障害者の方でも結構。","respondent":"福島荏原保健センター所長、高山防災計画担当課長","answer":"精神障害の患者につきましては、まだ名簿というのはでき上がっていませんけれど、保健師が地区活動の中で携わっている精神障害の患者については、今検討してリストをつくろうというところまでは進んでいるということです。安否を確認する体制についてですが、現実問題として区の職員だけで対応することはできませんので、一つには地域の力を活用するでありますとか、あるいは災害時の公的な機関の助けであるとか。","voiceIndex":98,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それとあわせて、要介護者の方の名簿というのも避難所ごとに整理されて、要介護者、障害者すべての名簿が避難所ごとに整備されて、安否確認や支援を行っていく、そういう前提としての名簿ができて、支援や安否確認がされていくという方向で進められているということで確認をさせていただいていいのか、ちょっとお聞かせください。","respondent":"永尾障害者福祉課長、原高齢者福祉課長","answer":"障害者の部分につきましては手帳を持っている方すべてがその名簿に載っておりますので、身体障害だけでなくて、知的障害も精神障害者保健福祉手帳も含まれております。これからマニュアルをつくる上で、もう最初からこの方は福祉避難所にご案内したほうがいいという方については、安否を確認する中でこちらにということもありましょうし、そこがどのぐらい個別支援計画の中で捉え切れるか。","voiceIndex":101,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つは、そういうふうに名簿ができたとき、この方がこの避難所で生活をしている、それでどんな支援が必要かというところが見えて、ぜひ届くような支援をしていただきたいと思うんですけれど、それとあわせて、避難所ではほんとうに生活が困難で、結局、倒れかかった自宅に戻らざるを得ない状況がたくさんあったというのが。","respondent":"永尾障害者福祉課長","answer":"それは障害者だけでなくて、高齢者もそうだし、その方個々の状況によって決まってくるのかなと思っているので、一概に最初から決めることは難しいかもしれないんですけれども、現在、防災課のほうとも協議をしながら、マニュアルもつくっているところですので。","voiceIndex":104,"id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろいろと検討しているところだと思うんですけれど、早急に検討を進めていただきたいということと、やはり今までそういう形で大変な状況があったということを、どう教訓にして生かしていくかということがすごく大事だと思うんですけれど、この推進会議の中で、日ごろから行政が障害者別ごとにどのような支援が必要かということを、障害者団体と協議をしてマニュアルを作成し。","respondent":"永尾障害者福祉課長","answer":"区内の障害者の団体の方とも懇談会を定期的に行っておりまして、その中のご意見も聞いておりますので、そういうのも参考に、また品川区全体として一つになってやっていかなければいけないので、防災課とも連携して考えていきたいと考えています。","voiceIndex":106,"id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"障害者の方、高齢者の方、ほんとうに一番弱者のところに、こういう災害のときには困難が一番いくと思いますので、そこのところの対策というところで、全庁を挙げて検討して、対策をとっていただくようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-047"},{"speaker":"武内委員","kind":"確認","question":"すみません、今ちょっと鈴木委員の質疑のところで、ちょっと気になったので一点確認なんですけれども、精神障害者の状況だけれど手帳を持っていないかとかは、今おっしゃったようになかなか区のほうで把握できないという状況があるんですけれど、例えばそういう方とか、またはそうではなくて手帳を持っている方でも、この名簿化されるに当たって希望されれば、どこかからお話を聞いて。","respondent":"鈴木防災課長","answer":"ご質問いただきました名簿登録者の要件に入っていない方、手帳を持っていない方とかの場合ですが、先ほどの名簿登録の対象者にありますように、特に登録を希望する方という項目がありますので、具体的に個別に相談をいただいて、その方への支援の内容とか特性によりますが。","voiceIndex":109,"id":"exchange-048"},{"speaker":"井上委員","kind":"質問","question":"資料４ページの3)名簿登録者の内訳というところですが、この割合というのは、３,４４６名に対しての割合だというふうに思うんですが、区が考えている対象者に対しての登録者の割合というのを把握されていたら、教えてください。","respondent":"高山防災計画担当課長","answer":"そういう意味では、おおむね１万人程度の方が、要介護、身体障害を合わせて１万人程度が最大分母だと思いますが、その中で３,５００名弱という登録ですので、おおむね登録率としては３割というような把握で考えております。","voiceIndex":111,"id":"exchange-049"},{"speaker":"井上委員","kind":"質問","question":"先ほど答弁の中で、要介護１から５だと大体４,０００人ぐらいで、身体障害者のほうは前回の議事録なども見ると６,５００人ぐらいだというふうに答えていただいているようですが、そのぐらいでよしとしたらいいでしょうか。","respondent":"原高齢者福祉課長、永尾障害者福祉課長、鈴木防災課長","answer":"ただ、要支援の方とかもいらっしゃいますので、そういった方々を入れれば７,０００人と、そういうふうな数字になってきます。６,５００人という数字ですけれども、今年の１月の震災対策特別委員会のときの答弁になっておりますけれども。申しわけありません、ただいまご質問いただいた各登録者の内訳のお話、資料の４ページになりますが。","voiceIndex":113,"id":"exchange-050"},{"speaker":"阿久津委員","kind":"質問・要望","question":"１点だけ。先ほどの質疑を聞いていて、１つだけ要望を込めた質問なんですけれども、先ほど大沢委員から登録のご案内に違和感があるというお話があって、私もちょっと違和感があったので、それは何なのかなとずっと今まで考えていて、質疑の中で思い出したこともあって。","respondent":"鈴木防災課長","answer":"今後もご意見いただきましたように、さらに重要性を認識していただいて、登録に手を挙げていただけるような情報提供も、あわせて改善していきたいと思います。","voiceIndex":117,"id":"exchange-051"},{"speaker":"渡辺委員","kind":"提案","question":"今のとりまとめの方法なんですが、今この場でというよりは、何日後に締め切りを設けていただいて、出する方式のほうがまとまりやすいかなと思ったので。そういう提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-052"},{"speaker":"井上委員","kind":"提案","question":"今日みたいな形で短時間で構わないと思うんですけれども、前回、避難所運営に関しての議論があったとき、やはり教育委員会で、学校の施設管理者としてどういうふうに避難所を防災部局と一緒に検討していただけるのかというところが、やはり現場の声がわからなかったので、ぜひ終わるまでにどこかで調整をいただいて、やはりこれは外せないなと思っているので、運営も区の職員なのか。","respondent":"南委員長","answer":"そうしましたら正副で検討して、ご連絡するようにいたします。その他を終了していいですか。","voiceIndex":137,"id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6418#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":50339,"voices":139}}]);
